  // Detecta a categoria de perfil ERP ativa a partir do usuário logado
  window.obterCategoriaPerfilAtivo = function(userObj) {
    const u = userObj || (typeof window.currentLoggedUser !== 'undefined' ? window.currentLoggedUser : null);
    if (!u) return 'Master';

    // Se houver override temporário de visualização no perfil Master ou salvo para o usuário
    if (u.categoriaErpAtiva && window.CATEGORIAS_PERFIL_ERP[u.categoriaErpAtiva]) {
      return u.categoriaErpAtiva;
    }

    const p = String(u.perfil || '').trim();
    const func = String(u.funcao || '').toLowerCase();
    const login = String(u.usuario || '').toLowerCase();

    if (p === 'Master' || ['admin', 'henrique', 'henriquecamilo', 'robson', 'camila'].includes(login)) {
      return 'Master';
    }
    if (p === 'Vendedor' || login === 'vendedor' || func.includes('vendedor') || func.includes('comercial') || func.includes('orçament')) {
      return 'Vendedor';
    }
    if (p === 'RH' || login === 'jennifer' || (func.includes('rh') && !func.includes('finan'))) {
      return 'RH';
    }
    if (p === 'Financeiro' || func.includes('financeir')) {
      return 'Financeiro';
    }
    if (p === 'Engenharia' || p === 'Estagiário Engenharia' || func.includes('engenheir') || func.includes('estagi')) {
      return 'Engenharia';
    }
    if (p === 'Administrativo Amplo') {
      if (login === 'leonardo' || login === 'edson') return 'RH';
      if (login === 'leticia') return 'Vendedor';
      return 'Financeiro';
    }
    return 'Engenharia';
  };

  // Verifica se o perfil atual tem permissão para acessar determinada seção/subseção
  window.verificarPermissaoModuloPorPerfil = function(secao, subsecao, userObj) {
    const u = userObj || window.currentLoggedUser;
    const cat = window.obterCategoriaPerfilAtivo(u);

    if (cat === 'Master') return true;

    // Restrição estrita por empresa (ex: José Henrique apenas emp-2)
    if (u && u.usuario === 'josehenrique' && Array.isArray(u.empresas) && !u.empresas.includes('emp-1')) {
      if (secao === 'usuarios' || secao === 'financeiro') return false;
    }

    // Regras estritas da categoria Vendedor
    if (cat === 'Vendedor') {
      const bloqueadosVendedor = ['financeiro', 'colaboradores', 'usuarios', 'cadastros', 'portal', 'conferencia'];
      if (bloqueadosVendedor.includes(secao)) return false;
      if (secao === 'suprimentos' && subsecao && !['estoque', 'pedidos'].includes(subsecao)) {
        return false; // Vendedor consulta apenas produtos/estoque disponível e pedidos
      }
      return ['painel', 'comercial', 'suprimentos'].includes(secao);
    }

    // Regras de segurança para configurações exclusivas Master
    if (secao === 'usuarios') return false;
    if (secao === 'financeiro' && (subsecao === 'permissoes' || subsecao === 'conciliacao')) return false;

    if (cat === 'RH') {
      if (secao === 'financeiro') return false;
      return true;
    }

    if (cat === 'Engenharia') {
      if (secao === 'financeiro' && subsecao !== 'gastos-obra') return false;
      return true;
    }

    return true;
  };

  // Permite trocar rapidamente o perfil ativo (para testes de homologação ou alternância de visão)
  window.alternarPerfilVisualizacaoErp = function(novaCategoria) {
    if (!window.CATEGORIAS_PERFIL_ERP[novaCategoria]) return false;

    if (!window.currentLoggedUser) {
      const users = typeof window.getUsuariosDb === 'function' ? window.getUsuariosDb() : [];
      window.currentLoggedUser = users[0] || {
        id: 'USR-01',
        usuario: 'admin',
        nome: 'Henrique Camilo',
        perfil: novaCategoria,
        empresas: ['emp-1', 'emp-2', 'emp-3']
      };
    }

    window.currentLoggedUser.categoriaErpAtiva = novaCategoria;
    // Se for teste direto de perfil, sincroniza o atributo perfil quando aplicável
    if (['Master', 'RH', 'Engenharia', 'Financeiro', 'Vendedor'].includes(novaCategoria)) {
      window.currentLoggedUser.perfil = novaCategoria;
    }

    try {
      sessionStorage.setItem('cm_active_user', JSON.stringify(window.currentLoggedUser));
    } catch (e) {}

    if (typeof window.atualizarInterfaceUsuario === 'function') {
      window.atualizarInterfaceUsuario();
    }
    window.renderizarMenuRapidoPersonalizado();
    window.renderizarBarraInferiorPorPerfil();
    window.renderizarBotaoAcoesRapidasPerfil();
    if (typeof window.renderizarMenuLateralInteligente === 'function') {
      window.renderizarMenuLateralInteligente();
    }
    if (typeof window.renderizarDashboardExecutivo === 'function') {
      window.renderizarDashboardExecutivo();
    }

    if (typeof showToast === 'function') {
      showToast(`✅ Ambiente adaptado para o perfil: ${window.CATEGORIAS_PERFIL_ERP[novaCategoria].titulo}`);
    }
    return true;
  };

