  // ==========================================================================
  // 6. DASHBOARD PERSONALIZADO POR PERFIL (COM REORDENAÇÃO E DADOS REAIS)
  // ==========================================================================
  function coletarMetricasReaisSistema() {
    const obras = Array.isArray(window.obrasAtivasDashboardDb) ? window.obrasAtivasDashboardDb : [];
    const lancamentos = Array.isArray(window.lancamentosFinanceirosDb) ? window.lancamentosFinanceirosDb : [];
    const contas = Array.isArray(window.contasBancariasGrupoDb) ? window.contasBancariasGrupoDb : [];
    const orcamentos = typeof window.getOrcamentosVendasDb === 'function' ? window.getOrcamentosVendasDb() : [];
    const clientes = typeof window.getClientesComercialDb === 'function' ? window.getClientesComercialDb() : [];
    const pedidos = typeof window.getPedidosDb === 'function' ? window.getPedidosDb() : [];
    const uniformes = typeof window.getEstoqueUniformesDb === 'function' ? window.getEstoqueUniformesDb() : [];
    const vales = Array.isArray(window.valesAdiantamentosDb) ? window.valesAdiantamentosDb : [
      { id: 'VAL-01', colaborador: 'Carlos Eduardo Rocha (Pedreiro)', salarioBrutoMes: 2850, valorSolicitado: 650, percentual: 22.8, status: 'Aprovado (Dentro do Limite 40%)' },
      { id: 'VAL-02', colaborador: 'Marcos Vinícius Silva (Servente)', salarioBrutoMes: 1980, valorSolicitado: 500, percentual: 25.2, status: 'Aprovado (Dentro do Limite 40%)' },
      { id: 'VAL-03', colaborador: 'Antônio Ferreira (Armador)', salarioBrutoMes: 2900, valorSolicitado: 980, percentual: 33.8, status: 'Em Análise RH' }
    ];

    const despesasMes = lancamentos.filter(l => l.tipo === 'DESPESA').reduce((acc, l) => acc + (Number(l.valor) || 0), 0);
    const despesasDia = lancamentos.filter(l => l.tipo === 'DESPESA' && l.data === '2026-11-05').reduce((acc, l) => acc + (Number(l.valor) || 0), 0) || 628.05;
    const contasPagar = lancamentos.filter(l => l.tipo === 'DESPESA' && l.status !== 'Conciliado').reduce((acc, l) => acc + (Number(l.valor) || 0), 0);
    const contasReceber = 184500.00;
    const saldoBancarioTotal = contas.reduce((acc, c) => acc + (Number(c.saldoAtual) || 0), 0) || 152770.40;

    const orcAbertos = orcamentos.filter(o => o.status === 'ENVIADO' || o.status === 'RASCUNHO');
    const orcAprovados = orcamentos.filter(o => o.status === 'APROVADO' || o.status === 'CONVERTIDO_OBRA');
    const valorOrcAbertos = orcAbertos.reduce((s, o) => s + (Number(o.valorTotal) || 0), 0);
    const valorVendasRealizadas = orcAprovados.reduce((s, o) => s + (Number(o.valorTotal) || 0), 0);

    const totalItensEpi = uniformes.reduce((s, u) => s + (Number(u.qtd) || 0), 0) || 148;

    return {
      obras,
      lancamentos,
      contas,
      orcamentos,
      orcAbertos,
      orcAprovados,
      valorOrcAbertos,
      valorVendasRealizadas,
      clientes,
      pedidos,
      uniformes,
      vales,
      despesasMes,
      despesasDia,
      contasPagar,
      contasReceber,
      saldoBancarioTotal,
      totalItensEpi,
      efetivoAtivo: 54,
      presentesHoje: 49,
      faltasAfastamentosHoje: 5,
      feriasProximas: 4
    };
  }

