  function obterChaveStorageDashboardCards() {
    const u = window.currentLoggedUser || { usuario: 'admin' };
    const cat = window.obterCategoriaPerfilAtivo(u);
    return `cm_dash_cards_pref_${u.usuario || 'admin'}_${cat}`;
  }

  window.obterConfigCartoesDashboardUsuario = function() {
    const cat = window.obterCategoriaPerfilAtivo();
    const padrao = (window.DEFINICAO_CARTOES_DASHBOARD_PERFIL[cat] || window.DEFINICAO_CARTOES_DASHBOARD_PERFIL.Master).map(c => ({
      ...c,
      visivel: true
    }));

    try {
      const salvo = localStorage.getItem(obterChaveStorageDashboardCards());
      if (!salvo) return padrao;
      const parsed = JSON.parse(salvo);
      if (!Array.isArray(parsed) || parsed.length === 0) return padrao;

      const mapa = {};
      padrao.forEach(p => { mapa[p.id] = p; });
      const res = [];
      parsed.forEach(item => {
        if (mapa[item.id]) {
          res.push({ ...mapa[item.id], visivel: item.visivel !== false });
          delete mapa[item.id];
        }
      });
      Object.values(mapa).forEach(r => res.push(r));
      return res;
    } catch (e) {
      return padrao;
    }
  };

  window.salvarConfigCartoesDashboardUsuario = function(lista) {
    try {
      localStorage.setItem(obterChaveStorageDashboardCards(), JSON.stringify(lista.map(c => ({ id: c.id, visivel: c.visivel !== false }))));
    } catch (e) {}
  };

  window.reordenarCartaoDashboard = function(cardId, direcao) {
    const lista = window.obterConfigCartoesDashboardUsuario();
    const idx = lista.findIndex(c => c.id === cardId);
    if (idx === -1) return;
    const novoIdx = idx + direcao;
    if (novoIdx < 0 || novoIdx >= lista.length) return;
    const tmp = lista[idx];
    lista[idx] = lista[novoIdx];
    lista[novoIdx] = tmp;
    window.salvarConfigCartoesDashboardUsuario(lista);
    window.renderizarDashboardExecutivo();
  };

  window.alternarVisibilidadeCartaoDashboard = function(cardId) {
    const lista = window.obterConfigCartoesDashboardUsuario();
    const visiveis = lista.filter(c => c.visivel !== false);
    const alvo = lista.find(c => c.id === cardId);
    if (!alvo) return;
    if (alvo.visivel !== false && visiveis.length <= 1) {
      if (typeof showToast === 'function') showToast('⚠️ Mantenha ao menos 1 cartão visível no Dashboard.');
      return;
    }
    alvo.visivel = !(alvo.visivel !== false);
    window.salvarConfigCartoesDashboardUsuario(lista);
    window.renderizarDashboardExecutivo();
  };

  window.restaurarDashboardPadrao = function() {
    try {
      localStorage.removeItem(obterChaveStorageDashboardCards());
    } catch (e) {}
    window.renderizarDashboardExecutivo();
    if (typeof showToast === 'function') showToast('🔄 Layout do Dashboard restaurado para o padrão do perfil.');
  };

