  window.obterHistoricoHoleritesDb = function() {
    try {
      const raw = localStorage.getItem('cm_historico_holerites_emitidos_db');
      return raw ? JSON.parse(raw) : [];
    } catch (e) {
      return [];
    }
  };

  window.salvarHistoricoHoleritesDb = function(lista) {
    try {
      localStorage.setItem('cm_historico_holerites_emitidos_db', JSON.stringify(lista));
    } catch (e) {}
  };

  // ==========================================================================
  // 4. INTEGRAÇÃO COM A FREQUÊNCIA (ITEM 19.E) — SEM ALTERAR REGISTROS DE PONTO
  // ==========================================================================
  window.apurarFrequenciaColaboradorCompetencia = function(colab, competenciaYm) {
    const comp = String(competenciaYm || '2026-11').trim();
    const freqDb = typeof window.getFrequenciaDiariaDb === 'function' ? window.getFrequenciaDiariaDb() : {};
    const feriados = typeof window.getFeriadosPassosDb === 'function' ? window.getFeriadosPassosDb() : {};
    const rdosDb = typeof window.getDb === 'function' ? window.getDb() : [];

    let diasTrabalhados = 0;
    let meioPeriodoCount = 0;
    let faltasInjustificadas = 0;
    let atestadosMedicos = 0;
    let feriasDias = 0;
    let folgasCompensadas = 0;
    let afastamentosLegais = 0;
    let atrasosMinutosTotal = 0;
    let horasExtrasAutorizadas = 0;
    const obrasDias = {};
    const divergencias = [];

    // 1. Varre os registros oficiais da Frequência Diária (SOMENTE LEITURA — nunca altera a frequência)
    Object.keys(freqDb).sort().forEach(dataIso => {
      if (!dataIso.startsWith(comp)) return;
      const folhaDia = freqDb[dataIso];
      if (!folhaDia) return;

      const reg = folhaDia[colab.id] || Object.values(folhaDia).find(r =>
        (r.colabId && r.colabId === colab.id) ||
        (r.nome && colab.nome && r.nome.trim().toLowerCase() === colab.nome.trim().toLowerCase()) ||
        (r.colabNome && colab.nome && r.colabNome.trim().toLowerCase() === colab.nome.trim().toLowerCase())
      );

      if (!reg) return;

      const dtObj = new Date(dataIso + 'T12:00:00');
      const dSem = dtObj.getDay();
      const isFdsOuFeriado = Boolean(feriados[dataIso]) || dSem === 0 || dSem === 6;
      const st = String(reg.status || '').toLowerCase();

      if (st === 'presente') {
        diasTrabalhados += 1;
        const ob = reg.obra || colab.obra || 'UBS - Nova Passos';
        obrasDias[ob] = (obrasDias[ob] || 0) + 1;
      } else if (st === 'meio_periodo' || st === 'meio-periodo') {
        diasTrabalhados += 0.5;
        meioPeriodoCount += 1;
        const ob = reg.obra || colab.obra || 'UBS - Nova Passos';
        obrasDias[ob] = (obrasDias[ob] || 0) + 0.5;
      } else if (st === 'falta') {
        // Não presume desconto em feriado ou fim de semana se lançado indevidamente
        if (isFdsOuFeriado) {
          divergencias.push(`Falta apontada em feriado/fim de semana (${dataIso}) — classificada para conferência sem desconto automático.`);
        } else if (reg.justificada === true || String(reg.obs || '').toLowerCase().includes('abonad')) {
          folgasCompensadas += 1;
        } else {
          faltasInjustificadas += 1;
        }
      } else if (st === 'atestado') {
        atestadosMedicos += 1;
      } else if (st === 'ferias' || st === 'férias') {
        feriasDias += 1;
      } else if (st === 'afastado' || st === 'afastamento' || st === 'licenca') {
        afastamentosLegais += 1;
      } else if (st === 'folga' || st === 'feriado' || st === 'chuva') {
        folgasCompensadas += 1;
      }

      if (Number(reg.horasExtras) > 0 && reg.horasExtrasAutorizadas !== false) {
        horasExtrasAutorizadas += Number(reg.horasExtras);
      } else if (Number(reg.horas || reg.horasTotais) > 8) {
        horasExtrasAutorizadas += (Number(reg.horas || reg.horasTotais) - 8);
      }

      if (Number(reg.atrasoMinutos) > 0) {
        atrasosMinutosTotal += Number(reg.atrasoMinutos);
      }
    });

    // 2. Verifica RDOs da competência para complementar presença e apontar divergências entre Ponto e RDO
    rdosDb.forEach(rdo => {
      if (!rdo.data || !rdo.data.startsWith(comp)) return;
      const achouTrab = Array.isArray(rdo.trabalhadores) && rdo.trabalhadores.find(t =>
        t.nome && colab.nome && t.nome.trim().toLowerCase() === colab.nome.trim().toLowerCase()
      );
      const regFreqDia = freqDb[rdo.data] && (freqDb[rdo.data][colab.id] || Object.values(freqDb[rdo.data]).find(x => (x.nome || x.colabNome) === colab.nome));

      if (achouTrab && !regFreqDia) {
        diasTrabalhados += 1;
        const ob = rdo.obra || colab.obra || 'UBS - Nova Passos';
        obrasDias[ob] = (obrasDias[ob] || 0) + 1;
        if (Number(achouTrab.horas) > 8) {
          horasExtrasAutorizadas += (Number(achouTrab.horas) - 8);
        }
      } else if (achouTrab && regFreqDia && String(regFreqDia.status).toLowerCase() === 'falta') {
        divergencias.push(`Divergência em ${rdo.data}: consta PRESENTE no RDO Nº ${rdo.num} (${rdo.obra}), mas consta FALTA na Frequência.`);
      }
    });

    // Caso a competência esteja em andamento e não haja lançamentos diários salvos ainda para o colaborador ativo,
    // utiliza a base operacional acumulada na varredura ou padrão de 20 dias trabalhados para permitir apuração e testes
    if (diasTrabalhados === 0 && faltasInjustificadas === 0 && atestadosMedicos === 0 && feriasDias === 0 && colab.status !== 'Inativo') {
      const scanGlobal = typeof window.escanearFrequenciaColaborador === 'function' ? window.escanearFrequenciaColaborador(colab) : null;
      if (scanGlobal && scanGlobal.diasTrabalhados > 0) {
        diasTrabalhados = scanGlobal.diasTrabalhados;
        faltasInjustificadas = Array.isArray(scanGlobal.faltasLista) ? scanGlobal.faltasLista.length : 0;
        atestadosMedicos = Array.isArray(scanGlobal.atestadosLista) ? scanGlobal.atestadosLista.length : 0;
        Object.assign(obrasDias, scanGlobal.obrasContagem || {});
      } else {
        diasTrabalhados = 20;
        const obPadrao = (colab.obra && colab.obra !== 'Rotativo' && colab.obra !== 'Todas as Obras') ? colab.obra : 'UBS - Nova Passos';
        obrasDias[obPadrao] = 20;
      }
    }

    // Calcula rateio percentual por obra com base nos dias efetivamente trabalhados em cada canteiro
    const totalDiasObras = Object.values(obrasDias).reduce((a, b) => a + b, 0) || diasTrabalhados || 1;
    const rateioObras = Object.entries(obrasDias).map(([obraNome, dias]) => ({
      obra: obraNome,
      dias,
      percentual: arredondar2((dias / totalDiasObras) * 100)
    }));
    if (rateioObras.length === 0) {
      rateioObras.push({ obra: colab.obra && colab.obra !== 'Rotativo' ? colab.obra : 'UBS - Nova Passos', dias: diasTrabalhados, percentual: 100 });
    }

    return {
      competencia: comp,
      diasTrabalhados: arredondar2(diasTrabalhados),
      meioPeriodoCount,
      faltasInjustificadas,
      atestadosMedicos,
      feriasDias,
      folgasCompensadas,
      afastamentosLegais,
      atrasosMinutosTotal,
      horasExtrasAutorizadas: arredondar2(horasExtrasAutorizadas),
      obrasDias,
      obraPrincipal: rateioObras[0].obra,
      rateioObras,
      divergencias,
      possuiDivergencia: divergencias.length > 0
    };
  };

  // ==========================================================================
  // 5. MOTOR DE CÁLCULO DA FOLHA DE PAGAMENTO (ITEM 19.A, 19.C, 19.D)
  // ==========================================================================
  window.calcularFolhaIndividualColaborador = function(colab, competenciaYm = '2026-11') {
    const comp = String(competenciaYm || '2026-11').trim();
    const rem = window.obterDadosRemuneracaoColaborador(colab);
    const freq = window.apurarFrequenciaColaboradorCompetencia(colab, comp);
    const ajustesMap = window.obterAjustesFolhaDb();
    const chaveAjuste = `${comp}__${colab.id}`;
    const ajuste = ajustesMap[chaveAjuste] || {};

    const diasTrab = ajuste.diasTrabalhados !== undefined ? Number(ajuste.diasTrabalhados) : freq.diasTrabalhados;
    const faltasDescontaveisQtd = ajuste.faltasDescontaveisQtd !== undefined
      ? Number(ajuste.faltasDescontaveisQtd)
      : (ajuste.abonarFaltas ? 0 : freq.faltasInjustificadas);

    const horasExtrasQtd = ajuste.horasExtrasQtd !== undefined ? Number(ajuste.horasExtrasQtd) : freq.horasExtrasAutorizadas;
    const atrasosMinutos = ajuste.atrasosMinutos !== undefined ? Number(ajuste.atrasosMinutos) : freq.atrasosMinutosTotal;

    const ehDiarista = rem.regimePagamento.toLowerCase().includes('diarista');

    // Valor Bruto Trabalhado no Período (para cálculo da folha e do limite de 40% de vales)
    const valorBrutoTrabalhadoPeriodo = ehDiarista
      ? arredondar2(diasTrab * rem.diariaBase)
      : arredondar2((rem.salarioBase / 30) * Math.min(30, diasTrab + freq.folgasCompensadas + freq.atestadosMedicos + freq.feriasDias));

    // Remuneração-base considerada na competência
    const proventoBase = ehDiarista ? valorBrutoTrabalhadoPeriodo : rem.salarioBase;

    // Desconto de faltas e atrasos:
    // Regra 19.A: Não presumir que toda falta, folga ou afastamento gera desconto.
    // Atestados médicos, férias, folgas compensadas e faltas abonadas NÃO geram desconto salarial.
    const descontoFaltasValor = ehDiarista
      ? 0 // Diarista recebe pelos dias efetivamente trabalhados, salvo falta contratual expressa
      : arredondar2(faltasDescontaveisQtd * (rem.salarioBase / 30));

    const descontoAtrasosValor = arredondar2((atrasosMinutos / 60) * rem.valorHoraNormal);
    const totalFaltasEAtrasosValor = arredondar2(descontoFaltasValor + descontoAtrasosValor);

    // Horas extras autorizadas (acréscimo legal padrão de 50%)
    const fatorHoraExtra = Number(ajuste.fatorHoraExtra || 1.5);
    const valorHorasExtras = arredondar2(horasExtrasQtd * rem.valorHoraNormal * fatorHoraExtra);

    // Adicionais e benefícios cadastrados (Cesta Básica / Vale Alimentação / Adicional)
    // Se não teve faltas injustificadas, recebe benefício cesta/assiduidade
    const outrosProventosPadrao = arredondar2(rem.adicionalPericulosidadeInsalubridade + (faltasDescontaveisQtd === 0 ? rem.beneficioValeAlimentacao : 0));
    const outrosProventos = ajuste.outrosProventos !== undefined ? arredondar2(Number(ajuste.outrosProventos)) : outrosProventosPadrao;

    // Vales e adiantamentos concedidos na competência (evitando duplicidades)
    const todosVales = window.obterValesAdiantamentosDb();
    const valesColabPeriodo = todosVales.filter(v =>
      (v.colabId === colab.id || (v.colabNome && colab.nome && v.colabNome.trim().toLowerCase() === colab.nome.trim().toLowerCase())) &&
      String(v.competencia || v.data || '').startsWith(comp) &&
      ['Aprovado', 'Pago Antecipadamente', 'Descontado em Folha'].includes(v.situacao)
    );

    const totalValesDescontar = arredondar2(
      valesColabPeriodo.reduce((acc, v) => acc + (Number(v.valorConcedido ?? v.valorSolicitado ?? v.valor) || 0), 0)
    );

    const totalValesJaPagosNoCaixa = arredondar2(
      valesColabPeriodo.filter(v => v.pagoNoCaixa !== false).reduce((acc, v) => acc + (Number(v.valorConcedido ?? v.valorSolicitado ?? v.valor) || 0), 0)
    );

    // Limite acumulado de 40% sobre o valor bruto efetivamente trabalhado no período (Regra 19.D)
    const limiteTotalVales40 = arredondar2(valorBrutoTrabalhadoPeriodo * 0.40);
    const limiteDisponivelNovosVales = Math.max(0, arredondar2(limiteTotalVales40 - totalValesDescontar));

    // Encargos legais (INSS, IRRF) parametrizados por vigência e regime
    const baseTributavel = Math.max(0, arredondar2(proventoBase + valorHorasExtras + rem.adicionalPericulosidadeInsalubridade - totalFaltasEAtrasosValor));
    const encargos = window.calcularEncargosLegaisParametrizados(
      baseTributavel,
      rem.regimePagamento,
      comp,
      colab.dependentes || 0,
      { forcarRetencaoTerceiro: ajuste.forcarRetencaoInss }
    );

    const descontoInss = ajuste.descontoInss !== undefined ? arredondar2(Number(ajuste.descontoInss)) : encargos.inss;
    const descontoIrrf = ajuste.descontoIrrf !== undefined ? arredondar2(Number(ajuste.descontoIrrf)) : encargos.irrf;
    const descontosAutorizadosExtras = ajuste.outrosDescontos !== undefined ? arredondar2(Number(ajuste.outrosDescontos)) : rem.descontoAutorizadoPadrao;

    const outrosDescontosTotal = arredondar2(descontoInss + descontoIrrf + descontosAutorizadosExtras);

    const totalProventos = arredondar2(proventoBase + valorHorasExtras + outrosProventos);
    const totalDescontos = arredondar2(totalFaltasEAtrasosValor + totalValesDescontar + outrosDescontosTotal);
    const liquidoReceber = Math.max(0, arredondar2(totalProventos - totalDescontos));

    const statusFolhaGlobal = window.obterStatusFolhaCompetencia(comp, rem.empresaId);
    let situacaoPagamento = ajuste.situacaoPagamento || (statusFolhaGlobal.paga ? 'Pago' : (statusFolhaGlobal.aprovada || statusFolhaGlobal.fechada ? 'Aprovado' : 'Pendente'));

    return {
      colabId: colab.id,
      funcionarioNome: colab.nome,
      cpfMascarado: colab.cpf && colab.cpf !== '-' && colab.cpf !== 'Não informado'
        ? '***.***.' + String(colab.cpf).slice(-6)
        : 'Matrícula ' + colab.id,
      cargoFuncao: colab.funcao || 'Operacional',
      tipoContratacao: rem.tipoContratacao,
      regimePagamento: rem.regimePagamento,
      empresaId: rem.empresaId,
      obraPrincipal: freq.obraPrincipal,
      rateioObras: freq.rateioObras,
      competencia: comp,
      remuneracaoBase: rem.salarioBase,
      diariaBase: rem.diariaBase,
      proventoBase,
      diasTrabalhados: diasTrab,
      valorBrutoTrabalhadoPeriodo,
      faltasInjustificadasQtd: freq.faltasInjustificadas,
      faltasDescontaveisQtd,
      atestadosMedicosQtd: freq.atestadosMedicos,
      feriasDiasQtd: freq.feriasDias,
      folgasQtd: freq.folgasCompensadas,
      afastamentosQtd: freq.afastamentosLegais,
      atrasosMinutos,
      faltasDescontaveisValor: totalFaltasEAtrasosValor,
      horasExtrasQtd,
      horasExtrasValor: valorHorasExtras,
      outrosProventosValor: outrosProventos,
      valesAdiantamentosValor: totalValesDescontar,
      valesJaPagosCaixaValor: totalValesJaPagosNoCaixa,
      limitePadraoVales40: limiteTotalVales40,
      limiteDisponivelVales: limiteDisponivelNovosVales,
      valesLista: valesColabPeriodo,
      descontoInss,
      descontoIrrf,
      descontosAutorizadosExtras,
      outrosDescontosValor: outrosDescontosTotal,
      totalProventos,
      totalDescontos,
      liquidoReceber,
      situacao: situacaoPagamento,
      divergenciasFrequencia: freq.divergencias,
      possuiDivergencia: freq.possuiDivergencia,
      sinalizacaoContabil: encargos.sinalizacaoContabil,
      dependeValidacaoContabil: encargos.dependeValidacaoContabil,
      ajusteAplicado: Boolean(ajustesMap[chaveAjuste]),
      justificativaAjuste: ajuste.justificativa || ''
    };
  };

  // Gera o Relatório Gerencial Completo para Pagamento de Funcionários (Item 19.C)
  window.gerarRelatorioPagamentoFuncionarios = function(filtros = {}) {
    const comp = filtros.competencia || '2026-11';
    const empFiltro = filtros.empresaId || 'todas';
    const obraFiltro = filtros.obra || 'todas';
    const colabFiltro = (filtros.funcionario || '').toLowerCase().trim();
    const sitFiltro = filtros.situacao || 'todas';

    const colabs = (typeof window.getColaboradoresDb === 'function' ? window.getColaboradoresDb() : [])
      .filter(c => c.status !== 'Inativo');

    const linhas = [];
    colabs.forEach(c => {
      const calc = window.calcularFolhaIndividualColaborador(c, comp);

      // Respeita isolamento de empresa do usuário logado
      if (typeof window.validarIsolamentoEmpresaUsuario === 'function' && window.currentLoggedUser) {
        const iso = window.validarIsolamentoEmpresaUsuario(window.currentLoggedUser, calc.empresaId);
        if (!iso.autorizado) return;
      }

      if (empFiltro !== 'todas' && calc.empresaId !== empFiltro) return;
      if (obraFiltro !== 'todas' && calc.obraPrincipal !== obraFiltro && !calc.rateioObras.some(r => r.obra === obraFiltro)) return;
      if (colabFiltro && !calc.funcionarioNome.toLowerCase().includes(colabFiltro) && !calc.colabId.toLowerCase().includes(colabFiltro)) return;
      if (sitFiltro !== 'todas' && calc.situacao.toLowerCase() !== sitFiltro.toLowerCase()) return;

      linhas.push(calc);
    });

    const totais = linhas.reduce((acc, item) => {
      acc.remuneracaoBase = arredondar2(acc.remuneracaoBase + item.remuneracaoBase);
      acc.proventoBase = arredondar2(acc.proventoBase + item.proventoBase);
      acc.faltasDescontaveisValor = arredondar2(acc.faltasDescontaveisValor + item.faltasDescontaveisValor);
      acc.horasExtrasValor = arredondar2(acc.horasExtrasValor + item.horasExtrasValor);
      acc.outrosProventosValor = arredondar2(acc.outrosProventosValor + item.outrosProventosValor);
      acc.valesAdiantamentosValor = arredondar2(acc.valesAdiantamentosValor + item.valesAdiantamentosValor);
      acc.outrosDescontosValor = arredondar2(acc.outrosDescontosValor + item.outrosDescontosValor);
      acc.totalProventos = arredondar2(acc.totalProventos + item.totalProventos);
      acc.totalDescontos = arredondar2(acc.totalDescontos + item.totalDescontos);
      acc.liquidoReceber = arredondar2(acc.liquidoReceber + item.liquidoReceber);
      return acc;
    }, {
      remuneracaoBase: 0,
      proventoBase: 0,
      faltasDescontaveisValor: 0,
      horasExtrasValor: 0,
      outrosProventosValor: 0,
      valesAdiantamentosValor: 0,
      outrosDescontosValor: 0,
      totalProventos: 0,
      totalDescontos: 0,
      liquidoReceber: 0
    });

    return {
      competencia: comp,
      filtrosAplicados: { empresaId: empFiltro, obra: obraFiltro, funcionario: colabFiltro, situacao: sitFiltro },
      quantidadeFuncionarios: linhas.length,
      itens: linhas,
      totaisGerais: totais
    };
  };

  // ==========================================================================
  // 6. RELATÓRIO E CONTROLE PARA CONCESSÃO DE VALES (ITEM 19.D — TRAVA 40%)
  // ==========================================================================
  window.gerarRelatorioConcessaoVales = function(filtros = {}) {
    const comp = filtros.competencia || '2026-11';
    const empFiltro = filtros.empresaId || 'todas';
    const obraFiltro = filtros.obra || 'todas';
    const valorSolicitadoSimulacao = Number(filtros.valorSolicitadoSimulacao || 0);

    const folha = window.gerarRelatorioPagamentoFuncionarios({
      competencia: comp,
      empresaId: empFiltro,
      obra: obraFiltro,
      funcionario: filtros.funcionario || ''
    });

    const relatorioVales = folha.itens.map(item => {
      const valSolicitado = valorSolicitadoSimulacao > 0 ? valorSolicitadoSimulacao : 0;
      const dentroDoLimite = (item.valesAdiantamentosValor + valSolicitado) <= item.limitePadraoVales40;
      const situacaoSolicitacao = item.valesLista.length > 0
        ? item.valesLista[0].situacao
        : (dentroDoLimite ? 'Disponível dentro do teto (40%)' : 'Requer Autorização Master (>40%)');

      return {
        colabId: item.colabId,
        funcionarioNome: item.funcionarioNome,
        cargoFuncao: item.cargoFuncao,
        empresaId: item.empresaId,
        obra: item.obraPrincipal,
        competencia: comp,
        diasTrabalhados: item.diasTrabalhados,
        remuneracaoBase: item.remuneracaoBase,
        valorBrutoTrabalhadoPeriodo: item.valorBrutoTrabalhadoPeriodo,
        valesJaConcedidos: item.valesAdiantamentosValor,
        limitePadrao40: item.limitePadraoVales40,
        limiteDisponivelNovosVales: item.limiteDisponivelVales,
        valorSolicitado: valSolicitado,
        valorDisponivelParaConcessao: item.limiteDisponivelVales,
        excedeLimite40: !dentroDoLimite,
        situacaoSolicitacao
      };
    });

    return {
      competencia: comp,
      regraLimitePercentual: 40,
      itens: relatorioVales,
      totalJaConcedido: arredondar2(relatorioVales.reduce((a, b) => a + b.valesJaConcedidos, 0)),
      totalDisponivelConcessao: arredondar2(relatorioVales.reduce((a, b) => a + b.valorDisponivelParaConcessao, 0))
    };
  };

  // Solicitação e Concessão de Vale com Trava Acumulada de 40%, Bloqueio de Duplicidade e Registro no Caixa
  window.registrarConcessaoValeSegura = function(dadosSolicitacao, usuarioExecutor) {
    const user = usuarioExecutor || window.currentLoggedUser || { usuario: 'operador', nome: 'Operador RH', perfil: 'RH' };
    const comp = dadosSolicitacao.competencia || (dadosSolicitacao.data ? dadosSolicitacao.data.slice(0, 7) : '2026-11');
    const dataVale = dadosSolicitacao.data || '2026-11-06';
    const valorSolicitado = arredondar2(Number(dadosSolicitacao.valorSolicitado || dadosSolicitacao.valor || 0));

    if (isNaN(valorSolicitado) || valorSolicitado <= 0) {
      return { aprovado: false, codigo: 'VALOR_INVALIDO', erro: 'O valor solicitado para o vale deve ser maior que zero.' };
    }

    const colabs = typeof window.getColaboradoresDb === 'function' ? window.getColaboradoresDb() : [];
    const colab = colabs.find(c => c.id === dadosSolicitacao.colabId || c.nome === dadosSolicitacao.colabNome) || {
      id: dadosSolicitacao.colabId || 'COL-01',
      nome: dadosSolicitacao.colabNome || 'Colaborador',
      funcao: dadosSolicitacao.funcao || 'Oficial de Obras (CLT)',
      salarioBase: dadosSolicitacao.salarioMensal || 3000,
      obra: dadosSolicitacao.obra || 'UBS - Nova Passos'
    };

    const calcAtual = window.calcularFolhaIndividualColaborador(colab, comp);
    const valesDb = window.obterValesAdiantamentosDb();

    // 1. Verifica duplicidade no período (mesmo colaborador, mesma data e mesmo valor)
    const duplicado = valesDb.find(v =>
      (v.colabId === colab.id || v.colabNome === colab.nome) &&
      v.data === dataVale &&
      Math.abs(Number(v.valorConcedido || v.valorSolicitado) - valorSolicitado) < 0.01 &&
      v.situacao !== 'Cancelado'
    );
    if (duplicado) {
      return {
        aprovado: false,
        codigo: 'VALE_DUPLICADO',
        erro: `Bloqueio de duplicidade: Já existe um adiantamento de ${formatarMoeda(valorSolicitado)} registrado para ${colab.nome} na data ${dataVale}.`
      };
    }

    // 2. Verifica limite acumulado de 40% do valor bruto efetivamente trabalhado no período
    const brutoTrabalhado = dadosSolicitacao.diasTrabalhadosNoPeriodo !== undefined
      ? arredondar2(((Number(dadosSolicitacao.salarioMensal || calcAtual.remuneracaoBase)) / 30) * Number(dadosSolicitacao.diasTrabalhadosNoPeriodo))
      : calcAtual.valorBrutoTrabalhadoPeriodo;

    const limite40 = arredondar2(brutoTrabalhado * 0.40);
    const jaConcedidoPeriodo = calcAtual.valesAdiantamentosValor;
    const disponivelAntes = Math.max(0, arredondar2(limite40 - jaConcedidoPeriodo));
    const novoTotalAcumulado = arredondar2(jaConcedidoPeriodo + valorSolicitado);

    let excecaoAutorizadaMaster = false;
    if (novoTotalAcumulado > limite40) {
      const ehMaster = typeof window.verificarSeUsuarioEhMaster === 'function'
        ? window.verificarSeUsuarioEhMaster(user)
        : (user.perfil === 'Master');
      const justificativa = String(dadosSolicitacao.justificativaExcecao || '').trim();

      if (!ehMaster) {
        return {
          aprovado: false,
          codigo: 'EXCEDE_LIMITE_40_SEM_MASTER',
          erro: `Limite acumulado de 40% excedido! Valor bruto já trabalhado: ${formatarMoeda(brutoTrabalhado)} | Teto 40%: ${formatarMoeda(limite40)} | Já concedido: ${formatarMoeda(jaConcedidoPeriodo)} | Disponível: ${formatarMoeda(disponivelAntes)}. Acima desse limite, o lançamento exige autorização do administrador Master.`,
          valorBrutoTrabalhado: brutoTrabalhado,
          limite40,
          jaConcedidoPeriodo,
          disponivelParaConcessao: disponivelAntes
        };
      }

      if (justificativa.length < 5) {
        return {
          aprovado: false,
          codigo: 'EXCEDE_LIMITE_40_SEM_JUSTIFICATIVA',
          erro: 'Informe uma justificativa administrativa (mínimo 5 caracteres) para autorizar vale acima do limite acumulado de 40%.'
        };
      }

      excecaoAutorizadaMaster = true;
      if (typeof window.gravarLogAuditoriaImutavel === 'function') {
        window.gravarLogAuditoriaImutavel({
          usuario_id: user.usuario || 'admin',
          perfil: user.perfil || 'Master',
          modulo: 'RH / Folha / Vales',
          acao: 'AUTORIZACAO_VALE_ACIMA_40_PORCENTO',
          entidade_id: colab.id,
          valor_anterior_json: { jaConcedidoPeriodo, limite40 },
          valor_novo_json: { valorSolicitado, novoTotalAcumulado },
          justificativa
        });
      }
    }

    const pagoImediatamente = dadosSolicitacao.pagoAntecipadamente !== false;
    let lancamentoCaixaId = null;

    // Se o vale foi pago antecipadamente, registra a saída única no Financeiro (adiantamento salarial)
    if (pagoImediatamente && Array.isArray(window.lancamentosFinanceirosDb)) {
      lancamentoCaixaId = `FIN-VALE-${Date.now()}`;
      window.lancamentosFinanceirosDb.unshift({
        id: lancamentoCaixaId,
        data: dataVale,
        favorecido: colab.nome,
        descricao: `[ADIANTAMENTO / VALE SALARIAL] ${colab.nome} (${comp}) — Desconto programado em folha`,
        categoria: 'MAO-OBRA',
        naturezaFinanceira: 'ADIANTAMENTO_SALARIAL',
        valor: valorSolicitado,
        tipo: 'DESPESA',
        empresaId: calcAtual.empresaId,
        obra: dadosSolicitacao.obra || calcAtual.obraPrincipal,
        contaBancariaId: dadosSolicitacao.contaBancariaId || 'CTA-BB-MOV',
        status: 'Conciliado',
        representaPagamentoBancarioReal: true,
        created_by: (user.usuario || 'admin').toLowerCase(),
        compartilhadoCom: []
      });
    }

    const novoVale = {
      id: `VALE-${comp.replace('-', '')}-${Date.now().toString().slice(-4)}`,
      colabId: colab.id,
      colabNome: colab.nome,
      empresaId: calcAtual.empresaId,
      obra: dadosSolicitacao.obra || calcAtual.obraPrincipal,
      competencia: comp,
      data: dataVale,
      valorSolicitado,
      valorConcedido: valorSolicitado,
      situacao: pagoImediatamente ? 'Pago Antecipadamente' : 'Aprovado',
      pagoNoCaixa: pagoImediatamente,
      lancamentoFinanceiroCaixaId: lancamentoCaixaId,
      descontadoEmFolha: false,
      excecaoMaster: excecaoAutorizadaMaster,
      autorizadoPor: `${user.nome || user.usuario} (${user.perfil || 'Master'})`,
      observacao: dadosSolicitacao.observacao || (excecaoAutorizadaMaster ? `Exceção >40%: ${dadosSolicitacao.justificativaExcecao}` : 'Vale dentro do limite de 40%')
    };

    valesDb.unshift(novoVale);
    window.salvarValesAdiantamentosDb(valesDb);

    return {
      aprovado: true,
      vale: novoVale,
      excecaoAutorizadaMaster,
      valorBrutoTrabalhado: brutoTrabalhado,
      limite40,
      novoAcumuladoConcedido: novoTotalAcumulado,
      saldoDisponivelRestante: Math.max(0, arredondar2(limite40 - novoTotalAcumulado))
    };
  };

  // ==========================================================================
  // 7. CONFERÊNCIA, AJUSTES AUTORIZADOS, FECHAMENTO E INTEGRAÇÃO FINANCEIRA (19.F e 19.G)
  // ==========================================================================
  window.registrarAjusteIndividualFolha = function(colabId, competenciaYm, dadosAjuste, usuarioExecutor) {
    const user = usuarioExecutor || window.currentLoggedUser || { usuario: 'admin', nome: 'Henrique Camilo', perfil: 'Master' };
    const comp = competenciaYm || '2026-11';
    const colabs = typeof window.getColaboradoresDb === 'function' ? window.getColaboradoresDb() : [];
    const colab = colabs.find(c => c.id === colabId) || { id: colabId, nome: colabId };
    const rem = window.obterDadosRemuneracaoColaborador(colab);
    const statusFolha = window.obterStatusFolhaCompetencia(comp, rem.empresaId);

    // Regra 19.G: Após o fechamento, alterações exigem autorização Master e ficam registradas no histórico
    if (statusFolha.fechada) {
      const ehMaster = typeof window.verificarSeUsuarioEhMaster === 'function'
        ? window.verificarSeUsuarioEhMaster(user)
        : (user.perfil === 'Master');
      const just = String(dadosAjuste.justificativa || '').trim();

      if (!ehMaster) {
        return {
          sucesso: false,
          codigo: 'FOLHA_FECHADA_EXIGE_MASTER',
          erro: 'A folha desta competência já está FECHADA. Alterações pós-fechamento exigem autorização exclusiva de um administrador Master.'
        };
      }
      if (just.length < 5) {
        return {
          sucesso: false,
          codigo: 'JUSTIFICATIVA_OBRIGATORIA_POS_FECHAMENTO',
          erro: 'Para ajustar uma folha já fechada, informe justificativa obrigatória para a trilha de auditoria.'
        };
      }
    }

    const ajustesMap = window.obterAjustesFolhaDb();
    const chave = `${comp}__${colabId}`;
    const anterior = ajustesMap[chave] || {};

    ajustesMap[chave] = {
      ...anterior,
      ...dadosAjuste,
      atualizadoPor: `${user.nome || user.usuario} (${user.perfil})`,
      dataHora: new Date().toISOString()
    };
    window.salvarAjustesFolhaDb(ajustesMap);

    if (typeof window.gravarLogAuditoriaImutavel === 'function') {
      window.gravarLogAuditoriaImutavel({
        usuario_id: user.usuario || 'admin',
        perfil: user.perfil || 'Master',
        modulo: 'Folha de Pagamento',
        acao: statusFolha.fechada ? 'AJUSTE_POS_FECHAMENTO_AUTORIZADO' : 'AJUSTE_CONFERENCIA_FOLHA',
        entidade_id: chave,
        valor_anterior_json: anterior,
        valor_novo_json: ajustesMap[chave],
        justificativa: dadosAjuste.justificativa || 'Conferência e ajuste de apuração da folha'
      });
    }

    return {
      sucesso: true,
      ajuste: ajustesMap[chave],
      calculoAtualizado: window.calcularFolhaIndividualColaborador(colab, comp)
    };
  };

  // Avança etapa do fluxo: Apuração -> Conferência -> Aprovação -> Fechamento -> Pagamento
  window.avancarFluxoFolhaCompetencia = function(competenciaYm, empresaId = 'emp-1', novaEtapa, usuarioExecutor, justificativa = '') {
    const user = usuarioExecutor || window.currentLoggedUser || { usuario: 'admin', nome: 'Henrique Camilo', perfil: 'Master' };
    const comp = competenciaYm || '2026-11';
    const emp = empresaId || 'emp-1';

    if (!window.ESTAGIOS_FLUXO_FOLHA.includes(novaEtapa)) {
      return { sucesso: false, erro: `Etapa inválida (${novaEtapa}). Use: ${window.ESTAGIOS_FLUXO_FOLHA.join(' → ')}.` };
    }

    const ehMaster = typeof window.verificarSeUsuarioEhMaster === 'function'
      ? window.verificarSeUsuarioEhMaster(user)
      : (user.perfil === 'Master');

    if (['Aprovação', 'Fechamento', 'Pagamento'].includes(novaEtapa) && !ehMaster) {
      return {
        sucesso: false,
        codigo: 'APROVACAO_FECHAMENTO_EXIGE_MASTER',
        erro: `A etapa "${novaEtapa}" da folha de pagamento exige autorização de perfil Master.`
      };
    }

    const db = window.obterControleFechamentoFolhaDb();
    const chave = `${comp}__${emp}`;
    const atual = window.obterStatusFolhaCompetencia(comp, emp);

    atual.etapaAtual = novaEtapa;
    if (novaEtapa === 'Aprovação') {
      atual.aprovada = true;
      // Regra 19.G: Não considerar uma folha aprovada como automaticamente paga!
      atual.paga = false;
    } else if (novaEtapa === 'Fechamento') {
      atual.aprovada = true;
      atual.fechada = true;
      atual.paga = false;
    } else if (novaEtapa === 'Pagamento') {
      if (!atual.aprovada && !atual.fechada) {
        return {
          sucesso: false,
          codigo: 'EXIGE_FECHAMENTO_ANTES_PAGAMENTO',
          erro: 'A folha precisa passar por Conferência, Aprovação e Fechamento antes da efetiva quitação/pagamento.'
        };
      }
      atual.paga = true;
    }

    atual.historicoFluxo = atual.historicoFluxo || [];
    atual.historicoFluxo.unshift({
      etapa: novaEtapa,
      responsavel: `${user.nome || user.usuario} (${user.perfil})`,
      dataHora: new Date().toISOString(),
      justificativa: justificativa || `Transição para ${novaEtapa}`
    });

    db[chave] = atual;
    window.salvarControleFechamentoFolhaDb(db);

    // Integração com o Financeiro (Item 19.F):
    // Ao Aprovar ou Fechar a folha, gera as obrigações financeiras (Contas a Pagar) pelo VALOR LÍQUIDO A RECEBER
    // (o vale pago antecipadamente já foi descontado no cálculo do líquido, evitando segunda saída de caixa pelo mesmo valor!)
    let integracaoFinanceira = null;
    if ((novaEtapa === 'Aprovação' || novaEtapa === 'Fechamento') && !atual.obrigacoesGeradasFinanceiro) {
      integracaoFinanceira = window.gerarObrigacoesFinanceirasDaFolha(comp, emp, user);
      atual.obrigacoesGeradasFinanceiro = true;
      db[chave] = atual;
      window.salvarControleFechamentoFolhaDb(db);
    }

    // Se a etapa for Pagamento (efetiva quitação), atualiza os títulos da folha para Pago/Conciliado no Fluxo de Caixa
    if (novaEtapa === 'Pagamento') {
      if (!atual.obrigacoesGeradasFinanceiro) {
        window.gerarObrigacoesFinanceirasDaFolha(comp, emp, user);
        atual.obrigacoesGeradasFinanceiro = true;
      }
      integracaoFinanceira = window.quitarFolhaNoFluxoDeCaixa(comp, emp, user);
      db[chave] = atual;
      window.salvarControleFechamentoFolhaDb(db);
    }

    if (typeof window.gravarLogAuditoriaImutavel === 'function') {
      window.gravarLogAuditoriaImutavel({
        usuario_id: user.usuario || 'admin',
        perfil: user.perfil || 'Master',
        modulo: 'Folha / Fluxo Fechamento',
        acao: `FLUXO_FOLHA_${novaEtapa.toUpperCase()}`,
        entidade_id: chave,
        valor_novo_json: { etapaAtual: novaEtapa, aprovada: atual.aprovada, fechada: atual.fechada, paga: atual.paga },
        justificativa: justificativa || `Mudança de estágio da folha para ${novaEtapa}`
      });
    }

    return {
      sucesso: true,
      statusFolha: atual,
      integracaoFinanceira
    };
  };

  // Item 19.F: Gera obrigações financeiras da folha sem duplicar adiantamentos já pagos e com rateio por obra
  window.gerarObrigacoesFinanceirasDaFolha = function(competenciaYm, empresaId = 'emp-1', usuarioExecutor) {
    const comp = competenciaYm || '2026-11';
    const emp = empresaId || 'emp-1';
    const user = usuarioExecutor || window.currentLoggedUser || { usuario: 'admin', nome: 'Henrique Camilo', perfil: 'Master' };

    window.lancamentosFinanceirosDb = window.lancamentosFinanceirosDb || [];

    // Evita duplicidade caso a geração de obrigações já tenha sido acionada para a mesma competência e empresa
    const chaveRefFolha = `FOLHA-${comp}-${emp}`;
    const jaExiste = window.lancamentosFinanceirosDb.some(l => l.referenciaFolhaChave === chaveRefFolha && l.status !== 'Estornado');
    if (jaExiste) {
      return {
        sucesso: true,
        duplicidadeEvitada: true,
        mensagem: `Obrigações financeiras da folha ${comp} (${emp}) já haviam sido geradas anteriormente.`
      };
    }

    const rel = window.gerarRelatorioPagamentoFuncionarios({ competencia: comp, empresaId: emp });
    const obrigacoesPorObra = {};
    let totalLiquidoGeradoCaixa = 0;
    let totalValesAbatidosSemNovaSaida = 0;

    rel.itens.forEach(item => {
      totalLiquidoGeradoCaixa = arredondar2(totalLiquidoGeradoCaixa + item.liquidoReceber);
      totalValesAbatidosSemNovaSaida = arredondar2(totalValesAbatidosSemNovaSaida + item.valesAdiantamentosValor);

      // Rateia o valor líquido a pagar pelas obras em que o funcionário trabalhou no período
      item.rateioObras.forEach(r => {
        const quotaLiquidaObra = arredondar2((item.liquidoReceber * r.percentual) / 100);
        if (!obrigacoesPorObra[r.obra]) {
          obrigacoesPorObra[r.obra] = { obra: r.obra, valorLiquidoPagar: 0, valesJaDescontados: 0, qtdFuncionarios: 0 };
        }
        obrigacoesPorObra[r.obra].valorLiquidoPagar = arredondar2(obrigacoesPorObra[r.obra].valorLiquidoPagar + quotaLiquidaObra);
        obrigacoesPorObra[r.obra].valesJaDescontados = arredondar2(obrigacoesPorObra[r.obra].valesJaDescontados + ((item.valesAdiantamentosValor * r.percentual) / 100));
        obrigacoesPorObra[r.obra].qtdFuncionarios += 1;
      });
    });

    const lancamentosCriados = [];
    Object.values(obrigacoesPorObra).forEach((obInfo, idx) => {
      if (obInfo.valorLiquidoPagar <= 0) return;
      const novoTitulo = {
        id: `FIN-FOLHA-${comp.replace('-', '')}-${emp}-${idx + 1}`,
        referenciaFolhaChave: chaveRefFolha,
        competenciaFolha: comp,
        data: `${comp}-05`,
        vencimento: `${comp}-05`,
        favorecido: `Folha de Pagamento (${obInfo.qtdFuncionarios} func.) — ${emp.toUpperCase()}`,
        descricao: `[FOLHA ${comp}] Líquido a pagar ref. obra ${obInfo.obra} (Vales já descontados sem nova saída: ${formatarMoeda(obInfo.valesJaDescontados)})`,
        categoria: 'MAO-OBRA',
        naturezaFinanceira: 'OBRIGACAO_FOLHA_LIQUIDA',
        valor: obInfo.valorLiquidoPagar,
        valesAbatidosSemSaidaDuplicada: obInfo.valesJaDescontados,
        tipo: 'DESPESA',
        empresaId: emp,
        obra: obInfo.obra,
        contaBancariaId: emp === 'emp-2' ? 'CTA-SANT-CALHAS' : (emp === 'emp-3' ? 'CTA-NUBANK-ACOS' : 'CTA-BB-MOV'),
        status: 'Conferido', // Aprovado na folha, aguardando efetiva quitação para atualizar saldo de caixa
        representaPagamentoBancarioReal: false,
        created_by: (user.usuario || 'admin').toLowerCase(),
        compartilhadoCom: []
      };
      window.lancamentosFinanceirosDb.unshift(novoTitulo);
      lancamentosCriados.push(novoTitulo);
    });

    return {
      sucesso: true,
      duplicidadeEvitada: false,
      competencia: comp,
      empresaId: emp,
      totalLiquidoGeradoCaixa,
      totalValesAbatidosSemNovaSaida,
      lancamentosCriados
    };
  };

  // Efetiva quitação da folha e atualiza o Fluxo de Caixa somente no momento do pagamento real
  window.quitarFolhaNoFluxoDeCaixa = function(competenciaYm, empresaId = 'emp-1', usuarioExecutor) {
    const comp = competenciaYm || '2026-11';
    const emp = empresaId || 'emp-1';
    const user = usuarioExecutor || window.currentLoggedUser || { usuario: 'admin', nome: 'Henrique Camilo', perfil: 'Master' };
    const chaveRefFolha = `FOLHA-${comp}-${emp}`;

    let totalQuitado = 0;
    let titulosBaixados = 0;

    (window.lancamentosFinanceirosDb || []).forEach(lanc => {
      if (lanc.referenciaFolhaChave === chaveRefFolha && lanc.status !== 'Conciliado') {
        lanc.status = 'Conciliado';
        lanc.representaPagamentoBancarioReal = true;
        lanc.dataPagamentoEfetivo = new Date().toISOString().slice(0, 10);
        lanc.quitadoPor = user.nome || user.usuario;
        totalQuitado = arredondar2(totalQuitado + Number(lanc.valor || 0));
        titulosBaixados++;
      }
    });

    // Marca vales da competência como descontados em folha
    const valesDb = window.obterValesAdiantamentosDb();
    valesDb.forEach(v => {
      if (v.competencia === comp && (emp === 'todas' || v.empresaId === emp)) {
        v.descontadoEmFolha = true;
        v.situacao = 'Descontado em Folha';
      }
    });
    window.salvarValesAdiantamentosDb(valesDb);

    return {
      sucesso: true,
      titulosBaixados,
      totalQuitadoNoCaixa: totalQuitado
    };
  };

  // ==========================================================================
  // 8. EMISSÃO DE HOLERITES EM PDF (INDIVIDUAL E EM LOTE) — ITEM 19.B
  // ==========================================================================
