  /**
   * Registro seguro de movimentação de estoque com CMP e prevenção de duplicidades financeiras
   */
  window.registrarMovimentacaoEstoque = function(mov, usuarioLogado) {
    const item = window.itensEstoqueDb.find(i => i.id === mov.itemId);
    if (!item) {
      return { sucesso: false, erro: 'Item de estoque não encontrado.' };
    }

    const qtd = Number(mov.quantidade) || 0;
    if (qtd <= 0) {
      return { sucesso: false, erro: 'Quantidade deve ser maior que zero.' };
    }

    const agora = new Date().toISOString();
    const tipo = mov.tipo; // ENTRADA_COMPRA, TRANSFERENCIA_DEPOSITO, RESERVA, BAIXA_PRODUCAO, RETORNO_SOBRA, SUCATA

    if (tipo === 'ENTRADA_COMPRA') {
      const custoUnitEntrada = Number(mov.custoUnitario) || item.custoMedioPonderado;
      const saldoAnterior = item.saldoFisico;
      const cmpAnterior = item.custoMedioPonderado;
      const novoSaldo = saldoAnterior + qtd;
      const novoCmp = novoSaldo > 0
        ? arredondar2(((saldoAnterior * cmpAnterior) + (qtd * custoUnitEntrada)) / novoSaldo)
        : custoUnitEntrada;

      item.saldoFisico = novoSaldo;
      item.saldoDisponivel = item.saldoFisico - item.saldoReservado;
      item.custoMedioPonderado = novoCmp;
    } else if (tipo === 'RESERVA') {
      if (item.saldoDisponivel < qtd) {
        return { sucesso: false, erro: `Saldo insuficiente para reserva. Disponível: ${item.saldoDisponivel}, Solicitado: ${qtd}` };
      }
      item.saldoReservado += qtd;
      item.saldoDisponivel = item.saldoFisico - item.saldoReservado;
      // REGRA: Reserva NÃO altera saldo físico nem gera lançamento contábil antecipado!
    } else if (tipo === 'BAIXA_PRODUCAO') {
      if (item.saldoFisico < qtd) {
        return { sucesso: false, erro: `Saldo físico insuficiente para baixa na produção.` };
      }
      item.saldoFisico -= qtd;
      item.saldoReservado = Math.max(0, item.saldoReservado - qtd);
      item.saldoDisponivel = item.saldoFisico - item.saldoReservado;
    } else if (tipo === 'TRANSFERENCIA_DEPOSITO') {
      const depDestinoId = mov.depositoDestinoId;
      if (!depDestinoId || depDestinoId === item.depositoId) {
        return { sucesso: false, erro: 'Depósito de destino inválido ou idêntico à origem.' };
      }
      if (item.saldoDisponivel < qtd) {
        return { sucesso: false, erro: `Saldo insuficiente para transferência. Disponível: ${item.saldoDisponivel}` };
      }

      // Baixa na origem
      item.saldoFisico -= qtd;
      item.saldoDisponivel = item.saldoFisico - item.saldoReservado;

      // Incremento ou criação no depósito destino
      let itemDestino = window.itensEstoqueDb.find(i => i.codigo === item.codigo && i.depositoId === depDestinoId);
      if (!itemDestino) {
        itemDestino = {
          ...item,
          id: `EST-${item.codigo}-${Date.now().toString().slice(-4)}`,
          depositoId: depDestinoId,
          saldoFisico: 0,
          saldoReservado: 0,
          saldoDisponivel: 0
        };
        window.itensEstoqueDb.push(itemDestino);
      }
      itemDestino.saldoFisico += qtd;
      itemDestino.saldoDisponivel += qtd;

      // REGRA DE OURO: TRANSFERÊNCIA NÃO GERA DESPESA NEM CONSUMO NO FINANCEIRO!
      mov.efeitoFinanceiro = 'NENHUM_TRANSFERENCIA_PATRIMONIAL_INTERNA';
    }

    const reg = {
      id: `MOV-${Date.now()}-${Math.floor(Math.random() * 1000)}`,
      itemId: item.id,
      itemCodigo: item.codigo,
      tipo: tipo,
      quantidade: qtd,
      unidadeMedida: item.unidadeMedida,
      depositoOrigemId: item.depositoId,
      depositoDestinoId: mov.depositoDestinoId || null,
      custoMedioNoMomento: item.custoMedioPonderado,
      saldoFisicoApos: item.saldoFisico,
      saldoDisponivelApos: item.saldoDisponivel,
      efeitoFinanceiro: mov.efeitoFinanceiro || (tipo === 'TRANSFERENCIA_DEPOSITO' ? 'NENHUM_TRANSFERENCIA_PATRIMONIAL_INTERNA' : 'NEUTRO'),
      justificativa: mov.justificativa || 'Movimentação operacional',
      referenciaDocumento: mov.referenciaDocumento || null,
      usuario: (usuarioLogado && usuarioLogado.usuario) || 'sistema',
      dataHora: agora
    };

    window.movimentacoesEstoqueHistorico.unshift(reg);
    return { sucesso: true, item, movimentacao: reg };
  };

  // ==========================================================================
  // LOTE 6 — FICHAS TÉCNICAS E CUSTOS (VERSIONADAS COM PRESERVAÇÃO HISTÓRICA)
