        { codigo: 'VIDRO-FLOAT-4', nome: 'Vidro Float Incolor 4mm', consumoPorUnidade: 0.95, uom: 'M2', custoUnitarioReposicao: 110.00 },
        { codigo: 'KIT-ACESS-J2F', nome: 'Kit Acessórios e Roldanas J2F', consumoPorUnidade: 1, uom: 'KIT', custoUnitarioReposicao: 85.00 }
