  /**
   * Sobrescreve window.gerarHtmlPdfRdoOficial para proteger Observações Confidenciais:
   * - Em relatórios destinados a clientes ou fiscais (`ocultarConfidenciaisParaClienteFiscal: true`, padrão = true),
   *   as observações confidenciais internas NUNCA são exibidas!
   */
  window.gerarHtmlPdfRdoOficial = function(rdoObj, fotosLista = [], opcoes = {}) {
    if (!rdoObj) return '';
    const incluirConfidenciais = Boolean(opcoes.incluirObservacoesConfidenciaisInternas === true);

    const itensHtml = (rdoObj.atividadesItens || []).map((at, i) => `
      <tr>
        <td style="padding:6px;border:1px solid #cbd5e1;text-align:center;">${i + 1}</td>
        <td style="padding:6px;border:1px solid #cbd5e1;"><strong>${at.descricao}</strong><br><small>Local: ${at.localExecucao || '-'}</small></td>
        <td style="padding:6px;border:1px solid #cbd5e1;text-align:center;">${at.quantidadeExecutada} ${at.unidadeMedida}</td>
        <td style="padding:6px;border:1px solid #cbd5e1;">${at.equipeResponsavel || '-'}</td>
        <td style="padding:6px;border:1px solid #cbd5e1;">${at.observacoes || '-'}</td>
      </tr>
    `).join('');

    const fotosHtml = (fotosLista || []).map(f => `
      <div style="border:1px solid #cbd5e1;padding:8px;border-radius:6px;font-size:11px;">
        <strong>Foto ID: ${f.id}</strong> (${f.resolucaoPx})<br>
        <span>Descrição: ${f.descricao}</span><br>
        <small>Caminho Storage: ${f.caminhoOrganizadoStorage}</small>
      </div>
    `).join('');

    const blocoConfidencialHtml = (incluirConfidenciais && rdoObj.observacoesConfidenciaisInternas)
      ? `<div style="margin-top:12px;padding:8px;background:#fef2f2;border:1px solid #ef4444;font-size:11px;">
           <strong>OBSERVAÇÕES CONFIDENCIAIS DA DIRETORIA (USO INTERNO):</strong> ${rdoObj.observacoesConfidenciaisInternas}
         </div>`
      : '';

    return `
      <div class="documento-rdo-oficial-a4" style="font-family:Inter,sans-serif;padding:24px;color:#0f172a;">
        <h2 style="margin:0 0 8px;">RELATÓRIO DIÁRIO DE OBRA (RDO) — ${rdoObj.numeroRelatorio}</h2>
        <p style="margin:0 0 12px;font-size:12px;">
          <strong>Obra:</strong> ${rdoObj.obraNome} | <strong>Data:</strong> ${rdoObj.dataIso} |
          <strong>Responsável:</strong> ${rdoObj.responsavel} | <strong>Situação:</strong> ${rdoObj.situacao}
        </p>
        <h4>1. Atividades Executadas (Itens Estruturados)</h4>
        <table style="width:100%;border-collapse:collapse;font-size:12px;margin-bottom:16px;">
          <thead>
            <tr style="background:#f1f5f9;">
              <th style="padding:6px;border:1px solid #cbd5e1;">#</th>
              <th style="padding:6px;border:1px solid #cbd5e1;">Atividade / Local</th>
              <th style="padding:6px;border:1px solid #cbd5e1;">Medição</th>
              <th style="padding:6px;border:1px solid #cbd5e1;">Equipe</th>
              <th style="padding:6px;border:1px solid #cbd5e1;">Observações</th>
            </tr>
          </thead>
          <tbody>${itensHtml}</tbody>
        </table>
        <h4>2. Observações Técnicas Públicas</h4>
        <p style="font-size:12px;">${rdoObj.observacoesTecnicas || 'Sem observações adicionais.'}</p>
        ${blocoConfidencialHtml}
        <h4>3. Registro Fotográfico Vinculado (${fotosLista.length} fotos)</h4>
        <div style="display:grid;grid-template-columns:1fr 1fr;gap:10px;">${fotosHtml}</div>
      </div>
    `;
  };

  /**
   * 7. Emissão do Dossiê Consolidado de RDOs por Período em PDF + Compartilhamento via WhatsApp / Web Share
   */
  window.emitirDossieConsolidadoRdosPdf = function(filtros = {}, usuarioLogado) {
    const sessao = window.exigirSessaoAutenticadaValida(usuarioLogado);
    if (!sessao.autenticado) return { sucesso: false, codigo: sessao.codigo, erro: sessao.erro };

    const consulta = window.consultarHistoricoRdosAntigos({ ...filtros, tamanhoPagina: 500 }, sessao.usuario);
    if (!consulta.sucesso) return consulta;

    // Organiza em ordem cronológica crescente para o Dossiê Técnico da Obra
    const rdosCronologicos = [...(consulta.rdosCompletosFiltrados || [])].sort((a, b) => a.dataIso.localeCompare(b.dataIso));
    const incluirConfidenciais = Boolean(filtros.incluirObservacoesConfidenciaisInternas === true && sessao.usuario.perfil === 'Master');

    const paginasHtml = rdosCronologicos.map(rdo => {
      const fotos = (window.galeriaFotografiasObrasMemoria || []).filter(f => (rdo.fotosIds || []).includes(f.id));
      return window.gerarHtmlPdfRdoOficial(rdo, fotos, { incluirObservacoesConfidenciaisInternas: incluirConfidenciais });
    }).join('<div style="page-break-after:always;border-bottom:2px dashed #94a3b8;margin:20px 0;"></div>');

    const nomeObra = rdosCronologicos[0]?.obraNome || 'Consolidado Multiempresa';
    const textoResumoWhatsApp = `*DOSSIÊ DE RDOs - SISTEMA MARTINS*\nObra: ${nomeObra}\nPeríodo: ${filtros.periodoInicio || 'Início'} a ${filtros.periodoFim || 'Hoje'}\nTotal de Relatórios: ${rdosCronologicos.length} RDO(s) homologados.`;
    const linkWhatsApp = `https://wa.me/?text=${encodeURIComponent(textoResumoWhatsApp)}`;

    const printArea = document.getElementById('printable-area');
    if (printArea) printArea.innerHTML = paginasHtml;

    return {
      sucesso: true,
      obraNome: nomeObra,
      quantidadeRdosNoDossie: rdosCronologicos.length,
      ordemCronologicaGarantida: true,
      observacoesConfidenciaisOcultadasParaTerceiros: !incluirConfidenciais,
      htmlConsolidadoPdf: paginasHtml,
      compartilhamentoDispositivo: {
        linkWhatsApp,
        textoResumoWhatsApp,
        webShareSuportado: Boolean(typeof navigator !== 'undefined' && navigator.share)
      }
    };
  };

  // ==========================================================================
  // 9. FREQUÊNCIA E EQUIPES: DETECÇÃO DE CONFLITO DE HORÁRIO ATRAVESSANDO MEIA-NOITE
  // ==========================================================================
  function converterHorarioEmIntervalosAbsolutos(dataIso, horaInicio = '07:00', horaFim = '17:00') {
    const dtBase = new Date(dataIso + 'T00:00:00Z').getTime() / 60000; // em minutos desde epoch
    const [hI, mI] = horaInicio.split(':').map(Number);
    const [hF, mF] = horaFim.split(':').map(Number);
    const iniMin = dtBase + (hI * 60 + mI);
    let fimMin = dtBase + (hF * 60 + mF);
    if (fimMin <= iniMin) {
      fimMin += 24 * 60; // Turno noturno que atravessa a meia-noite!
    }
    return { inicioAbsolutoMin: iniMin, fimAbsolutoMin: fimMin };
  }

  window.registrarAlocacaoEFrequenciaPorObra = function(dados, usuarioLogado) {
    const sessao = window.exigirSessaoAutenticadaValida(usuarioLogado);
    if (!sessao.autenticado) return { sucesso: false, codigo: sessao.codigo, erro: sessao.erro };
    const user = sessao.usuario;

    const obra = window.obrasDb.find(o => o.id === dados.obraId);
    if (!obra) return { sucesso: false, erro: 'Obra não localizada.' };

    const permEmp = window.exigirSessaoAutenticadaValida(user, obra.empresaId);
    if (!permEmp.autorizado) return { sucesso: false, codigo: permEmp.codigo, erro: permEmp.erro };

    const dataIso = dados.dataIso || (typeof window.obterDataAtualBrasiliaIso === 'function' ? window.obterDataAtualBrasiliaIso() : '2026-11-06');
    const horaInicio = dados.horaInicio || '07:00';
    const horaFim = dados.horaFim || '17:00';
    const novoInterv = converterHorarioEmIntervalosAbsolutos(dataIso, horaInicio, horaFim);

    const statusAtivosNoCanteiro = ['Presente', 'Presença Integral', 'Meio Período', 'Atraso'];
    const statusNovo = dados.statusFrequencia || 'Presente';

    if (statusAtivosNoCanteiro.includes(statusNovo) && !dados.permitirTransferenciaTurno) {
      const conflito = (window.alocacoesEquipesObraDiaDb || []).find(a => {
        if (a.colaboradorId !== dados.colaboradorId) return false;
        if (a.obraId === obra.id) return false;
        if (!statusAtivosNoCanteiro.includes(a.statusFrequencia)) return false;

        const intervExistente = converterHorarioEmIntervalosAbsolutos(a.dataIso, a.horaInicio || '07:00', a.horaFim || '17:00');
        // Verifica interseção real entre os intervalos de tempo (mesmo atravessando a meia-noite entre dias consecutivos!)
        return Math.max(novoInterv.inicioAbsolutoMin, intervExistente.inicioAbsolutoMin) <
               Math.min(novoInterv.fimAbsolutoMin, intervExistente.fimAbsolutoMin);
      });

      if (conflito) {
        return {
          sucesso: false,
          codigo: 'COLABORADOR_ALOCADO_EM_OUTRA_OBRA',
          conflitoObraId: conflito.obraId,
          erro: `Conflito de horário/turno: O colaborador ${dados.colaboradorNome || dados.colaboradorId} já está alocado na obra ${conflito.obraId} em janela de horário sobreposta (${conflito.dataIso} ${conflito.horaInicio || '07:00'}-${conflito.horaFim || '17:00'}).`
        };
      }
    }

    const novoReg = {
      id: 'ALOC-' + Date.now() + '-' + Math.floor(Math.random() * 1000),
      dataIso,
      horaInicio,
      horaFim,
      atravessaMeiaNoite: novoInterv.fimAbsolutoMin - novoInterv.inicioAbsolutoMin > 0 && horaFim < horaInicio,
      obraId: obra.id,
      empresaId: obra.empresaId,
      colaboradorId: dados.colaboradorId,
      colaboradorNome: dados.colaboradorNome || dados.colaboradorId,
      equipeId: dados.equipeId || 'EQ-GERAL',
      statusFrequencia: statusNovo,
      minutosAtraso: Number(dados.minutosAtraso || 0),
      registradoNaFrequenciaSemObrigarRdo: true,
      responsavelRegistro: user.usuario
    };

    window.alocacoesEquipesObraDiaDb.push(novoReg);
    return { sucesso: true, registro: novoReg };
  };

  // ==========================================================================
