  // 2.3 CESTA BÁSICA: LISTA DE ELEGIBILIDADE COM REGRAS CONFIGURÁVEIS
  window.regrasElegibilidadeCestaBasicaConfig = window.regrasElegibilidadeCestaBasicaConfig || {
    maxFaltasInjustificadasNoMes: 0,
    minDiasTrabalhadosNoMes: 1,
    permitirAtestadoMedicoHomologado: true,
    valorEstimadoCestaBasica: 185.00
  };

  window.apurarElegibilidadeCestaBasicaRh = function(competenciaYm = '2026-11', regrasCustom = {}) {
    const regras = { ...window.regrasElegibilidadeCestaBasicaConfig, ...regrasCustom };
    window.colaboradoresDb = window.colaboradoresDb || (typeof window.getColaboradoresDb === 'function' ? window.getColaboradoresDb() : []);
    const colabs = window.colaboradoresDb;

    const elegiveis = [];
    const inabilitados = [];

    colabs.forEach(c => {
      if (c.status === 'Inativo') return;
      const calcFolha = typeof window.calcularFolhaIndividualColaborador === 'function'
        ? window.calcularFolhaIndividualColaborador(c, competenciaYm)
        : { diasTrabalhados: 20, faltasInjustificadasQtd: 0, atestadosMedicosQtd: 0 };

      const faltasInj = Number(calcFolha.faltasInjustificadasQtd || 0);
      const diasTrab = Number(calcFolha.diasTrabalhados || 0);
      const motivosBloqueio = [];

      if (faltasInj > regras.maxFaltasInjustificadasNoMes) {
        motivosBloqueio.push(`Possui ${faltasInj} falta(s) injustificada(s) (limite: ${regras.maxFaltasInjustificadasNoMes})`);
      }
      if (diasTrab < regras.minDiasTrabalhadosNoMes) {
        motivosBloqueio.push(`Dias trabalhados (${diasTrab}) abaixo do mínimo exigido (${regras.minDiasTrabalhadosNoMes})`);
      }

      const item = {
        colabId: c.id,
        nome: c.nome,
        funcao: c.funcao,
        empresaId: c.empresaId || 'emp-1',
        diasTrabalhados: diasTrab,
        faltasInjustificadas: faltasInj,
        elegivel: motivosBloqueio.length === 0,
        motivo: motivosBloqueio.length === 0 ? 'Critérios de assiduidade 100% atendidos' : motivosBloqueio.join('; ')
      };

      if (item.elegivel) elegiveis.push(item);
      else inabilitados.push(item);
    });

    return {
      sucesso: true,
      competencia: competenciaYm,
      regrasAplicadas: regras,
      totalElegiveis: elegiveis.length,
      totalInabilitados: inabilitados.length,
      custoTotalEstimadoCestas: arredondar2(elegiveis.length * regras.valorEstimadoCestaBasica),
      elegiveis,
      inabilitados
    };
  };

  // ==========================================================================
  // ETAPA 2.4 — FINANCEIRO AVANÇADO: BAIXA EM LOTE COM CHECKBOX (CONFERÊNCIA
  // PRÉVIA), PAINEL C ABA 7 (COMPARTILHAMENTO EM LOTE), ALERTA SEM OBRA, DRE E DFC
  // ==========================================================================

  window.executarBaixaEmLoteContasPagar = function(idsSelecionados = [], opcoesPagamento = {}, usuarioExecutor = window.currentLoggedUser) {
    if (!Array.isArray(idsSelecionados) || idsSelecionados.length === 0) {
      return { sucesso: false, codigo: 'LOTE_VAZIO', erro: 'Selecione ao menos um lançamento via checkbox para baixa em lote.' };
    }
    const sessao = window.exigirSessaoAutenticadaValida(usuarioExecutor);
    if (!sessao.autenticado) return { sucesso: false, codigo: sessao.codigo, erro: sessao.erro };
    const cfgPerm = window.obterPermissoesFinanceirasUsuario(sessao.usuario);
    if (!cfgPerm.permissoes.pagar && !cfgPerm.isMaster) {
      return { sucesso: false, codigo: 'PERMISSAO_PAGAR_LOTE_NEGADA', erro: 'Seu perfil não possui permissão para executar baixa em lote.' };
    }

    const itensNaoConferidos = [];
    const alvos = [];

    idsSelecionados.forEach(id => {
      const lanc = (window.lancamentosFinanceirosDb || []).find(l => l.id === id) || (window.obrigacoesPagarDb || []).find(o => o.id === id);
      if (!lanc) return;
      const jaConferidoOuAprovado = (
        lanc.statusConferencia === 'CONFERIDO' ||
        lanc.statusConferencia === 'APROVADO_DIRETORIA' ||
        lanc.status === 'APROVADO' ||
        lanc.estagioAtual === 'APROVACAO' ||
        lanc.statusFluxo6Estagios === '2_CONFERIDO' ||
        lanc.statusFluxo6Estagios === '3_APROVADO'
      );
      if (!jaConferidoOuAprovado) {
        itensNaoConferidos.push(id);
      } else {
        alvos.push(lanc);
      }
    });

    if (itensNaoConferidos.length > 0) {
      return {
        sucesso: false,
        codigo: 'BLOQUEIO_BAIXA_LOTE_SEM_CONFERENCIA_PREVIA',
        itensBloqueados: itensNaoConferidos,
        erro: `Conferência prévia obrigatória: Os lançamentos [${itensNaoConferidos.join(', ')}] ainda não foram conferidos/aprovados e não podem ser baixados em lote.`
      };
    }

    const baixados = [];
    let valorTotalBaixado = 0;

    alvos.forEach(lanc => {
      if (lanc.status !== 'APROVADO' && lanc.estagioAtual !== 'APROVACAO') {
        window.executarFluxoConferenciaDespesa(lanc.id, 'APROVAR', {}, sessao.usuario);
      }
      const resPg = window.executarFluxoConferenciaDespesa(lanc.id, 'PAGAR', opcoesPagamento, sessao.usuario);
      if (opcoesPagamento.confirmarImediatamente !== false) {
        window.executarFluxoConferenciaDespesa(lanc.id, 'CONFIRMAR', opcoesPagamento, sessao.usuario);
      }
      if (resPg && resPg.sucesso) {
        const val = Number(lanc.valorRealizado || lanc.valorPrevisto || lanc.valorOriginal || 0);
        valorTotalBaixado = arredondar2(valorTotalBaixado + val);
        baixados.push(lanc.id);
      }
    });

    return {
      sucesso: true,
      quantidadeBaixada: baixados.length,
      idsBaixados: baixados,
      valorTotalBaixado
    };
  };

  window.compartilhamentosLancamentosLoteDb = window.compartilhamentosLancamentosLoteDb || [];

  window.compartilharLancamentosFinanceirosEmLote = function(idsLancamentos = [], usuarioDestinoLogin, nivelAcesso = 'SOMENTE_VISUALIZACAO', usuarioExecutor = window.currentLoggedUser) {
    const sessao = window.exigirSessaoAutenticadaValida(usuarioExecutor);
    if (!sessao.autenticado) return { sucesso: false, codigo: sessao.codigo, erro: sessao.erro };
    const cfgPerm = window.obterPermissoesFinanceirasUsuario(sessao.usuario);
    if (!cfgPerm.isMaster) {
      return { sucesso: false, codigo: 'APENAS_MASTER_COMPARTILHA_LOTE', erro: 'Apenas o Master pode compartilhar lançamentos em lote no Painel C.' };
    }
    if (!Array.isArray(idsLancamentos) || idsLancamentos.length === 0 || !usuarioDestinoLogin) {
      return { sucesso: false, codigo: 'DADOS_COMPARTILHAMENTO_INVALIDOS', erro: 'Selecione ao menos um lançamento e o usuário de destino.' };
    }

    const compartilhados = [];
    idsLancamentos.forEach(id => {
      const lanc = (window.lancamentosFinanceirosDb || []).find(l => l.id === id) || (window.obrigacoesPagarDb || []).find(o => o.id === id);
      if (lanc) {
        lanc.compartilhadoComUsuarios = Array.isArray(lanc.compartilhadoComUsuarios) ? lanc.compartilhadoComUsuarios : [];
        lanc.compartilhadoComUsuarios.push({
          usuario: String(usuarioDestinoLogin).toLowerCase(),
          nivelAcesso,
          concedidoPor: sessao.usuario.usuario,
          dataHora: new Date().toISOString()
        });
        compartilhados.push(lanc.id);
      }
    });

    const reg = {
      id: 'SHARE-LOTE-' + Date.now(),
      idsCompartilhados: compartilhados,
      usuarioDestino: String(usuarioDestinoLogin).toLowerCase(),
      nivelAcesso,
      concedidoPor: sessao.usuario.usuario,
      dataHora: new Date().toISOString()
    };
    window.compartilhamentosLancamentosLoteDb.push(reg);
    return { sucesso: true, compartilhamento: reg };
  };

  window.apurarGastosSemObraVinculada = function(empresaId = 'todas') {
    const todos = window.lancamentosFinanceirosDb || [];
    const semObra = todos.filter(l => {
      if (empresaId !== 'todas' && l.empresaId !== empresaId) return false;
      return l.natureza === 'SAIDA' && (!l.obraId || l.obraId === '' || l.obraId === 'Geral');
    });
    return {
      sucesso: true,
      quantidadeSemObra: semObra.length,
      valorTotalSemObra: arredondar2(semObra.reduce((s, l) => s + Number(l.valorPrevisto || l.valorOriginal || 0), 0)),
      lancamentosSemObra: semObra
    };
  };

  /**
   * Gera DRE (Regime de Competência) e DFC (Regime de Caixa) estritamente separados!
   */
  window.gerarDreEDfcGerencial = function(filtros = {}, usuarioExecutor = window.currentLoggedUser) {
    const empFiltro = filtros.empresaId || 'todas';
    const todosLancs = (window.lancamentosFinanceirosDb || []).filter(l => empFiltro === 'todas' || l.empresaId === empFiltro);

    // 1. DRE — REGIME DE COMPETÊNCIA (considera fatos geradores aprovados/registrados, independentemente de liquidação bancária, excluindo cancelados/estornados)
    let receitaBrutaCompetencia = 0;
    let custosDiretosObrasCompetencia = 0;
    let despesasOperacionaisCompetencia = 0;
    let impostosEDeducoesCompetencia = 0;

    // 2. DFC — REGIME DE CAIXA (considera exclusivamente entradas e saídas efetivamente CONFIRMADAS no caixa/banco)
    let entradasCaixaOperacional = 0;
    let saidasCaixaFornecedoresEObras = 0;
    let totalPrevistoPendente = 0;
    let totalEstornadoOuCancelado = 0;

    todosLancs.forEach(l => {
      const valOrig = Number(l.valorPrevisto ?? l.valorOriginal ?? 0);
      const valReal = Number(l.valorRealizado ?? l.valorPagoAcumulado ?? l.valorRecebido ?? 0);
      const isEstornado = l.status === 'ESTORNADO' || l.status === 'CANCELADO' || l.status === 'CANCELADO_POR_NFE';

      if (isEstornado) {
        totalEstornadoOuCancelado = arredondar2(totalEstornadoOuCancelado + valOrig);
        return;
      }

      if (l.natureza === 'ENTRADA') {
        if (l.statusFluxo6Estagios !== 'PREVISTO_ORCAMENTO') {
          receitaBrutaCompetencia = arredondar2(receitaBrutaCompetencia + valOrig);
        }
        if (l.status === 'CONFIRMADO' || l.status === 'RECEBIDO_CONFIRMADO' || l.status === 'RECEBIDO' || valReal > 0) {
          entradasCaixaOperacional = arredondar2(entradasCaixaOperacional + (valReal || valOrig));
        } else {
          totalPrevistoPendente = arredondar2(totalPrevistoPendente + valOrig);
        }
      } else {
        const cat = String(l.categoriaFinanceira || '').toLowerCase();
        if (l.statusFluxo6Estagios !== 'PREVISTO_ORCAMENTO') {
          if (cat.includes('imposto') || cat.includes('taxa')) {
            impostosEDeducoesCompetencia = arredondar2(impostosEDeducoesCompetencia + valOrig);
          } else if (l.obraId) {
            custosDiretosObrasCompetencia = arredondar2(custosDiretosObrasCompetencia + valOrig);
          } else {
            despesasOperacionaisCompetencia = arredondar2(despesasOperacionaisCompetencia + valOrig);
          }
        }

        if (l.status === 'CONFIRMADO' || l.estagioAtual === 'CONFIRMACAO' || l.statusFluxo6Estagios === '5_CONFIRMADO' || l.statusFluxo6Estagios === '6_CONCILIADO') {
          saidasCaixaFornecedoresEObras = arredondar2(saidasCaixaFornecedoresEObras + (valReal || valOrig));
        } else {
          totalPrevistoPendente = arredondar2(totalPrevistoPendente + (valOrig - valReal));
        }
      }
    });

    const receitaLiquidaCompetencia = arredondar2(receitaBrutaCompetencia - impostosEDeducoesCompetencia);
    const lucroBrutoCompetencia = arredondar2(receitaLiquidaCompetencia - custosDiretosObrasCompetencia);
    const resultadoLiquidoExercicioDre = arredondar2(lucroBrutoCompetencia - despesasOperacionaisCompetencia);
    const geracaoCaixaOperacionalDfc = arredondar2(entradasCaixaOperacional - saidasCaixaFornecedoresEObras);

    return {
      sucesso: true,
      empresaId: empFiltro,
      separacaoEstritaCompetenciaECaixa: true,
      dreRegimeCompetencia: {
        receitaBrutaCompetencia,
        impostosEDeducoesCompetencia,
        receitaLiquidaCompetencia,
        custosDiretosObrasCompetencia,
        lucroBrutoCompetencia,
        despesasOperacionaisCompetencia,
        resultadoLiquidoExercicioDre
      },
      dfcRegimeCaixa: {
        entradasCaixaOperacional,
        saidasCaixaFornecedoresEObras,
        geracaoCaixaOperacionalDfc,
        totalPrevistoPendenteNaoLiquidado: totalPrevistoPendente,
        totalEstornadoOuCancelado
      }
    };
  };

