    const simSer = window.ultimoCalculoSerralheriaUi || window.calcularOrcamentoETecnicaSerralheria({ tipoProduto: 'PORTAO', larguraMm: 3000, alturaMm: 2200 });
    const simEsq = window.ultimoCalculoEsquadriaUi || window.calcularEngenhariaCompletaEsquadria({ tipologiaId: 'J2F', larguraMm: 1500, alturaMm: 1200, tipoVidroId: 'TEMPERADO_6MM' });

