    NOTAS_FISCAIS: { bucket: 'martins-financeiro-fiscal-privado', pasta: 'nfe_xml_danfe', maxMb: 20 },
    DOCS_VEICULOS: { bucket: 'martins-frota-estoque-privado', pasta: 'frota_crlv_seguro', maxMb: 15 },
    ASSINATURAS: { bucket: 'martins-rh-sst-privado', pasta: 'assinaturas_digitais', maxMb: 5 },
    ANEXOS_FINANCEIROS: { bucket: 'martins-financeiro-fiscal-privado', pasta: 'anexos_financeiros', maxMb: 20 },
    DOCS_COMPRAS_ESTOQUE: { bucket: 'martins-frota-estoque-privado', pasta: 'compras_cotacoes_estoque', maxMb: 15 }
