  window.pesquisarObrasNoSeletorMobile = function (termo = '') {
    return window.abrirSeletorObraResponsivoMobile(window.estadoSeletorObraMobile.selectAlvoId, termo);
  };

  window.selecionarObraNoSeletorMobile = function (obraId, selectAlvoId = null) {
    const alvo = selectAlvoId || window.estadoSeletorObraMobile.selectAlvoId || 'obra-select';
    const catalogo = window.obterCatalogoUnificadoObrasErp();
    const obra = catalogo.find((o) => o.id === obraId || o.nome === obraId) || catalogo[0];

    window.estadoSeletorObraMobile.obraSelecionadaId = obra.id;
    window.obraAtivaGestaoId = obra.id;

    if (typeof document !== 'undefined') {
      const sel = document.getElementById(alvo);
      if (sel) {
        let optExiste = Array.from(sel.options || []).some((op) => op.value === obra.id || op.value === obra.nome);
        if (!optExiste && typeof document.createElement === 'function') {
          const novaOpt = document.createElement('option');
          novaOpt.value = obra.id;
          novaOpt.textContent = `${obra.codigo} — ${obra.nome}`;
          sel.appendChild(novaOpt);
        }
        sel.value = Array.from(sel.options || []).some((op) => op.value === obra.id) ? obra.id : obra.nome;
        if (typeof sel.dispatchEvent === 'function' && typeof Event === 'function') {
          try { sel.dispatchEvent(new Event('change', { bubbles: true })); } catch (e) {}
        }
      }
    }

    window.fecharSeletorObraMobile();
    window.renderizarBannerObraAtivaGestao(obra.id);

    return {
      sucesso: true,
      obraSelecionada: obra,
      listaFechadaCorretamente: !window.estadoSeletorObraMobile.aberto
    };
  };

  window.fecharSeletorObraMobile = function () {
    window.estadoSeletorObraMobile.aberto = false;
    if (typeof document !== 'undefined') {
      const modal = document.getElementById('modal-seletor-obra-mobile-erp');
      if (modal) {
        modal.classList.add('hidden');
        if (modal.style) modal.style.display = 'none';
      }
    }
    return { sucesso: true, aberto: false };
  };

  // ==========================================================================
