  window.obraAtivaGestaoId = window.obraAtivaGestaoId || 'OBR-UEMG-01';

  window.selecionarObraAtivaGestao = function (obraId) {
    const catalogo = window.obterCatalogoUnificadoObrasErp();
    const obra = catalogo.find((o) => o.id === obraId || o.nome === obraId) || catalogo[0];
    window.obraAtivaGestaoId = obra.id;
    window.renderizarBannerObraAtivaGestao(obra.id);
    return {
      sucesso: true,
      obraAtiva: obra,
      identificacaoVisivelEntreAbas: true
    };
  };

  window.renderizarBannerObraAtivaGestao = function (obraIdParam = null) {
    const idAlvo = obraIdParam || window.obraAtivaGestaoId || 'OBR-UEMG-01';
    const catalogo = window.obterCatalogoUnificadoObrasErp();
    const obra = catalogo.find((o) => o.id === idAlvo || o.nome === idAlvo) || catalogo[0];
    // Sem obras cadastradas (ambiente novo), não há banner; evita interromper a inicialização das telas.
    if (!obra) return { sucesso: false, codigo: 'SEM_OBRAS', erro: 'Nenhuma obra cadastrada.' };
    window.obraAtivaGestaoId = obra.id;

    if (typeof document === 'undefined') {
      return {
        sucesso: true,
        obraAtiva: obra,
        camposExibidos: ['nome', 'cliente', 'codigo', 'situacao', 'indicadorVisual']
      };
    }

    const secGestao = document.getElementById('view-gestao');
    if (!secGestao) return { sucesso: true, obraAtiva: obra };

    let banner = document.getElementById('banner-identificacao-obra-ativa-gestao');
    if (!banner) {
      banner = document.createElement('div');
      banner.id = 'banner-identificacao-obra-ativa-gestao';
      banner.className = 'bg-slate-900 text-white rounded-2xl p-3 sm:p-4 border-2 border-amber-500 shadow-md mb-3';
      secGestao.prepend(banner);
    }

    banner.innerHTML = `
      <div class="flex flex-wrap items-center justify-between gap-2 text-xs">
        <div class="flex items-center gap-2.5 min-w-0">
          <span class="px-2.5 py-1 rounded-lg bg-amber-500 text-slate-950 font-black text-[10px] uppercase tracking-wider shrink-0 flex items-center gap-1">
            <span class="w-2 h-2 rounded-full bg-slate-950 animate-ping"></span>
            Obra Ativa Selecionada
          </span>
          <div class="min-w-0">
            <div class="font-black text-sm sm:text-base text-amber-300 truncate" id="lbl-gestao-obra-ativa-nome">${esc(obra.nome)}</div>
            <div class="text-[11px] text-slate-300 flex flex-wrap items-center gap-x-3 gap-y-0.5">
              <span><strong>Código:</strong> <span id="lbl-gestao-obra-ativa-codigo" class="font-mono text-white">${esc(obra.codigo)}</span></span>
              <span><strong>Cliente:</strong> <span id="lbl-gestao-obra-ativa-cliente" class="text-white">${esc(obra.cliente)}</span></span>
              <span><strong>Situação:</strong> <span id="lbl-gestao-obra-ativa-situacao" class="px-2 py-0.5 rounded bg-emerald-500/20 text-emerald-300 border border-emerald-400/30 font-bold text-[10px]">${esc(obra.situacao)}</span></span>
            </div>
          </div>
        </div>
        <div class="flex items-center gap-1.5 shrink-0">
          <button type="button" onclick="window.abrirSeletorObraResponsivoMobile('gestao-obra-select')" class="px-3 py-1.5 rounded-xl bg-amber-500 hover:bg-amber-400 text-slate-950 font-black text-xs shrink-0">🔍 Buscar Obra pelo Nome</button>
        </div>
      </div>
    `;

    return {
      sucesso: true,
      obraAtiva: obra,
      camposExibidos: ['nome', 'cliente', 'codigo', 'situacao', 'indicadorVisual']
    };
  };

