  window.atualizarSimulacaoTelhaRapidaUi = function () {
    if (typeof document === 'undefined') return;
    const tipo = document.getElementById('telha-rap-tipo')?.value || 'Sanduíche';
    const comp = parseFloat(document.getElementById('telha-rap-comp')?.value || '6') || 6;
    const larg = parseFloat(document.getElementById('telha-rap-larg')?.value || '1') || 1;
    const qtd = parseFloat(document.getElementById('telha-rap-qtd')?.value || '10') || 10;
    const negInp = document.getElementById('telha-rap-preco-neg');
    const precoNeg = parseFloat(negInp?.value || '0') || window.configuracaoPrecosPadraoTelhasM2[tipo] || 98;

    const sim = window.calcularEGerarOrcamentoRapidoTelhas({
      tipoTelha: tipo,
      comprimento: comp,
      larguraUtil: larg,
      quantidade: qtd,
      precoUnitarioNegociado: precoNeg,
      apenasSimular: true
    });

    const elArea = document.getElementById('lbl-telha-area-total');
    const elPad = document.getElementById('lbl-telha-preco-padrao');
    const elNeg = document.getElementById('lbl-telha-preco-negociado');
    const elTot = document.getElementById('lbl-telha-total-final');

    if (elArea) elArea.textContent = `${sim.areaTotalM2.toFixed(2)} m²`;
    if (elPad) elPad.textContent = formatarMoeda(sim.precoPadraoM2);
    if (elNeg) elNeg.textContent = formatarMoeda(sim.precoUnitarioNegociado);
    if (elTot) elTot.textContent = formatarMoeda(sim.valorTotalFinal);
    return sim;
  };

  window.salvarOrcamentoRapidoTelhasDaTela = function (abrirPdf = true) {
    const cliente = document.getElementById('telha-rap-cliente')?.value || 'Cliente Telhas';
    const obra = document.getElementById('telha-rap-obra')?.value || 'OBR-GALPAO-ACOS-03';
    const tipoTelha = document.getElementById('telha-rap-tipo')?.value || 'Sanduíche';
    const comprimento = parseFloat(document.getElementById('telha-rap-comp')?.value || '6') || 6;
    const larguraUtil = parseFloat(document.getElementById('telha-rap-larg')?.value || '1') || 1;
    const quantidade = parseFloat(document.getElementById('telha-rap-qtd')?.value || '12') || 12;
    const precoUnitarioNegociado = parseFloat(document.getElementById('telha-rap-preco-neg')?.value || '98') || 98;

    const res = window.calcularEGerarOrcamentoRapidoTelhas({
      cliente,
      obra,
      tipoTelha,
      comprimento,
      larguraUtil,
      quantidade,
      precoUnitarioNegociado
    });
    if (res.sucesso && abrirPdf) {
      window.gerarPropostaPdfOrcamentoCompleta(res.orcamento.id, { incluirImagens: true });
    }
    return res;
  };

