  window.definirPermissoesFinanceirasNoPerfilUsuario = function (usuarioIdOuLogin, configuracao = {}, usuarioAdmin = window.currentLoggedUser) {
    const perfilNome = configuracao.perfil || 'Conferente Financeiro';
    const base =
      window.PERFIS_ESTRUTURAIS_PADRAO_FINANCEIRO[perfilNome] ||
      window.PERFIS_ESTRUTURAIS_PADRAO_FINANCEIRO.PadraoRestrito;

    // Garante que Conferente Financeiro não receba aprovar/pagar/receber/excluir automaticamente a menos que explicitamente autorizado
    const ehConferente = perfilNome === 'Conferente Financeiro';
    const permissoesFinais = {
      ...base,
      ...(configuracao.permissoesEspecificas || {}),
      aprovar: ehConferente ? Boolean(configuracao.concederAprovacaoExplicita === true) : Boolean(configuracao.permissoesEspecificas?.aprovar ?? base.aprovar),
      pagar: ehConferente ? Boolean(configuracao.concederPagamentoExplicito === true) : Boolean(configuracao.permissoesEspecificas?.pagar ?? base.pagar),
      receber: ehConferente ? Boolean(configuracao.concederRecebimentoExplicito === true) : Boolean(configuracao.permissoesEspecificas?.receber ?? base.receber),
      excluirOuCancelar: ehConferente ? Boolean(configuracao.concederExclusaoExplicita === true) : Boolean(configuracao.permissoesEspecificas?.excluirOuCancelar ?? base.excluirOuCancelar)
    };

    window.mapaPermissoesFinanceirasCentralizadasDb = window.mapaPermissoesFinanceirasCentralizadasDb || {};
    window.mapaPermissoesFinanceirasCentralizadasDb[String(usuarioIdOuLogin).toLowerCase()] = {
      usuario: String(usuarioIdOuLogin).toLowerCase(),
      perfil: perfilNome,
      empresasAutorizadas: configuracao.empresasAutorizadas || ['emp-1'],
      modulosVisiveis: configuracao.modulosVisiveis || ['financeiro'],
      permissoesFinanceiras: permissoesFinais,
      atualizadoPor: usuarioAdmin?.usuario || 'henrique',
      atualizadoEm: new Date().toISOString()
    };

    salvarJsonStorage('cm_permissoes_financeiras_centralizadas_db', window.mapaPermissoesFinanceirasCentralizadasDb);
    const conf = window.emitirConfirmacaoOficialErp('PERMISSOES_ATUALIZADAS');

    return {
      sucesso: true,
      usuario: String(usuarioIdOuLogin).toLowerCase(),
      perfil: perfilNome,
      permissoesFinanceiras: permissoesFinais,
      mensagem: conf.mensagem
    };
  };

  window.avaliarAcaoFinanceiraPorPerfil = function (usuarioObjOuLogin, acaoSolicitada) {
    const login =
      typeof usuarioObjOuLogin === 'string'
        ? usuarioObjOuLogin.toLowerCase()
        : String(usuarioObjOuLogin?.usuario || usuarioObjOuLogin?.id || 'henrique').toLowerCase();

    const reg =
      (window.mapaPermissoesFinanceirasCentralizadasDb || {})[login] ||
      (usuarioObjOuLogin?.perfil === 'Conferente Financeiro'
        ? {
            perfil: 'Conferente Financeiro',
            permissoesFinanceiras: window.PERFIS_ESTRUTURAIS_PADRAO_FINANCEIRO['Conferente Financeiro']
          }
        : null);

    const perms =
      reg?.permissoesFinanceiras ||
      window.PERFIS_ESTRUTURAIS_PADRAO_FINANCEIRO[usuarioObjOuLogin?.perfil] ||
      window.PERFIS_ESTRUTURAIS_PADRAO_FINANCEIRO.PadraoRestrito;

    const mapaAcao = {
      VISUALIZAR: perms.visualizacaoFinanceira !== 'NENHUMA',
      CADASTRAR: Boolean(perms.cadastrar),
      EDITAR: Boolean(perms.editar),
      CONFERIR: Boolean(perms.conferir),
      ENCAMINHAR_APROVACAO: Boolean(perms.encaminharParaAprovacao),
      APROVAR: Boolean(perms.aprovar),
      PAGAR: Boolean(perms.pagar),
      RECEBER: Boolean(perms.receber),
      CONCILIAR: Boolean(perms.conciliar),
      EXCLUIR: Boolean(perms.excluirOuCancelar),
      COMPARTILHAR: Boolean(perms.compartilharRegistros)
    };

    const permitido = Boolean(mapaAcao[String(acaoSolicitada).toUpperCase()]);
    return {
      permitido,
      acao: acaoSolicitada,
      perfil: reg?.perfil || usuarioObjOuLogin?.perfil || 'PadraoRestrito',
      permissoesFinanceiras: perms
    };
  };

  // Item 16 — Compartilhamento Financeiro Granular Avançado (por pessoa(s), conta bancária, período, contínuo, obra ou lote)
  window.regrasCompartilhamentoFinanceiroGranularDb = lerJsonStorage('cm_regras_compartilhamento_fin_granular_db', []);

  window.concederCompartilhamentoFinanceiroGranularAvancado = function (dados = {}, usuarioExecutor = window.currentLoggedUser) {
    const user = usuarioExecutor || window.currentLoggedUser || { usuario: 'henrique', nome: 'Henrique Camilo', perfil: 'Master' };
    const aval = window.avaliarAcaoFinanceiraPorPerfil(user, 'COMPARTILHAR');
    const ehMaster = String(user.perfil || '').toLowerCase().includes('master') || user.usuario === 'henrique';

    if (!aval.permitido && !ehMaster) {
      return {
        sucesso: false,
        codigo: 'SEM_PERMISSAO_COMPARTILHAR_FINANCEIRO',
        erro: 'Apenas administradores ou usuários com permissão de compartilhamento podem compartilhar dados financeiros.'
      };
    }

    const usuariosDestino = (
      Array.isArray(dados.usuariosDestino)
        ? dados.usuariosDestino
        : [dados.usuarioDestino || dados.usuariosDestino || 'samara']
    )
      .map((u) => String(u).trim().toLowerCase())
      .filter(Boolean);

    if (usuariosDestino.length === 0) {
      return { sucesso: false, erro: 'Selecione pelo menos um usuário destinatário para o compartilhamento.' };
    }

    const novaRegra = {
      id: 'SHARE-FIN-' + Date.now() + '-' + Math.floor(Math.random() * 1000),
      usuariosDestino,
      empresaId: dados.empresaId || 'emp-1',
      escopo: dados.escopo || 'CONTA_PERIODO', // 'LANCAMENTO_ESPECIFICO' | 'LOTE_LANCAMENTOS' | 'CONTA_PERIODO' | 'CONTA_CONTINUA' | 'OBRA_ESPECIFICA'
      lancamentosIds: Array.isArray(dados.lancamentosIds) ? dados.lancamentosIds : dados.lancamentoId ? [dados.lancamentoId] : [],
      contaBancariaId: dados.contaBancariaId || null,
      dataInicio: dados.dataInicio || null,
      dataFim: dados.dataFim || null,
      continuoContaCorrente: Boolean(dados.continuoContaCorrente || dados.escopo === 'CONTA_CONTINUA'),
      obraId: dados.obraId || null,
      somenteLeitura: dados.somenteLeitura !== false,
      permitirEdicao: Boolean(dados.permitirEdicao === true && dados.somenteLeitura === false),
      validoAte: dados.validoAte || null,
      ativa: true,
      revogada: false,
      concedidoPor: user.usuario || 'henrique',
      concedidoEm: new Date().toISOString(),
      historico: [
        {
          acao: 'CONCESSAO_COMPARTILHAMENTO',
          por: user.usuario || 'henrique',
          dataHora: new Date().toISOString()
        }
      ]
    };

    window.regrasCompartilhamentoFinanceiroGranularDb.unshift(novaRegra);
    salvarJsonStorage('cm_regras_compartilhamento_fin_granular_db', window.regrasCompartilhamentoFinanceiroGranularDb);

    return {
      sucesso: true,
      regra: novaRegra
    };
  };

  window.revogarCompartilhamentoFinanceiroGranular = function (regraId, usuarioExecutor = window.currentLoggedUser) {
    const regra = (window.regrasCompartilhamentoFinanceiroGranularDb || []).find((r) => r.id === regraId);
    if (!regra) return { sucesso: false, erro: 'Regra de compartilhamento não localizada.' };
    regra.ativa = false;
    regra.revogada = true;
    regra.revogadaEm = new Date().toISOString();
    regra.historico = Array.isArray(regra.historico) ? regra.historico : [];
    regra.historico.push({
      acao: 'REVOGACAO_COMPARTILHAMENTO',
      por: usuarioExecutor?.usuario || 'henrique',
      dataHora: regra.revogadaEm
    });
    salvarJsonStorage('cm_regras_compartilhamento_fin_granular_db', window.regrasCompartilhamentoFinanceiroGranularDb);
    return { sucesso: true, regraId, revogada: true };
  };

  window.verificarAcessoLancamentoPorCompartilhamentoGranular = function (lancamento, usuarioObj) {
    if (!lancamento || !usuarioObj) return false;
    const login = String(usuarioObj.usuario || usuarioObj.id || '').toLowerCase();
    const empresasUsuario = Array.isArray(usuarioObj.empresas)
      ? usuarioObj.empresas
      : [usuarioObj.empresaId || 'emp-1'];

    // Regra de segurança multiempresa: nunca rompe isolamento de empresa não autorizada, a menos que a regra autorize explicitamente a empresa
    const hojeIso = obterDataHojeIso();

    const regrasAtivas = (window.regrasCompartilhamentoFinanceiroGranularDb || []).filter((r) => {
      if (!r || !r.ativa || r.revogada) return false;
      if (!r.usuariosDestino.includes(login)) return false;
      if (r.validoAte && r.validoAte < hojeIso) return false;
      if (r.empresaId && lancamento.empresaId && r.empresaId !== lancamento.empresaId) return false;
      if (r.empresaId && !empresasUsuario.includes(r.empresaId) && !empresasUsuario.includes('todas')) return false;
      return true;
    });

    for (const r of regrasAtivas) {
      if (r.lancamentosIds && r.lancamentosIds.includes(lancamento.id)) return true;
      if (r.continuoContaCorrente && r.contaBancariaId && lancamento.contaBancariaId === r.contaBancariaId) return true;
      if (
        r.escopo === 'CONTA_PERIODO' &&
        r.contaBancariaId &&
        lancamento.contaBancariaId === r.contaBancariaId &&
        (!r.dataInicio || lancamento.data >= r.dataInicio) &&
        (!r.dataFim || lancamento.data <= r.dataFim)
      ) {
        return true;
      }
      if (r.obraId && (lancamento.obraId === r.obraId || lancamento.obra === r.obraId)) return true;
    }

    return false;
  };

  // Integra a verificação granular na camada de consulta financeira (listarLancamentosVisiveisParaUsuario)
  const _origListarLancVisiveis = window.listarLancamentosVisiveisParaUsuario;
  window.listarLancamentosVisiveisParaUsuario = function (usuarioObj, filtros = {}) {
    const base =
      typeof _origListarLancVisiveis === 'function'
        ? _origListarLancVisiveis(usuarioObj, filtros)
        : window.lancamentosFinanceirosDb || [];

    const todos = window.lancamentosFinanceirosDb || [];
    const idsJaIncluidos = new Set(base.map((l) => l.id));

    todos.forEach((lanc) => {
      if (!idsJaIncluidos.has(lanc.id) && window.verificarAcessoLancamentoPorCompartilhamentoGranular(lanc, usuarioObj)) {
        base.push(lanc);
        idsJaIncluidos.add(lanc.id);
      }
    });

    return base;
  };

  // ==========================================================================
  // ITEM 17 — CADASTRO DE USUÁRIOS: TODAS AS FUNCIONALIDADES EXISTENTES NO
  // SISTEMA ORGANIZADAS POR MÓDULO (SELEÇÃO INDIVIDUAL, POR MÓDULO, SELECIONAR
