  // Correção Crítica da Auditoria (Seção 3): PROIBIR que um orçamento vazio gere automaticamente produto fictício, quantidade 1 ou preço R$ 100!
  const _origCriarOrcUnificado = window.criarOrcamentoUnificadoComVendedorEElaborador;
  window.criarOrcamentoUnificadoComVendedorEElaborador = function (dados = {}, usuarioElaborador = window.currentLoggedUser) {
    const itens = dados.itens;
    if (!Array.isArray(itens) || itens.length === 0) {
      return {
        sucesso: false,
        bloqueadoPorOrcamentoVazio: true,
        gerouProdutoFicticio: false,
        codigo: 'ORCAMENTO_VAZIO_SEM_ITENS_REAIS',
        erro: 'Não é permitido criar ou salvar um orçamento vazio. Adicione pelo menos um item real com descrição, quantidade e valor unitário válidos.'
      };
    }

    for (let i = 0; i < itens.length; i++) {
      const it = itens[i] || {};
      const desc = String(it.descricao || it.desc || '').trim();
      const qtd = Number(it.quantidade != null ? it.quantidade : it.qtd || 0);
      const valUnit = Number(it.valorUnitario != null ? it.valorUnitario : it.precoUnit != null ? it.precoUnit : it.precoUnitario || 0);
      if (!desc || qtd <= 0 || valUnit <= 0) {
        return {
          sucesso: false,
          bloqueadoPorItemInvalido: true,
          gerouProdutoFicticio: false,
          codigo: 'ITEM_ORCAMENTO_INVALIDO_OU_ZERADO',
          erro: `O item #${i + 1} do orçamento possui descrição vazia, quantidade inválida (${qtd}) ou preço unitário inválido (${valUnit}). Informe dados reais.`
        };
      }
    }

    return _origCriarOrcUnificado.call(this, dados, usuarioElaborador);
  };

