  // ==========================================================================
  // SEÇÃO 5 — ESTOQUE (PRIORIDADE ALTA): CONVERSÃO ENTRE COMPRA, ESTOQUE E VENDA,
  // PROTEÇÃO CONTRA MOVIMENTAÇÕES DUPLICADAS E INTEGRAÇÃO COM OBRAS/COMPRAS/VENDAS
  // ==========================================================================
  window.chavesMovimentacoesEstoqueProcessadas = new Set();

  window.executarMovimentacaoEstoqueMultimedidaCompleta = function (dados = {}, usuarioExecutor = window.currentLoggedUser) {
    const tipo = String(dados.tipoMovimentacao || dados.tipo || 'ENTRADA').toUpperCase(); // ENTRADA | SAIDA | TRANSFERENCIA | CONSUMO_OBRA | BAIXA_VENDA
    const chaveIdemp =
      dados.chaveIdempotencia ||
      `${tipo}-${dados.produtoId || dados.codigoProduto}-${dados.depositoId || dados.depositoOrigemId || 'DEP'}-${dados.quantidade}-${dados.documentoReferencia || ''}`;

    if (dados.bloquearDuplicidade !== false && window.chavesMovimentacoesEstoqueProcessadas.has(chaveIdemp)) {
      return {
        sucesso: false,
        duplicidadeBloqueada: true,
        codigo: 'MOVIMENTACAO_ESTOQUE_DUPLICADA_BLOQUEADA',
        erro: 'Esta movimentação de estoque já foi processada (proteção contra duplicidade ativa).'
      };
    }

    const prodsCat = window.produtosCatalogoCompletoDb || [];
    const prodsFat = typeof window.getProdutosFatorDb === 'function' ? window.getProdutosFatorDb() : [];
    const prod =
      prodsCat.find((p) => p.id === dados.produtoId || p.codigo === dados.codigoProduto) ||
      prodsFat.find((p) => p.id === dados.produtoId || p.codigo === dados.codigoProduto);

    if (!prod) {
      return { sucesso: false, codigo: 'PRODUTO_NAO_CADASTRADO', erro: 'Produto não localizado no estoque.' };
    }

    // Valida fator de conversão válido (> 0)
    const fatorCompraParaEstoque = Number(dados.fatorCompraParaEstoque || prod.fatorCompraParaEstoque || 1);
    const fatorEstoqueParaVenda = Number(dados.fatorConversao || prod.fatorConversao || prod.fatorEmb || 0);

    if (fatorCompraParaEstoque <= 0 || fatorEstoqueParaVenda <= 0 || Number.isNaN(fatorEstoqueParaVenda)) {
      return {
        sucesso: false,
        codigo: 'FATOR_CONVERSAO_INVALIDO_OU_AUSENTE',
        erro: 'Não é permitido realizar conversão de estoque sem fator de conversão válido maior que zero.'
      };
    }

    const qtdInformada = Number(dados.quantidade || 0);
    if (qtdInformada <= 0) {
      return { sucesso: false, codigo: 'QUANTIDADE_INVALIDA', erro: 'Informe uma quantidade maior que zero.' };
    }

    const unidadeOperacao = String(dados.unidadeOperacao || (tipo === 'ENTRADA' ? prod.unidadeCompra || 'KG' : prod.unidadeVenda || 'Metro')).trim();
    const unCompra = prod.unidadeCompra || prod.unCompra || 'KG';
    const unEstoque = prod.unidadePrincipalEstoque || unCompra;
    const unVenda = prod.unidadeVenda || prod.unVenda || 'Metro';

    // Converte a quantidade informada para a unidade de estoque e para a unidade de venda
    let qtdNaUnidadeEstoque = qtdInformada;
    let qtdEquivalenteVenda = arredondar4(qtdInformada * fatorEstoqueParaVenda);

    if (unidadeOperacao.toLowerCase() === unVenda.toLowerCase() && unVenda.toLowerCase() !== unEstoque.toLowerCase()) {
      // Ex: Vendeu ou consumiu em Metros, converte de volta para KG no estoque!
      qtdNaUnidadeEstoque = arredondar4(qtdInformada / fatorEstoqueParaVenda);
      qtdEquivalenteVenda = qtdInformada;
    }

    const resMov = window.registrarMovimentacaoEstoqueComConversaoEHistorico(
      {
        ...dados,
        tipoMovimentacao: tipo === 'CONSUMO_OBRA' || tipo === 'BAIXA_VENDA' ? 'SAIDA' : tipo,
        produtoId: prod.id,
        quantidade: qtdNaUnidadeEstoque
      },
      usuarioExecutor
    );

    if (!resMov.sucesso) return resMov;

    window.chavesMovimentacoesEstoqueProcessadas.add(chaveIdemp);
    resMov.movimentacao.unidadeOperacaoInformada = unidadeOperacao;
    resMov.movimentacao.quantidadeInformadaOriginal = qtdInformada;
    resMov.movimentacao.quantidadeNaUnidadeEstoque = qtdNaUnidadeEstoque;
    resMov.movimentacao.quantidadeEquivalenteUnidadeVenda = qtdEquivalenteVenda;

    return {
      ...resMov,
      unidadeCompra: unCompra,
      unidadeEstoque: unEstoque,
      unidadeVenda: unVenda,
      fatorAplicado: fatorEstoqueParaVenda,
      quantidadeNaUnidadeEstoque: qtdNaUnidadeEstoque,
      quantidadeEquivalenteUnidadeVenda: qtdEquivalenteVenda,
      duplicidadeBloqueada: false
    };
  };

  // ==========================================================================
