  window.cadastrarOuEditarContaCorrenteBancaria = function (dados = {}, usuarioExecutor = window.currentLoggedUser) {
    const nome = String(dados.nome || '').trim();
    const banco = String(dados.banco || '').trim();
    if (!nome || !banco) {
      return { sucesso: false, codigo: 'DADOS_CONTA_INCOMPLETOS', erro: 'Informe o nome da conta corrente e o banco.' };
    }

    window.contasCorrentesBancariasDb = Array.isArray(window.contasCorrentesBancariasDb)
      ? window.contasCorrentesBancariasDb
      : [];

    let conta = window.contasCorrentesBancariasDb.find((c) => c.id === dados.id);
    if (conta) {
      conta.nome = nome;
      conta.banco = banco;
      if (dados.agencia !== undefined) conta.agencia = dados.agencia;
      if (dados.conta !== undefined) conta.conta = dados.conta;
      if (dados.empresaId) conta.empresaId = dados.empresaId;
      if (dados.status) conta.status = dados.status;
      conta.atualizadoPor = usuarioExecutor?.usuario || 'master';
      conta.atualizadoEm = new Date().toISOString();
    } else {
      const saldoIni = arredondar2(Number(dados.saldoInicial || 0));
      conta = {
        id: dados.id || 'CTA-' + Date.now(),
        empresaId: dados.empresaId || 'emp-1',
        nome,
        banco,
        agencia: dados.agencia || '0001',
        conta: dados.conta || '00001-0',
        saldoInicial: saldoIni,
        saldoAtual: saldoIni,
        status: dados.status || 'Ativa',
        historicoAjustes: [
          {
            tipo: 'IMPLANTACAO_SALDO_INICIAL',
            saldoAnterior: 0,
            novoSaldo: saldoIni,
            justificativa: 'Implantação de saldo inicial da conta corrente',
            responsavel: usuarioExecutor?.nome || 'Administração',
            dataHora: new Date().toISOString()
          }
        ],
        criadoEm: new Date().toISOString()
      };
      window.contasCorrentesBancariasDb.unshift(conta);
    }

    salvarJsonStorage('cm_contas_correntes_bancarias_db', window.contasCorrentesBancariasDb);
    return { sucesso: true, conta };
  };

  window.registrarAjusteRastreavelContaBancaria = function (contaId, dadosAjuste = {}, usuarioExecutor = window.currentLoggedUser) {
    const conta = (window.contasCorrentesBancariasDb || []).find((c) => c.id === contaId);
    if (!conta) return { sucesso: false, erro: 'Conta corrente não localizada.' };

    const justificativa = String(dadosAjuste.justificativa || '').trim();
    if (justificativa.length < 5) {
      return {
        sucesso: false,
        codigo: 'JUSTIFICATIVA_AJUSTE_SALDO_OBRIGATORIA',
        erro: 'Informe uma justificativa rastreável (mínimo 5 caracteres) para ajustar o saldo bancário.'
      };
    }

    const saldoAnterior = arredondar2(Number(conta.saldoAtual || 0));
    const novoSaldo =
      dadosAjuste.novoSaldo != null
        ? arredondar2(Number(dadosAjuste.novoSaldo))
        : arredondar2(saldoAnterior + Number(dadosAjuste.valorDiferenca || 0));

    const registroAjuste = {
      id: 'AJ-CTA-' + Date.now(),
      contaId: conta.id,
      saldoAnterior,
      novoSaldo,
      diferenca: arredondar2(novoSaldo - saldoAnterior),
      justificativa,
      responsavel: usuarioExecutor?.nome || usuarioExecutor?.usuario || 'Master',
      dataHora: new Date().toISOString()
    };

    conta.saldoAtual = novoSaldo;
    conta.historicoAjustes = Array.isArray(conta.historicoAjustes) ? conta.historicoAjustes : [];
    conta.historicoAjustes.unshift(registroAjuste);

    salvarJsonStorage('cm_contas_correntes_bancarias_db', window.contasCorrentesBancariasDb);
    return {
      sucesso: true,
      conta,
      ajuste: registroAjuste,
      rastreabilidadeCompleta: true
    };
  };

