  window.chavesRateiosObrasProcessados = new Set();
  window.registrarGastoComObraERateioIntegrado = function (dados = {}) {
    const desc = String(dados.descricao || "").trim();
    const valorTotal = arredondar2(Number(dados.valorTotal || 0));
    const rateio = Array.isArray(dados.rateioObras) ? dados.rateioObras : [];
    if (!desc || valorTotal <= 0 || rateio.length === 0) {
      return { sucesso: false, erro: "Informe descrição, valor total maior que zero e obras para rateio." };
    }
    const chave = `${desc.toLowerCase()}|${dados.fornecedor || ""}|${valorTotal}|${dados.data || ""}`;
    if (window.chavesRateiosObrasProcessados.has(chave)) {
      return { sucesso: false, duplicidadeBloqueada: true, erro: "Gasto/rateio com obra duplicado bloqueado." };
    }
    const somaPerc = rateio.reduce((acc, r) => acc + Number(r.percentual || 0), 0);
    if (Math.abs(somaPerc - 100) > 0.01) {
      return { sucesso: false, erro: "A soma dos percentuais do rateio deve ser 100%." };
    }
    window.chavesRateiosObrasProcessados.add(chave);
    const lancamentosFinanceirosCriados = rateio.map((r, idx) => {
      const valParcela = arredondar2((valorTotal * Number(r.percentual)) / 100);
      return {
        id: `FIN-RAT-${Date.now()}-${idx + 1}`,
        natureza: "DESPESA_CUSTO_OBRA",
        descricao: `${desc} (Rateio ${r.percentual}% - ${r.obra})`,
        fornecedor: dados.fornecedor || "Fornecedor Obra",
        obra: r.obra,
        percentualRateio: Number(r.percentual),
        valor: valParcela,
        vencimento: dados.vencimento || obterDataHojeIso(),
        status: "Pendente"
      };
    });
    const gastosSalvos = lerJsonStorage("cm_gastos_rateio_obras_db", []);
    gastosSalvos.unshift({
      id: "GASTO-OBRA-" + Date.now(),
      ...dados,
      lancamentosFinanceirosCriados
    });
    salvarJsonStorage("cm_gastos_rateio_obras_db", gastosSalvos);
    return {
      sucesso: true,
      valorTotal,
      lancamentosFinanceirosCriados
    };
  };

