  window.gerarHoleritesLotePDFMultipaginaReal = function (dados = {}) {
    const competencia = dados.competencia || "11/2026";
    const empresa = dados.empresa || "Construtora & Incorporadora Martins Ltda";
    const funcs = Array.isArray(dados.funcionarios) ? dados.funcionarios : [];
    const linhas = [];
    // 3 funcionários por página (46 linhas por página em construirBinarioPdfA4Oficial; 3 linhas de cabeçalho inicial na pág 1 -> 14 linhas por funcionário)
    funcs.forEach((f, idx) => {
      linhas.push(`================================================================================`);
      linhas.push(`RECIBO DE PAGAMENTO DE SALÁRIO (HOLERITE OFICIAL) - COMPETÊNCIA: ${competencia}`);
      linhas.push(`EMPRESA: ${empresa} | OBRA: ${f.obra || "Canteiro Central"}`);
      linhas.push(`COLABORADOR [${String(idx + 1).padStart(2, "0")}]: ${f.nome} | CPF: ${f.cpf || "-"}`);
      linhas.push(`FUNÇÃO: ${f.cargo || "Operacional"} | VÍNCULO: CLT`);
      linhas.push(`--------------------------------------------------------------------------------`);
      linhas.push(`001 Salário Base Mensal ............................. Provento: ${formatarMoeda(f.salarioBase || 2500)}`);
      linhas.push(`002 Horas Extras 50% / 100% ......................... Provento: ${formatarMoeda((f.he50 || 0) + (f.he100 || 0))}`);
      linhas.push(`101 Desconto INSS Oficial ........................... Desconto: ${formatarMoeda(f.inss || 210)}`);
      linhas.push(`102 Adiantamento / Vales ............................ Desconto: ${formatarMoeda(f.vales || 0)}`);
      linhas.push(`BASE FGTS: ${formatarMoeda(f.salarioBase || 2500)} | FGTS DO MÊS (8%): ${formatarMoeda(f.fgts || 200)}`);
      linhas.push(`VALOR LÍQUIDO A RECEBER: ${formatarMoeda(f.liquido || 2290)}`);
      linhas.push(`Assinatura do Colaborador: ___________________________________ Data: ____/____/2026`);
      linhas.push(``);
      linhas.push(``);
    });
    const pdfBin = window.construirBinarioPdfA4Oficial(
      `HOLERITES EM LOTE OFICIAIS - COMPETÊNCIA ${competencia} (${funcs.length} COLABORADORES)`,
      linhas,
      { competencia, totalFuncionarios: funcs.length }
    );
    const bytes = new Uint8Array(pdfBin.conteudoBruto.length);
    for (let i = 0; i < pdfBin.conteudoBruto.length; i++) {
      bytes[i] = pdfBin.conteudoBruto.charCodeAt(i) & 0xff;
    }
    return {
      sucesso: true,
      competencia,
      totalFuncionarios: funcs.length,
      totalPaginas: pdfBin.totalPaginas,
      acentuacaoWinAnsiAtiva: true,
      bytes,
      pdfBinario: pdfBin
    };
  };

