  window.obterDadosCompletosObraParaAutoPreenchimento = function (obraIdentificador) {
    if (!obraIdentificador) return null;
    const q = String(obraIdentificador).trim().toLowerCase();

    // 1. Verifica no mapa oficial enriquecido
    for (const [cod, info] of Object.entries(window.CATALOGO_COMPLETO_DADOS_OBRAS_AUTOFILL)) {
      if (
        cod.toLowerCase() === q ||
        info.nome.toLowerCase() === q ||
        info.nomeExibicao.toLowerCase() === q ||
        (q === 'obr-ubs-passos-02' && cod === 'OBR-PAS-02') ||
        (q === 'obr-cemei-nh' && cod === 'OBR-PAS-01')
      ) {
        return { ...info };
      }
    }

    // 2. Verifica nos cadastros dinâmicos (empreendimentosObrasDb / obrasDb / dadosObras)
    const din = [...(window.empreendimentosObrasDb || []), ...(window.obrasDb || [])].find(
      (o) =>
        o &&
        (String(o.id || '').toLowerCase() === q ||
          String(o.codigo || '').toLowerCase() === q ||
          String(o.nome || '').toLowerCase() === q)
    );
    if (din) {
      const empId = din.empresaId || 'emp-1';
      return {
        id: din.id,
        codigo: din.codigo || din.id,
        nome: din.nome,
        nomeExibicao: din.nome,
        cliente: din.cliente || din.clienteResponsavel || '',
        endereco: din.endereco || (din.logradouro ? `${din.logradouro}${din.numero ? ', ' + din.numero : ''} - ${din.cidade || ''}` : ''),
        responsavelTecnico: din.responsavelTecnico || din.resp || '',
        empresaId: empId,
        empresaResponsavel:
          typeof window.obterNomeRealEmpresa === 'function'
            ? window.obterNomeRealEmpresa(empId)
            : empId,
        centroCustoId: din.centroCustoPrincipalId || '',
        centroCustoNome: din.centroCustoPrincipalNome || '',
        dataInicio: din.dataInicio || din.dataInicioPrevista || '',
        dataFim: din.dataFim || din.dataTerminoPrevista || '',
        valorContrato: Number(din.valorContrato || din.contrato || 0)
      };
    }

    return null;
  };

  window.preencherAutomaticamenteFormularioPorObra = function (
    obraIdentificador,
    opcoes = {},
    usuarioObj = window.currentLoggedUser
  ) {
    const dadosObra = window.obterDadosCompletosObraParaAutoPreenchimento(obraIdentificador);
    if (!dadosObra) {
      return {
        sucesso: false,
        codigo: 'OBRA_NAO_ENCONTRADA_PARA_AUTOFILL',
        semDadosFicticios: true,
        erro: 'Obra não localizada no cadastro oficial. Nenhum dado fictício foi preenchido.'
      };
    }

    // Respeita o contexto de empresa e permissões do usuário
    const empresaContexto = opcoes.empresaContextoId || null;
    if (empresaContexto && empresaContexto !== 'todas' && dadosObra.empresaId !== empresaContexto) {
      return {
        sucesso: false,
        codigo: 'OBRA_FORA_DO_CONTEXTO_DA_EMPRESA_SELECIONADA',
        erro: `A obra "${dadosObra.nome}" pertence à empresa ${dadosObra.empresaResponsavel} e não ao contexto selecionado.`
      };
    }

    if (usuarioObj && typeof window.validarAcessoEmpresaUsuario === 'function') {
      const checkPerm = window.validarAcessoEmpresaUsuario(usuarioObj, dadosObra.empresaId);
      if (!checkPerm.autorizado) {
        return {
          sucesso: false,
          codigo: checkPerm.codigo || 'SEM_PERMISSAO_EMPRESA_OBRA',
          erro: checkPerm.erro
        };
      }
    }

    const estadoFormularioAtual = opcoes.camposAtuaisFormulario || {};
    const confirmarSubstituicao = Boolean(opcoes.confirmarSubstituicao === true);
    const camposPreenchidos = {};
    const camposPreservadosSemSobrescrever = [];

    const mapaCamposAlvo = {
      nomeObra: dadosObra.nome,
      clienteContratante: dadosObra.cliente,
      endereco: dadosObra.endereco,
      responsavelTecnico: dadosObra.responsavelTecnico,
      empresaId: dadosObra.empresaId,
      empresaResponsavel: dadosObra.empresaResponsavel,
      centroCustoId: dadosObra.centroCustoId,
      centroCustoNome: dadosObra.centroCustoNome,
      dataInicio: dadosObra.dataInicio,
      dataFim: dadosObra.dataFim
    };

    Object.entries(mapaCamposAlvo).forEach(([chave, valorDaObra]) => {
      // Se não existir valor no cadastro oficial, não inventa dado fictício
      if (valorDaObra === undefined || valorDaObra === null || valorDaObra === '') {
        camposPreenchidos[chave] = '';
        return;
      }

      const valorJaDigitadoPeloUsuario = estadoFormularioAtual[chave];
      const foiPreenchidoManualmente =
        valorJaDigitadoPeloUsuario !== undefined &&
        valorJaDigitadoPeloUsuario !== null &&
        String(valorJaDigitadoPeloUsuario).trim() !== '' &&
        opcoes.trocaExplicitaDeObra !== true;

      if (foiPreenchidoManualmente && !confirmarSubstituicao) {
        camposPreenchidos[chave] = valorJaDigitadoPeloUsuario;
        camposPreservadosSemSobrescrever.push(chave);
      } else {
        camposPreenchidos[chave] = valorDaObra;
      }
    });

    // Atualiza o DOM do RDO e formulários vinculados quando disponível
    if (typeof document !== 'undefined') {
      const elRespDisplay = document.getElementById('resp-fixo-display');
      if (elRespDisplay && camposPreenchidos.responsavelTecnico) {
        elRespDisplay.value = camposPreenchidos.responsavelTecnico;
      }
      const elRespSelect = document.getElementById('resp-select');
      if (elRespSelect && camposPreenchidos.responsavelTecnico) {
        const nomeLimpoResp = camposPreenchidos.responsavelTecnico.split('(')[0].replace(/Eng[ª.]?\s*/i, '').trim();
        elRespSelect.innerHTML = `<option value="${nomeLimpoResp}" selected>${camposPreenchidos.responsavelTecnico}</option>`;
        elRespSelect.value = nomeLimpoResp;
      }
      const elContratante = document.getElementById('rdo-prazo-contratante');
      if (elContratante) {
        elContratante.textContent = `${camposPreenchidos.clienteContratante} · ${camposPreenchidos.endereco || ''} · ${camposPreenchidos.empresaResponsavel}`;
      }
      const elDatas = document.getElementById('rdo-prazo-datas');
      if (elDatas && camposPreenchidos.dataInicio && camposPreenchidos.dataFim) {
        elDatas.textContent = `Ordem de Serviço: ${camposPreenchidos.dataInicio} · Término Previsto: ${camposPreenchidos.dataFim}`;
      }
    }

    window.ultimoAutoPreenchimentoObra = {
      obraId: dadosObra.id,
      camposPreenchidos,
      timestamp: new Date().toISOString()
    };

    return {
      sucesso: true,
      obraId: dadosObra.id,
      dadosRecuperados: camposPreenchidos,
      camposPreservadosSemSobrescrever,
      semCadastrosDuplicados: true,
      semDadosFicticios: true,
      registrosHistoricosPreservados: true
    };
  };

