  window.obterConfiguracaoNavegacaoInicialPorPerfil = function (usuarioObj = window.currentLoggedUser) {
    const u = usuarioObj || { usuario: 'operador', perfil: 'Encarregado', empresas: ['emp-1'] };
    const login = String(u.usuario || u.login || '').toLowerCase().trim();
    const pRaw = String(u.perfil || '').toLowerCase().trim();

    let chavePerfil = 'Encarregado / Mestre de Obras';
    if (pRaw === 'master' || ['henrique', 'camila', 'robson', 'admin'].includes(login)) {
      chavePerfil = 'Master';
    } else if (pRaw.includes('vendedor') || pRaw.includes('comercial') || login === 'vendedor' || login === 'leticia') {
      chavePerfil = 'Comercial / Vendedor';
    } else if (pRaw === 'rh' || login === 'jennifer' || login === 'leonardo') {
      chavePerfil = 'RH';
    } else if (pRaw.includes('engenheir') || pRaw.includes('engenharia') || pRaw.includes('estagi')) {
      chavePerfil = 'Engenharia';
    }

    const baseConfig = window.MAPA_NAVEGACAO_E_ATALHOS_POR_PERFIL[chavePerfil];
    const empresasAutorizadas =
      login === 'josehenrique'
        ? ['emp-2']
        : chavePerfil === 'Master'
        ? ['emp-1', 'emp-2', 'emp-3']
        : Array.isArray(u.empresas) && u.empresas.length > 0
        ? u.empresas
        : [u.empresaId || 'emp-1'];

    return {
      sucesso: true,
      usuario: login,
      perfilIdentificado: chavePerfil,
      empresasAutorizadas,
      telaInicial: { ...baseConfig.telaInicial },
      atalhosPrioritarios: baseConfig.atalhosPrioritarios.map((a) => ({ ...a })),
      modulosBloqueados: baseConfig.modulosBloqueados.slice()
    };
  };

  window.executarAtalhoRapidoPerfilComSeguranca = function (atalhoOuModulo, opcoes = {}, usuarioObj = window.currentLoggedUser) {
    if (!usuarioObj || !usuarioObj.usuario) {
      return {
        sucesso: false,
        acessoNegado: true,
        codigo: 'USUARIO_NAO_AUTENTICADO',
        erro: 'Autenticação obrigatória para acionar atalhos do sistema.'
      };
    }

    const cfg = window.obterConfiguracaoNavegacaoInicialPorPerfil(usuarioObj);
    const login = String(usuarioObj.usuario || '').toLowerCase().trim();

    // Verifica isolamento de empresa se o atalho especificar uma empresaAlvo
    if (opcoes.empresaId && !cfg.empresasAutorizadas.includes(opcoes.empresaId)) {
      return {
        sucesso: false,
        acessoNegado: true,
        codigo: 'ATALHO_BLOQUEADO_OUTRA_EMPRESA',
        erro: `Acesso bloqueado: Seu usuário (${login}) não possui permissão para acessar dados da empresa ${window.obterNomeRealEmpresa ? window.obterNomeRealEmpresa(opcoes.empresaId) : opcoes.empresaId}.`
      };
    }

    const moduloAlvo = String(
      typeof atalhoOuModulo === 'object' ? atalhoOuModulo.modulo : atalhoOuModulo
    )
      .toLowerCase()
      .trim();
    const subsecaoAlvo =
      typeof atalhoOuModulo === 'object' ? atalhoOuModulo.subsecao : opcoes.subsecao || null;

    // Verifica se o módulo está na lista bloqueada do perfil ou na verificação estrita de perfil
    if (cfg.modulosBloqueados.includes(moduloAlvo)) {
      return {
        sucesso: false,
        acessoNegado: true,
        codigo: 'ATALHO_MODULO_RESTRITO_PERFIL',
        erro: `Acesso negado: O perfil "${cfg.perfilIdentificado}" não possui autorização para acessar o módulo "${moduloAlvo}".`
      };
    }

    if (
      typeof window.verificarPermissaoModuloPorPerfil === 'function' &&
      cfg.perfilIdentificado !== 'Master'
    ) {
      const permitido = window.verificarPermissaoModuloPorPerfil(moduloAlvo, subsecaoAlvo, usuarioObj);
      if (!permitido && !(cfg.perfilIdentificado === 'Encarregado / Mestre de Obras' && ['colaboradores', 'novo', 'gestao'].includes(moduloAlvo))) {
        return {
          sucesso: false,
          acessoNegado: true,
          codigo: 'ATALHO_BLOQUEADO_RBAC',
          erro: `Permissão negada para "${moduloAlvo}".`
        };
      }
    }

    if (typeof window.navegarParaModuloErp === 'function') {
      try {
        window.navegarParaModuloErp(moduloAlvo, subsecaoAlvo);
      } catch (e) {}
    }

    return {
      sucesso: true,
      acessoNegado: false,
      perfil: cfg.perfilIdentificado,
      moduloNavegado: moduloAlvo,
      subsecaoNavegada: subsecaoAlvo
    };
  };

