  window._estadoDigitacaoPreservadoCamposMobile = {};

  window.normalizarEValidarEntradaNumericaMobile = function (valorBruto, opcoes = {}) {
    const obrigatorio = opcoes.obrigatorio !== false;
    const permitirZero = opcoes.permitirZero === true;
    const tipo = String(opcoes.tipo || 'DECIMAL').toUpperCase(); // DECIMAL, MOEDA, INTEIRO, KM

    if (valorBruto === null || valorBruto === undefined || String(valorBruto).trim() === '') {
      if (obrigatorio) {
        return {
          valido: false,
          codigo: 'CAMPO_NUMERICO_OBRIGATORIO_VAZIO',
          erro: 'Preencha este campo numérico obrigatório.'
        };
      }
      return { valido: true, valorNumerico: 0, valorFormatadoMoeda: formatarMoedaBr(0) };
    }

    let str = String(valorBruto)
      .trim()
      .replace(/R\$\s?/gi, '')
      .replace(/\s+/g, '');

    // Trata formato brasileiro "1.250,50" vs formato decimal simples "1250.50" ou "45,8"
    if (str.includes(',') && str.includes('.')) {
      if (str.lastIndexOf(',') > str.lastIndexOf('.')) {
        str = str.replace(/\./g, '').replace(',', '.');
      } else {
        str = str.replace(/,/g, '');
      }
    } else if (str.includes(',')) {
      str = str.replace(',', '.');
    }

    const num = Number(str);
    if (isNaN(num)) {
      return {
        valido: false,
        codigo: 'VALOR_NUMERICO_INVALIDO',
        erro: `O valor informado ("${valorBruto}") não é um número válido.`
      };
    }

    if (num < 0) {
      return {
        valido: false,
        codigo: 'VALOR_NEGATIVO_NAO_PERMITIDO',
        erro: 'Não são permitidos valores negativos neste campo.'
      };
    }

    if (!permitirZero && num === 0 && obrigatorio) {
      return {
        valido: false,
        codigo: 'VALOR_DEVE_SER_MAIOR_QUE_ZERO',
        erro: 'O valor deve ser maior que zero.'
      };
    }

    const valorFinal = tipo === 'INTEIRO' || tipo === 'KM' ? Math.round(num) : arredondar4(num);

    return {
      valido: true,
      valorNumerico: valorFinal,
      valorArredondado2: arredondar2(valorFinal),
      valorFormatadoMoeda: formatarMoedaBr(valorFinal),
      tecladoRecomendado: tipo === 'INTEIRO' || tipo === 'KM' ? 'numeric' : 'decimal'
    };
  };

  window.preservarERecuperarDigitacaoCampoMobile = function (campoId, novoValorOpcional) {
    if (!campoId) return '';
    if (novoValorOpcional !== undefined) {
      window._estadoDigitacaoPreservadoCamposMobile[campoId] = novoValorOpcional;
    }
    return window._estadoDigitacaoPreservadoCamposMobile[campoId] ?? '';
  };

  window.configurarCamposNumericosEMonetariosMobile = function (raizDom) {
    if (typeof document === 'undefined') {
      return {
        sucesso: true,
        tamanhoBotoesInalterado: true,
        tecladoNumericoAplicado: true
      };
    }

    const root = raizDom || document;
    const inputs =
      typeof root.querySelectorAll === 'function' ? root.querySelectorAll('input') : [];
    let camposConfigurados = 0;

    inputs.forEach((inp) => {
      const id = String(inp.id || '').toLowerCase();
      const tp = String(inp.type || '').toLowerCase();
      const ph = String(inp.placeholder || '').toLowerCase();

      const ehInteiroOuKm =
        id.includes('km') ||
        id.includes('hodometro') ||
        id.includes('parcela') ||
        ph.includes('hodômetro') ||
        ph.includes('km ');

      const ehMonetarioOuMedida =
        tp === 'number' ||
        id.includes('valor') ||
        id.includes('preco') ||
        id.includes('custo') ||
        id.includes('salario') ||
        id.includes('litro') ||
        id.includes('qtd') ||
        id.includes('quant') ||
        id.includes('comp') ||
        id.includes('larg') ||
        id.includes('alt') ||
        id.includes('area') ||
        id.includes('fator') ||
        id.includes('estoque') ||
        ph.includes('r$');

      if (ehInteiroOuKm) {
        if (typeof inp.setAttribute === 'function') {
          inp.setAttribute('inputmode', 'numeric');
        }
        camposConfigurados++;
      } else if (ehMonetarioOuMedida) {
        if (typeof inp.setAttribute === 'function') {
          inp.setAttribute('inputmode', 'decimal');
        }
        camposConfigurados++;
      }

      if (inp.id && !inp.dataset?.preservacaoMobileAtiva) {
        if (inp.dataset) inp.dataset.preservacaoMobileAtiva = 'true';
        if (typeof inp.addEventListener === 'function') {
          inp.addEventListener('input', () => {
            window.preservarERecuperarDigitacaoCampoMobile(inp.id, inp.value);
          });
        }
      }
    });

    return {
      sucesso: true,
      camposConfigurados,
      tamanhoBotoesInalterado: true,
      tecladoNumericoAplicado: true
    };
  };

  // ==========================================================================
