          <input type="text" id="telha-rap-cliente" value="${esc(est.clienteNome || 'Agropecuária Sul de Minas')}" oninput="window.orcamentoTelhasMultiItensAtivo.clienteNome=this.value" class="w-full border border-slate-300 rounded-lg p-2 bg-white font-bold">
        </div>
        <div>
          <label class="block font-bold text-slate-700 mb-1">Obra / Destino</label>
