  // ==========================================================================
  // 6. ITEM 6 — PERMISSÕES E CONFERENTES: SELETOR DE USUÁRIOS CADASTRADOS
  //    (SUBSTITUI DIGITAÇÃO MANUAL DE NOME POR SELETOR PESQUISÁVEL COM ID REAL)
  // ==========================================================================

  window.obterOpcoesSeletorUsuariosCadastrados = function (filtros = {}) {
    const termo = String(filtros.termo || '').toLowerCase().trim();
    const empresaFiltro = filtros.empresaId || 'todas';
    const despesaId = filtros.despesaId || null;
    const todos = obterListaUsuariosOficial();
    const compartilhamentosAtivos = (window.compartilhamentosDespesasUsuariosDb || []).filter(
      (c) => c.status === 'ATIVO' && (!despesaId || c.despesaId === despesaId)
    );
    const loginsComAcesso = new Set(
      compartilhamentosAtivos.map((c) => String(c.usuarioDestino).toLowerCase().trim())
    );

    const elegiveis = [];
    const bloqueadosInativosOuSemVinculo = [];

    todos.forEach((u) => {
      const login = String(u.usuario || '').toLowerCase().trim();
      const nome = String(u.nome || '').trim();
      if (termo && !nome.toLowerCase().includes(termo) && !login.includes(termo)) return;

      const inativo = u.status === 'Inativo' || u.ativo === false;
      const emps = Array.isArray(u.empresas) ? u.empresas : ['emp-1'];
      const semVinculoEmpresa = empresaFiltro !== 'todas' && !emps.includes(empresaFiltro) && !MASTERS_AUTENTICADOS_PERMITIDOS.includes(login);

      const item = {
        usuarioIdReal: u.id || `USR-${login.toUpperCase()}`,
        login,
        nome,
        perfil: u.perfil || 'Operacional',
        setor: u.setor || 'Geral',
        empresas: emps,
        status: inativo ? 'Inativo' : 'Ativo',
        jaPossuiAcesso: loginsComAcesso.has(login),
        elegivel: !inativo && !semVinculoEmpresa,
        motivoBloqueio: inativo
          ? 'Usuário Inativo'
          : semVinculoEmpresa
          ? `Sem vínculo permitido com a empresa ${empresaFiltro}`
          : null
      };

      if (item.elegivel) elegiveis.push(item);
      else bloqueadosInativosOuSemVinculo.push(item);
    });

    return {
      sucesso: true,
      seletorUsuariosCadastradosAtivo: true,
      semDigitacaoManualDeNome: true,
      utilizaIdentificadorRealBanco: true,
      elegiveis,
      bloqueadosInativosOuSemVinculo,
      usuariosQueJaPossuemAcesso: elegiveis.filter((e) => e.jaPossuiAcesso)
    };
  };

  window.selecionarUsuariosCadastradosECompartilhar = function (
    dados = {},
    usuarioExecutor = window.currentLoggedUser
  ) {
    const idsOuLogins = Array.isArray(dados.usuariosIdsOuLogins)
      ? dados.usuariosIdsOuLogins
      : dados.usuarioIdOuLogin
      ? [dados.usuarioIdOuLogin]
      : [];

    if (idsOuLogins.length === 0) {
      return {
        sucesso: false,
        codigo: 'NENHUM_USUARIO_SELECIONADO',
        erro: 'Selecione ao menos um usuário cadastrado no seletor.'
      };
    }

    const todos = obterListaUsuariosOficial();
    const validados = [];
    for (const ref of idsOuLogins) {
      const refNorm = String(ref || '').toLowerCase().trim();
      const u = todos.find(
        (x) =>
          String(x.id || '').toLowerCase().trim() === refNorm ||
          String(x.usuario || '').toLowerCase().trim() === refNorm
      );
      if (!u) {
        return {
          sucesso: false,
          codigo: 'USUARIO_NAO_ENCONTRADO_NO_BANCO',
          erro: `O identificador "${ref}" não corresponde a um usuário cadastrado no banco.`
        };
      }
      if (u.status === 'Inativo' || u.ativo === false) {
        return {
          sucesso: false,
          bloqueadoUsuarioInativo: true,
          codigo: 'BLOQUEIO_SELECAO_USUARIO_INATIVO',
          erro: `O usuário "${u.nome}" está INATIVO e não pode receber compartilhamento ou acesso.`
        };
      }
      if (dados.empresaId && dados.empresaId !== 'todas') {
        const emps = Array.isArray(u.empresas) ? u.empresas : ['emp-1'];
        if (!emps.includes(dados.empresaId) && !MASTERS_AUTENTICADOS_PERMITIDOS.includes(String(u.usuario).toLowerCase())) {
          return {
            sucesso: false,
            bloqueadoSemVinculoEmpresa: true,
            codigo: 'BLOQUEIO_USUARIO_SEM_VINCULO_EMPRESA',
            erro: `O usuário "${u.nome}" não possui vínculo permitido com a empresa "${dados.empresaId}".`
          };
        }
      }
      validados.push(u);
    }

    const despesaIds = Array.isArray(dados.despesaIds) && dados.despesaIds.length > 0
      ? dados.despesaIds
      : [(window.lancamentosFinanceirosDb || [])[0]?.id || 'FIN-2026-001'];

    const res = window.gerenciarCompartilhamentoDespesasERegistrosPorListaUsuarios(
      'CONCEDER',
      {
        despesaIds,
        usuariosSelecionados: validados.map((u) => u.usuario),
        nivelAcesso: dados.nivelAcesso || 'SOMENTE_VISUALIZACAO',
        empresaId: dados.empresaId
      },
      usuarioExecutor
    );

    return {
      ...res,
      usuariosValidadosBanco: validados.map((u) => ({
        usuarioIdReal: u.id,
        login: u.usuario,
        nome: u.nome
      }))
    };
  };

  // Substitui o campo manual #inp-share-lote-user em #fin-tab-panel-permissoes por um seletor pesquisável de usuários cadastrados
  window.injetarSeletorUsuariosNoPainelPermissoesDom = function () {
    if (typeof document === 'undefined') return { sucesso: true };
    const painelPerm = document.getElementById('fin-tab-panel-permissoes');
    if (!painelPerm) return { sucesso: false };

    const opcoes = window.obterOpcoesSeletorUsuariosCadastrados({});
    const painelLote = document.getElementById('painel-c-compartilhamento-lote');
    if (painelLote) {
      painelLote.innerHTML = `
        <div class="space-y-3 text-xs">
          <div class="flex flex-wrap items-center justify-between gap-2">
            <div>
              <span class="text-[10px] font-black uppercase text-amber-400">Seletor Oficial de Usuários Cadastrados</span>
              <h4 class="font-black text-sm text-white">🤝 Compartilhamento e Delegação para Usuários Cadastrados</h4>
              <p class="text-[11px] text-slate-300">Pesquise e selecione um ou mais usuários ativos cadastrados no banco (usuários inativos são bloqueados automaticamente).</p>
            </div>
          </div>

          <div class="grid grid-cols-1 sm:grid-cols-3 gap-2 text-slate-900">
            <div>
              <label class="block text-[10px] font-bold text-slate-300 mb-1">Pesquisar Usuário pelo Nome</label>
              <input type="search" id="busca-seletor-usuario-permissoes" placeholder="Filtrar por nome ou login..." oninput="window.filtrarOpcoesSeletorUsuariosPermissoesDom(this.value)" class="w-full px-2.5 py-1.5 rounded-lg text-xs font-bold bg-white">
            </div>
            <div>
              <label class="block text-[10px] font-bold text-slate-300 mb-1">Selecionar Usuário Cadastrado (ID Real) *</label>
              <select id="inp-share-lote-user" multiple size="3" class="w-full px-2.5 py-1.5 rounded-lg text-xs font-bold bg-white">
                ${opcoes.elegiveis.map((u, i) => `<option value="${esc(u.login)}" data-user-id="${esc(u.usuarioIdReal)}" ${i === 0 ? 'selected' : ''}>${esc(u.nome)} (@${esc(u.login)} · ${esc(u.perfil)})${u.jaPossuiAcesso ? ' [✓ Já possui acesso]' : ''}</option>`).join('')}
              </select>
            </div>
            <div class="flex flex-col justify-between gap-2">
              <div>
                <label class="block text-[10px] font-bold text-slate-300 mb-1">Nível de Permissão</label>
                <select id="sel-share-lote-nivel" class="w-full px-2.5 py-1.5 rounded-lg text-xs font-bold bg-white">
                  <option value="SOMENTE_VISUALIZACAO">Somente Visualização e Conferência</option>
                  <option value="PERMISSAO_EDICAO">Permissão de Edição</option>
                </select>
              </div>
              <button type="button" id="btn-aplicar-compartilhamento-lote" onclick="const sel=document.getElementById('inp-share-lote-user'); const escolhidos=sel?Array.from(sel.selectedOptions).map(o=>o.value):[]; const n=document.getElementById('sel-share-lote-nivel')?.value||'SOMENTE_VISUALIZACAO'; window.selecionarUsuariosCadastradosECompartilhar({usuariosIdsOuLogins:escolhidos,nivelAcesso:n}); window.injetarSeletorUsuariosNoPainelPermissoesDom();" class="w-full px-3 py-2 rounded-xl bg-amber-500 hover:bg-amber-400 text-slate-950 font-black text-xs cursor-pointer">
                ✓ Conceder Acesso aos Selecionados
              </button>
            </div>
          </div>

          <div class="bg-slate-800/90 p-3 rounded-xl border border-slate-700 space-y-1.5">
            <div class="text-[10px] font-black uppercase text-emerald-400">Usuários que Já Possuem Acesso Compartilhado (${opcoes.usuariosQueJaPossuemAcesso.length})</div>
            ${opcoes.usuariosQueJaPossuemAcesso.length === 0 ? `<div class="text-[11px] text-slate-400">Nenhum compartilhamento ativo no momento.</div>` : `
              <div class="flex flex-wrap gap-2">
                ${opcoes.usuariosQueJaPossuemAcesso.map((u) => `
                  <span class="inline-flex items-center gap-2 px-2.5 py-1 rounded-lg bg-slate-900 border border-emerald-500/40 text-xs">
                    <span class="font-bold text-white">${esc(u.nome)} (@${esc(u.login)})</span>
                    <button type="button" onclick="window.gerenciarCompartilhamentoDespesasERegistrosPorListaUsuarios('REVOGAR',{usuariosSelecionados:['${esc(u.login)}']}); window.injetarSeletorUsuariosNoPainelPermissoesDom();" class="px-1.5 py-0.5 rounded bg-rose-600 hover:bg-rose-700 text-white font-black text-[10px]">✕ Revogar</button>
                  </span>
                `).join('')}
              </div>
            `}
          </div>
        </div>
      `;
    }

    return { sucesso: true, seletorInjetado: true };
  };

  window.filtrarOpcoesSeletorUsuariosPermissoesDom = function (termo = '') {
    if (typeof document === 'undefined') return;
    const sel = document.getElementById('inp-share-lote-user');
    if (!sel) return;
    const opcoes = window.obterOpcoesSeletorUsuariosCadastrados({ termo });
    sel.innerHTML = opcoes.elegiveis
      .map(
        (u, i) =>
          `<option value="${esc(u.login)}" data-user-id="${esc(u.usuarioIdReal)}" ${i === 0 ? 'selected' : ''}>${esc(u.nome)} (@${esc(u.login)} · ${esc(u.perfil)})${u.jaPossuiAcesso ? ' [✓ Já possui acesso]' : ''}</option>`
      )
      .join('');
  };

