  window.padronizarTodosModaisSistemaErp = function () {
    if (typeof document === 'undefined') return { sucesso: true };
    const todosModais = document.querySelectorAll('[id^="modal-"]');
    let modaisPadronizadosCount = 0;

    todosModais.forEach((modal) => {
      if (!modal || modal.id === 'modal-obra-titulo' || modal.id === 'modal-empresa-titulo' || modal.id.startsWith('modal-titulo')) return;
      const cardInterno = modal.querySelector('.bg-white');
      if (cardInterno) {
        if (!cardInterno.classList.contains('max-h-[90vh]') && !cardInterno.classList.contains('max-h-[92vh]')) {
          cardInterno.classList.add('max-h-[90vh]', 'overflow-y-auto', 'custom-scroll');
        }
        const header = cardInterno.querySelector('.border-b');
        if (header && !header.querySelector('button')) {
          const btnX = document.createElement('button');
          btnX.type = 'button';
          btnX.className = 'bg-slate-100 hover:bg-rose-100 text-slate-700 font-black text-xs px-2.5 py-1 rounded-xl';
          btnX.textContent = '✕';
          btnX.onclick = () => window.fecharModalUniversalComSeguranca(modal.id);
          header.appendChild(btnX);
        }
      }

      if (!modal.dataset.backdropPadronizadoV162) {
        modal.dataset.backdropPadronizadoV162 = '1';
        modal.addEventListener('click', (ev) => {
          if (ev.target === modal) window.fecharModalUniversalComSeguranca(modal.id, { viaBackdrop: true });
        });
      }
      modaisPadronizadosCount++;
    });

    if (!window._listenerEscUniversalModaisV162) {
      window._listenerEscUniversalModaisV162 = true;
      document.addEventListener('keydown', (ev) => {
        if (ev.key === 'Escape') {
          const abertos = Array.from(document.querySelectorAll('[id^="modal-"]:not(.hidden)')).filter((el) => el.classList.contains('fixed'));
          if (abertos.length > 0) {
            const topo = abertos[abertos.length - 1];
            window.fecharModalUniversalComSeguranca(topo.id, { viaEsc: true });
          }
        }
      });
    }

    return { sucesso: true, modaisPadronizadosCount };
  };

  window.fecharModalUniversalComSeguranca = function (modalId, opcoes = {}) {
    if (typeof document === 'undefined') return { sucesso: true, modalId, fechado: true };
    const modal = document.getElementById(modalId);
    if (!modal) return { sucesso: false, erro: 'Modal não encontrado.' };

    if (modal.dataset.alteracoesNaoSalvas === 'true' && opcoes.confirmarDescarte !== true) {
      return {
        sucesso: false,
        requerConfirmacaoDescarte: true,
        codigo: 'CONFIRMAR_DESCARTE_ALTERACOES_NAO_SALVAS',
        erro: 'Existem alterações não salvas neste formulário. Confirme antes de descartar.'
      };
    }

    modal.dataset.alteracoesNaoSalvas = 'false';
    modal.classList.add('hidden');
    return { sucesso: true, modalId, fechado: true };
  };

