          etapaNome: 'Superestrutura, Alvenaria e Cobertura Metálica',
          codigo: '02.01.01',
          fonte: 'SINAPI',
          descricao: 'Alvenaria de vedação de blocos cerâmicos furados 14x19x19 cm e estrutura metálica de telhado',
          unidade: 'm²',
          quantidade: 920,
          precoUnitario: 902.4456,
