  const _origCorrigirNavAbas = window.corrigirNavegacaoHorizontalAbasGestaoObras;
  window.corrigirNavegacaoHorizontalAbasGestaoObras = function () {
    const res = typeof _origCorrigirNavAbas === "function" ? _origCorrigirNavAbas() : { sucesso: true };
    if (typeof document !== "undefined") {
      const barEl = document.getElementById("barra-abas-gestao-obras-scroll");
      let anc = barEl;
      while (anc && anc !== document.body) {
        const hasHidden = typeof anc.classList?.contains === "function" && anc.classList.contains("hidden");
        const isDispNone = typeof getComputedStyle === "function" && getComputedStyle(anc)?.display === "none";
        if (anc.id === "view-gestao" || hasHidden || isDispNone) {
          if (typeof anc.classList?.remove === "function") anc.classList.remove("hidden");
          if (isDispNone && anc.style) anc.style.display = "block";
        }
        anc = anc.parentElement;
      }
      ["card-abas-gestao-obras", "header-abas-gestao-obras-wrapper", "controles-scroll-abas-gestao-wrapper"].forEach((id) => {
        const el = document.getElementById(id);
        if (el && el.style) {
          el.style.minWidth = "0";
          el.style.maxWidth = "100%";
          el.style.boxSizing = "border-box";
        }
      });
      const ctrlWrap = document.getElementById("controles-scroll-abas-gestao-wrapper");
      if (ctrlWrap && ctrlWrap.style) {
        ctrlWrap.style.display = "flex";
        ctrlWrap.style.alignItems = "center";
        ctrlWrap.style.width = "100%";
        ctrlWrap.style.overflow = "hidden";
      }
      const bar = document.getElementById("barra-abas-gestao-obras-scroll");
      if (bar && bar.style) {
        bar.style.display = "flex";
        bar.style.flexDirection = "row";
        bar.style.flexWrap = "nowrap";
        bar.style.overflowX = "auto";
        bar.style.overflowY = "hidden";
        bar.style.minWidth = "0";
        bar.style.flex = "1 1 0%";
        bar.style.width = "100%";
        const vw = (typeof window !== "undefined" && window.innerWidth) ? window.innerWidth : 360; bar.style.maxWidth = (vw < 1024 ? Math.max(200, vw - 110) + "px" : "calc(100vw - 140px)");
        bar.style.scrollBehavior = "auto";
        (bar.querySelectorAll ? bar.querySelectorAll("button, .subtab-btn") : []).forEach((btn) => { if (!btn.style) btn.style = {};
          btn.style.flexShrink = "0";
          btn.style.whiteSpace = "nowrap";
          btn.style.minWidth = "190px";
        });
      }
    }
    return res;
  };

