          obraNome: obraAlvo,
          ordem: idx + 1,
          nome: et.nome,
          descricao: 'Etapa integrada entre Boletim de Medição e Cronograma Físico-Financeiro',
          servicosVinculados: [et.nome],
          dataInicioPrevista: d.inicio || d.dataInicio || '2026-02-01',
          dataConclusaoPrevista: d.termino || d.dataFim || '2026-11-30',
          dataInicioReal: et.pAcumulado > 0 ? (d.inicio || d.dataInicio || '2026-02-05') : '',
          dataConclusaoReal: et.pAcumulado >= 100 ? new Date().toISOString().slice(0, 10) : '',
          unidade: et.unidade,
          quantidadePrevista: et.qtdPrevista,
          quantidadeExecutada: et.qtdAcumulada,
