              onchange="window.ajustarMedicaoItemPorcentagemOuQuantidade('${obraEsc}', ${idx}, 'PERCENTUAL', this.value)"
              class="w-18 text-center font-mono font-black ${desabilitarPct ? 'bg-slate-100 text-slate-400 border-slate-200' : 'text-amber-950 bg-white border-2 border-amber-400 focus:border-amber-600'} rounded-lg p-1 text-xs focus:outline-none">
            <span class="text-[10px] font-bold text-amber-900">%</span>
