        modal = document.createElement('div');
        modal.id = 'modal-preview-boletim-medicao-v168';
        modal.className = 'fixed inset-0 bg-slate-950/80 z-50 flex items-center justify-center p-3 sm:p-6 no-print';
        document.body.appendChild(modal);
