            <div class="flex justify-end gap-2 pt-2 border-t border-slate-200">
              <button type="button" onclick="window.fecharModalSeguro('modal-permissoes-crea-usuario')" class="px-4 py-2 rounded-xl bg-slate-100 font-bold text-slate-700 cursor-pointer">Cancelar</button>
              <button type="button" id="btn-salvar-permissoes-v168" onclick="window.salvarPermissoesGranularesDoModalV168('${u.id}')" class="px-5 py-2 rounded-xl bg-purple-600 hover:bg-purple-700 text-white font-black cursor-pointer">✓ Salvar Permissões no Servidor</button>
            </div>
