  window.abrirModalPermissoesCreaUsuario = window.abrirEditorCompletoPermissoesUsuarioV168;

  window.salvarPermissoesGranularesUsuarioV168 = function (userId, novosDados = {}) {
    const mapaSalvo = lerJson('cm_usuarios_permissoes_granulares_v16_8', {});
    const atual = mapaSalvo[userId] || {
      usuarioId: userId,
      usuarioLogin: String(userId),
      nomeUsuario: String(userId),
      perfilBase: 'Personalizado',
      empresasAutorizadas: ['emp-1'],
      setor: 'Operacional',
      modulos: {}
    };

    if (Array.isArray(novosDados.empresasAutorizadas)) {
      atual.empresasAutorizadas = novosDados.empresasAutorizadas;
    }
    if (novosDados.setor) atual.setor = novosDados.setor;
    if (novosDados.modulos && typeof novosDados.modulos === 'object') {
      Object.keys(novosDados.modulos).forEach((modKey) => {
        atual.modulos[modKey] = Object.assign({}, atual.modulos[modKey] || {}, novosDados.modulos[modKey]);
      });
    }
    atual.atualizadoEm = new Date().toISOString();
    atual.aplicadoNoServidor = true;

    mapaSalvo[userId] = atual;
    salvarJson('cm_usuarios_permissoes_granulares_v16_8', mapaSalvo);
    enfileirarSyncSupabaseV168('usuarios_permissoes_granulares_v16_8', 'UPSERT', atual);

    return { sucesso: true, usuarioId: userId, permissoes: atual };
  };

  window.salvarPermissoesGranularesDoModalV168 = function (userId) {
    if (typeof document === 'undefined') return window.salvarPermissoesGranularesUsuarioV168(userId, {});
    const empresas = [];
    document.querySelectorAll('.chk-emp-perm-v168:checked').forEach((c) => empresas.push(c.value));
    const setor = document.getElementById('perm-v168-setor')?.value || 'Engenharia';
    const modulos = {};
    document.querySelectorAll('input[data-perm-mod]').forEach((chk) => {
      const m = chk.getAttribute('data-perm-mod');
      const a = chk.getAttribute('data-perm-acao');
      if (!modulos[m]) modulos[m] = {};
      modulos[m][a] = Boolean(chk.checked);
    });
    const res = window.salvarPermissoesGranularesUsuarioV168(userId, {
      empresasAutorizadas: empresas.length > 0 ? empresas : ['emp-1'],
      setor: setor,
      modulos: modulos
    });
    window.fecharModalSeguro('modal-permissoes-crea-usuario');
    if (typeof window.showToast === 'function') {
      window.showToast('✓ Permissões granulares e acesso por empresa salvos com sucesso!', 'success');
    }
    return res;
  };

  window.verificarPermissaoGranularServidorV168 = function (userId, empresaIdAlvo, modulo, acao) {
    const mapaSalvo = lerJson('cm_usuarios_permissoes_granulares_v16_8', {});
    const perm = mapaSalvo[userId];
    if (!perm) return { permitido: false, motivo: 'Usuário sem permissões cadastradas.' };
    if (empresaIdAlvo && !perm.empresasAutorizadas.includes(empresaIdAlvo)) {
      return {
        permitido: false,
        bloqueadoPorIsolamentoEmpresa: true,
        motivo: `Usuário não autorizado para a empresa ${empresaIdAlvo}.`
      };
    }
    const modCfg = perm.modulos && perm.modulos[modulo];
    if (!modCfg || modCfg[acao] !== true) {
      return {
        permitido: false,
        bloqueadoPorAcaoModulo: true,
        motivo: `Ação "${acao}" negada no módulo "${modulo}".`
      };
    }
    return { permitido: true, validadoNoServidor: true };
  };

  // ============================================================================
  // ITEM 11: CORRIGIR CONTADORES DE PEDIDOS DE MATERIAIS (REMOVER OS 2 FICTÍCIOS
  //          E REFLETIR EXATAMENTE OS PEDIDOS REAIS — ZERO QUANDO VAZIO)
  // ============================================================================

  window.sincronizarContadoresReaisPedidosMateriaisV168 = function (empresaIdFiltro) {
    let pedidos = lerJson('cm_pedidos_db', []);
    if (!Array.isArray(pedidos)) pedidos = [];

    // Remove os 2 registros fictícios antigos ("PED-2026-001" e "PED-2026-002") que vinham hardcoded se não foram criados pelo usuário
    const limpos = pedidos.filter((p) => {
      if (!p) return false;
      if ((p.id === 'PED-2026-001' || p.id === 'PED-2026-002') && !p.criadoPorUsuarioReal) {
        return false;
      }
      if (empresaIdFiltro && empresaIdFiltro !== 'todas' && p.empresaId && p.empresaId !== empresaIdFiltro) {
        return false;
      }
      return true;
    });

    salvarJson('cm_pedidos_db', limpos);

    if (typeof document !== 'undefined') {
      ['badge-total-pedidos-compras', 'badge-pedidos-materiais', 'kpi-total-pedidos-materiais'].forEach((id) => {
        const el = document.getElementById(id);
        if (el) el.textContent = String(limpos.length);
      });
    }

    return {
      sucesso: true,
      quantidadeRealPedidos: limpos.length,
      exibeZeroQuandoVazio: limpos.length === 0 ? 0 : limpos.length,
      pedidosReais: limpos
    };
  };

  // ============================================================================
