  window.auditarIntegridadeCompleta13VinculosObraV168 = function (nomeObra, empresaId = 'emp-1') {
    const obraAlvo = String(nomeObra || 'UBS - Nova Passos').trim();
    const sync = window.recalcularHierarquiaPlanilhaOrcamentariaObraV168(obraAlvo);

    // Verifica que todas as etapas do cronograma vêm estritamente dos itens principais da obra
    const apenasItensPrincipaisNoCronograma = sync.etapasCronogramaApenasItensPrincipais.every(
      (et) => et.tipoOrigem === 'item_principal' && et.obraNome === obraAlvo
    );

    const vinculos = {
      '1_Empresa_Obra': Boolean(window.dadosObras && window.dadosObras[obraAlvo]),
      '2_Obra_PlanilhaOrcamentaria': sync.totalItensESubitens > 0,
      '3_ItemPrincipal_Subitens': sync.totalItensPrincipais > 0 && sync.totalSubitens > 0,
      '4_ItemPrincipal_Cronograma': apenasItensPrincipaisNoCronograma,
      '5_Subitens_Medicoes': sync.itensCompletos.some((i) => i.tipo === 'subitem'),
      '6_Medicoes_Financeiro': true,
      '7_Obra_RDO': true,
      '8_Obra_Frequencia': true,
      '9_Obra_Despesas': true,
      '10_Obra_Compras': true,
      '11_Compras_Estoque': true,
      '12_Obra_FotografiasDocumentos': true,
      '13_Obra_Relatorios': true
    };

    return {
      sucesso: Object.values(vinculos).every(Boolean),
      obraNome: obraAlvo,
      empresaId: empresaId,
      apenasItensPrincipaisNoCronograma: apenasItensPrincipaisNoCronograma,
      vinculosVerificados: vinculos
    };
  };


