  // ============================================================================
  window.garantirQuadroFuncionariosNuncaVazioV168 = function () {
    let colabs = typeof window.getColaboradoresDb === 'function' ? window.getColaboradoresDb() : lerJson('cm_colaboradores_db', []);
    if (!Array.isArray(colabs) || colabs.length === 0) {
      if (Array.isArray(window.initialColaboradores) && window.initialColaboradores.length > 0) {
        colabs = JSON.parse(JSON.stringify(window.initialColaboradores));
      } else {
        colabs = lerJson('cm_colaboradores_backup_54', []);
      }
      salvarJson('cm_colaboradores_db', colabs);
      window.colaboradoresDb = colabs;
      window.funcionariosDb = colabs;
    }

    if (typeof document !== 'undefined') {
      const selObraColab = document.getElementById('filtro-obra-colab');
      if (selObraColab) {
        if (selObraColab.options && !Array.from(selObraColab.options).some(o => o.value === 'todas')) {
          const optTodas = document.createElement('option');
          optTodas.value = 'todas';
          optTodas.textContent = 'Todas as Obras Alocadas';
          selObraColab.insertBefore(optTodas, selObraColab.firstChild);
        }
        // Se a obra selecionada for restritiva e zerar a tabela, reseta para 'todas'
        if (selObraColab.value !== 'todas') {
          const countComEstaObra = colabs.filter(c => c.obra === selObraColab.value).length;
          if (countComEstaObra === 0) {
            selObraColab.value = 'todas';
          }
        }
      }
      const selVinc = document.getElementById('filtro-vinculo-colab');
      if (selVinc && selVinc.value !== 'todos') {
        const countComVinc = colabs.filter(c => String(c.vinculo || '').includes(selVinc.value)).length;
        if (countComVinc === 0) selVinc.value = 'todos';
      }
      const inpBusca = document.getElementById('filtro-busca-colab');
      if (inpBusca && inpBusca.value) {
        const q = inpBusca.value.toLowerCase();
        const countBusca = colabs.filter(c => String(c.nome || '').toLowerCase().includes(q)).length;
        if (countBusca === 0) inpBusca.value = '';
      }
    }
    return colabs;
  };

