  // Bloqueia a simulação fictícia de NF-e para impedir que notas falsas entrem no estoque ou financeiro
  window.simularImportacaoNotaRecebida = function () {
    if (typeof window.showToast === 'function') {
      window.showToast('Importação de notas demonstrativas desativada em produção. Selecione um arquivo XML real.', 'warning');
    }
    return {
      sucesso: false,
      bloqueadoNotaDemonstrativa: true,
      motivo: 'Notas fiscais fictícias/demonstrativas foram removidas e bloqueadas.'
    };
  };

  window.importarXmlNfeRealV169 = function (xmlContent, opcoes = {}) {
    const strXml = String(xmlContent || '').trim();
    if (!strXml || (!strXml.includes('<NFe') && !strXml.includes('<nfeProc') && !strXml.includes('<det'))) {
      return { sucesso: false, erro: 'Arquivo XML inválido: estrutura <NFe>/<det> não localizada.' };
    }

    const extrairTag = (bloco, tag) => {
      const m = bloco.match(new RegExp(`<${tag}[^>]*>([\\s\\S]*?)<\\/${tag}>`, 'i'));
      return m ? m[1].trim() : '';
    };

    const nNF = extrairTag(strXml, 'nNF') || ('NF-' + Date.now());
    const emitBloco = extrairTag(strXml, 'emit') || strXml;
    const cnpjEmit = extrairTag(emitBloco, 'CNPJ') || '00.000.000/0001-00';
    const nomeEmit = extrairTag(emitBloco, 'xNome') || 'Fornecedor XML Real';
    const chaveMatch = strXml.match(/NFe(\d{44})/) || strXml.match(/<chNFe>(\d{44})<\/chNFe>/);
    const chaveAcesso = chaveMatch ? chaveMatch[1] : ('312611' + String(Date.now()).padStart(38, '0')).slice(0, 44);

    // Extrai todos os blocos <det>
    const detRegex = /<det[^>]*>([\s\S]*?)<\/det>/gi;
    const itensExtraidos = [];
    let mDet;
    while ((mDet = detRegex.exec(strXml)) !== null) {
      const prodBloco = extrairTag(mDet[1], 'prod') || mDet[1];
      const codigo = extrairTag(prodBloco, 'cProd') || ('XML-' + (itensExtraidos.length + 1));
      const nome = extrairTag(prodBloco, 'xProd') || 'Produto NF-e';
      const unid = extrairTag(prodBloco, 'uCom') || 'UN';
      const qtd = Number(extrairTag(prodBloco, 'qCom') || 1);
      const vUnit = Number(extrairTag(prodBloco, 'vUnCom') || 0);
      const vTot = Number(extrairTag(prodBloco, 'vProd') || arred2(qtd * vUnit));

      itensExtraidos.push({
        codigo: codigo,
        nome: nome,
        unidade: unid,
        qtd: arred2(qtd),
        valorUnitario: arred2(vUnit),
        total: arred2(vTot)
      });
    }

    if (itensExtraidos.length === 0) {
      return { sucesso: false, erro: 'Nenhum item <det><prod> encontrado no XML.' };
    }

    const depDestino = opcoes.depositoId || window.depositoSelecionadoEstoqueV169 || 'DEP-CENTRAL';
    const empId = opcoes.empresaId || 'emp-1';

    if (opcoes.confirmarEntradaEstoque !== false) {
      itensExtraidos.forEach((it, idx) => {
        window.registrarMovimentacaoDepositoIntegradaV169({
          chaveIdempotencia: `XML-${chaveAcesso}-ITEM-${idx + 1}`,
          depositoId: depDestino,
          empresaId: empId,
          tipo: 'ENTRADA',
          codigo: it.codigo,
          produto: it.nome,
          unidade: it.unidade,
          quantidade: it.qtd,
          custoUnitario: it.valorUnitario,
          origem: `NF-e Real #${nNF} (${nomeEmit})`
        });
      });
    }

    if (typeof document !== 'undefined') {
      const container = document.getElementById('lista-itens-extraidos-nfe');
      if (container) {
        container.innerHTML = itensExtraidos.map((it) => `
          <div class="p-2 bg-slate-50 border border-slate-200 rounded-lg flex items-center justify-between text-xs font-mono">
            <div>
              <strong class="text-slate-900 block font-sans">${esc(it.nome)}</strong>
              <span class="text-slate-500 text-[10px]">${esc(it.codigo)} · ${it.qtd} ${esc(it.unidade)} @ ${moedaBr(it.valorUnitario)}</span>
            </div>
            <strong class="text-emerald-800">${moedaBr(it.total)}</strong>
          </div>
        `).join('');
      }
      const prev = document.getElementById('resultado-preview-nfe');
      if (prev && prev.classList) prev.classList.remove('hidden');
    }

    return {
      sucesso: true,
      notaDemonstraFicticia: false,
      numeroNfe: nNF,
      chaveAcesso: chaveAcesso,
      emitente: nomeEmit,
      cnpjEmitente: cnpjEmit,
      depositoDestinoId: depDestino,
      totalItens: itensExtraidos.length,
      valorTotalNota: arred2(itensExtraidos.reduce((acc, i) => acc + i.total, 0)),
      itens: itensExtraidos
    };
  };

  window.processarImportacaoNfe = function (e) {
    const file = e && e.target && e.target.files && e.target.files[0];
    if (!file) return;
    if (typeof FileReader !== 'undefined') {
      const reader = new FileReader();
      reader.onload = function (ev) {
        window.importarXmlNfeRealV169(ev.target.result, { confirmarEntradaEstoque: true });
      };
      reader.readAsText(file);
    }
  };

