  window.sincronizarObrasModalFiscalV169 = function () {
    const obrasMap = window.dadosObras || {};
    const nomesObras = Object.keys(obrasMap).length > 0
      ? Object.keys(obrasMap)
      : [
          'UBS - Nova Passos',
          'UBS - Guaxupé',
          'SAAE - PÁTIO DE MANUTENÇÃO',
          'Cemei - Novo Horizonte',
          'UEMG - Bloco 4',
          'UEMG - Bloco 1',
          'CRAS - Alpinópolis'
        ];

    if (typeof document !== 'undefined') {
      const container = document.getElementById('container-obras-fiscal');
      if (container) {
        const marcados = new Set(
          Array.from(container.querySelectorAll ? container.querySelectorAll('input.ck-obra-fiscal:checked') : []).map((c) => c.value)
        );
        container.innerHTML = nomesObras.map((nome, idx) => {
          const checked = marcados.size > 0 ? marcados.has(nome) : idx === 0;
          return `
            <label class="flex items-center space-x-2 text-xs font-semibold text-slate-800 cursor-pointer p-1 rounded hover:bg-slate-100">
              <input type="checkbox" value="${esc(nome)}" ${checked ? 'checked' : ''} class="ck-obra-fiscal rounded text-emerald-600">
              <span>${esc(nome)}</span>
            </label>
          `;
        }).join('');
      }
    }

    return {
      sucesso: true,
      totalObrasDisponiveisFiscal: nomesObras.length,
      obras: nomesObras
    };
  };

  window.cadastrarFiscalComObrasVinculadasV169 = function (dadosFiscal = {}) {
    window.sincronizarObrasModalFiscalV169();
    const nome = String(dadosFiscal.nome || 'Eng. Fiscal Municipal').trim();
    const usuario = String(dadosFiscal.usuario || ('fiscal.' + Date.now())).trim();
    const orgao = String(dadosFiscal.orgao || 'Prefeitura Municipal').trim();
    const obrasLiberadas = Array.isArray(dadosFiscal.obrasLiberadas) && dadosFiscal.obrasLiberadas.length > 0
      ? dadosFiscal.obrasLiberadas
      : ['UBS - Nova Passos'];

    const users = typeof window.getUsuariosDb === 'function' ? window.getUsuariosDb() : lerJson('cm_usuarios_db', []);
    const idxExist = users.findIndex((u) => String(u.usuario) === usuario);
    const novoFiscal = {
      id: idxExist >= 0 ? users[idxExist].id : ('USR-FISC-' + Date.now()),
      usuario: usuario,
      nome: nome,
      email: `${usuario}@fiscalizacao.gov.br`,
      funcao: `Fiscal (${orgao})`,
      perfil: 'Fiscal',
      setor: 'Fiscalização Externa',
      empresasAutorizadas: [dadosFiscal.empresaId || 'emp-1'],
      obras: obrasLiberadas.join(', '),
      obrasLiberadas: obrasLiberadas,
      primeiroAcesso: true,
      status: 'Ativo'
    };

    if (idxExist >= 0) {
      // Preserva permissões já concedidas anteriormente e mescla obras
      const obrasAnt = Array.isArray(users[idxExist].obrasLiberadas) ? users[idxExist].obrasLiberadas : [];
      novoFiscal.obrasLiberadas = Array.from(new Set([...obrasAnt, ...obrasLiberadas]));
      novoFiscal.obras = novoFiscal.obrasLiberadas.join(', ');
      users[idxExist] = Object.assign({}, users[idxExist], novoFiscal);
    } else {
      users.push(novoFiscal);
    }

    salvarJson('cm_usuarios_db', users);
    if (typeof window.saveUsuariosDb === 'function') {
      try { window.saveUsuariosDb(users); } catch (e) {}
    }
    return {
      sucesso: true,
      fiscal: novoFiscal,
      obrasVinculadas: novoFiscal.obrasLiberadas
    };
  };

