  // 1.6 Formatação e Conversão Monetária Brasileira no campo #mo-valor
  window.converterValorMonetarioObraBrV170 = function (valorBruto) {
    const num = parseMoedaOuNumeroBr(valorBruto, 0);
    return {
      sucesso: num >= 0,
      valorNumerico: arred2(num),
      valorFormatadoBr: moedaBr(num)
    };
  };

  window.vincularCampoMoValorMonetarioBrV170 = function () {
    if (typeof document === 'undefined') return;
    const inpMoValor = document.getElementById('mo-valor');
    if (inpMoValor) {
      inpMoValor.setAttribute('type', 'text');
      inpMoValor.setAttribute('inputmode', 'decimal');
      if (!inpMoValor.dataset.boundMoValorV170) {
        inpMoValor.dataset.boundMoValorV170 = 'true';
        inpMoValor.addEventListener('blur', function () {
          const n = parseMoedaOuNumeroBr(this.value, 0);
          if (n > 0) {
            this.value = n.toLocaleString('pt-BR', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
          }
        });
      }
    }

    const formGestaoObra = document.getElementById('form-gestao-obra');
    if (formGestaoObra && !formGestaoObra.dataset.boundSubmitMoValorV170) {
      formGestaoObra.dataset.boundSubmitMoValorV170 = 'true';
      formGestaoObra.addEventListener('submit', function () {
        if (inpMoValor) {
          const n = parseMoedaOuNumeroBr(inpMoValor.value, 0);
          inpMoValor.dataset.rawFormattedValue = inpMoValor.value;
          inpMoValor.value = String(n);
        }
      }, true);
    }
  };

  // 1.7 Garantir Identificadores Únicos no RDO e Persistência de Terceirizados e Equipamentos
  window.garantirIdsUnicosCamposRdoEPersistenciaV170 = function () {
    if (typeof document === 'undefined') return { sucesso: true, camposSemIdRestantes: 0 };
    const formRdo = document.getElementById('form-rdo');
    if (!formRdo) return { sucesso: true, camposSemIdRestantes: 0 };

    let atribuidos = 0;
    const elementos = Array.from(formRdo.querySelectorAll('input, select, textarea'));
    elementos.forEach((el, idx) => {
      if (!el.id || !el.id.trim()) {
        const field = el.getAttribute('data-field') || el.getAttribute('name') || el.tagName.toLowerCase();
        const rowIdx = el.getAttribute('data-index') !== null ? el.getAttribute('data-index') : idx;
        el.id = `rdo-campo-${field}-${rowIdx}`;
        atribuidos++;
      }
    });

    const restantesSemId = Array.from(formRdo.querySelectorAll('input:not([type="hidden"]), select, textarea')).filter((el) => !el.id).length;
    return {
      sucesso: restantesSemId === 0,
      idsAtribuidosAgora: atribuidos,
      camposSemIdRestantes: restantesSemId
    };
  };

  window.salvarRdoComTerceirizadosEEquipamentosV170 = function (dadosRdo = {}) {
    const rdos = typeof window.getDb === 'function' ? window.getDb() : lerJson('cm_rdos_db', []);
    const id = dadosRdo.id || ('RDO-' + Date.now());
    const obra = String(dadosRdo.obra || 'UBS - Nova Passos').trim();
    const data = dadosRdo.data || new Date().toISOString().split('T')[0];

    const trabalhadores = Array.isArray(dadosRdo.trabalhadores) ? dadosRdo.trabalhadores.map((t, i) => ({
      idCampo: `rdo-trab-${i}`,
      nome: t.nome || 'Operário',
      funcao: t.funcao || 'Oficial',
      vinculo: t.vinculo || 'Próprio (CLT)',
      horas: Number(t.horas || 8)
    })) : [];

    const terceirizados = Array.isArray(dadosRdo.terceirizados) ? dadosRdo.terceirizados.map((terc, i) => ({
      idCampo: `rdo-terc-${i}`,
      empresaSubempreiteira: terc.empresaSubempreiteira || terc.empresa || 'Subempreiteiro',
      especialidade: terc.especialidade || terc.servico || 'Montagem',
      efetivo: Number(terc.efetivo || terc.qtd || 1),
      turno: terc.turno || 'Integral (8h)'
    })) : [];

    const equipamentos = Array.isArray(dadosRdo.equipamentosLista || dadosRdo.equipamentosApontados)
      ? (dadosRdo.equipamentosLista || dadosRdo.equipamentosApontados).map((eq, i) => ({
          idCampo: `rdo-equip-${i}`,
          equipamento: eq.equipamento || eq.nome || 'Betoneira 400L',
          horasUso: Number(eq.horasUso || eq.horas || 8),
          statusOperacional: eq.statusOperacional || 'Operando Normalmente'
        }))
      : [];

    const registro = {
      id: id,
      obra: obra,
      empresaId: dadosRdo.empresaId || 'emp-1',
      data: data,
      status: dadosRdo.status || 'Finalizado',
      climaManha: dadosRdo.climaManha || 'Claro',
      climaTarde: dadosRdo.climaTarde || 'Claro',
      trabalhadores: trabalhadores,
      terceirizados: terceirizados,
      equipamentosApontados: equipamentos,
      servicos: dadosRdo.servicos || '',
      equipamentos: dadosRdo.equipamentos || equipamentos.map((e) => `${e.equipamento} (${e.horasUso}h)`).join(', '),
      materiais: dadosRdo.materiais || '',
      ocorrencias: dadosRdo.ocorrencias || '',
      salvoEm: new Date().toISOString()
    };

    const idx = rdos.findIndex((r) => String(r.id) === String(id));
    if (idx >= 0) rdos[idx] = Object.assign({}, rdos[idx], registro);
    else rdos.unshift(registro);

    salvarJson('cm_rdos_db', rdos);
    if (typeof window.saveDb === 'function') {
      try { window.saveDb(rdos); } catch (e) {}
    }
    enfileirarSyncSupabaseV170('diarios_obra_rdo', 'UPSERT', registro);

    return {
      sucesso: true,
      rdo: registro
    };
  };

  window.recuperarRdoComTerceirizadosEEquipamentosV170 = function (rdoId) {
    const rdos = typeof window.getDb === 'function' ? window.getDb() : lerJson('cm_rdos_db', []);
    const encontrado = rdos.find((r) => String(r.id) === String(rdoId));
    if (!encontrado) return { sucesso: false, erro: 'RDO não encontrado.' };
    window.garantirIdsUnicosCamposRdoEPersistenciaV170();
    return {
      sucesso: true,
      rdo: encontrado,
      terceirizadosRecuperados: Array.isArray(encontrado.terceirizados) ? encontrado.terceirizados.length : 0,
      equipamentosRecuperados: Array.isArray(encontrado.equipamentosApontados) ? encontrado.equipamentosApontados.length : 0
    };
  };

