  // 1.9 Corrigir Pedidos Marcados como Fechado para Aparecerem Imediatamente em Pedidos Convertidos
  window.listarPedidosConvertidosFechadosUnificados = function (filtros = {}) {
    const mapa = new Map();
    const ehConvertidoOuFechado = (st) => {
      const s = String(st || '').toLowerCase();
      return (
        s.includes('fechad') ||
        s.includes('aprovad') ||
        s.includes('vendid') ||
        s.includes('venda realizada') ||
        s.includes('entregue') ||
        s.includes('convertid') ||
        s.includes('produ') ||
        s.includes('finalizad') ||
        s.includes('faturad')
      );
    };

    const statusFluxoSalvos = lerJson('cm_pedidos_convertidos_etapas_v16_8', {});

    const fontes = [
      ...(Array.isArray(window.pedidosVendaDb) ? window.pedidosVendaDb : []),
      ...lerJson('cm_pedidos_venda_db', []),
      ...(typeof window.obterOrcamentosComerciaisUnificadosV167 === 'function' ? window.obterOrcamentosComerciaisUnificadosV167() : []),
      ...(Array.isArray(window.orcamentosComerciaisDb) ? window.orcamentosComerciaisDb : []),
      ...lerJson('cm_orcamentos_comerciais_db', []),
      ...lerJson('cm_orcamentos_vendas_db_v1', []),
      ...lerJson('cm_orcamentos_vendas_db', []),
      ...lerJson('cm_orcamentos_db', [])
    ];

    fontes.forEach((o) => {
      if (!o || typeof o !== 'object') return;
      if (ehConvertidoOuFechado(o.status) || ehConvertidoOuFechado(o.statusComercial) || ehConvertidoOuFechado(o.etapaFluxo)) {
        const chave = String(o.orcamentoOrigemId || o.id || o.codigo || '').replace(/^PED-/, '');
        if (!chave) return;

        const stOrig = String(o.statusComercial || o.status || 'Fechado');
        const etapaFluxo =
          statusFluxoSalvos[chave] ||
          o.etapaFluxo ||
          (stOrig.toLowerCase().includes('entregue') || stOrig.toLowerCase().includes('finalizad')
            ? 'Finalizado / Entregue'
            : stOrig.toLowerCase().includes('produ')
            ? 'Em Produção / Atendimento'
            : 'Pedido de Venda');

        const existente = mapa.get(chave) || {};
        mapa.set(chave, Object.assign({}, existente, {
          id: String(o.id || '').startsWith('PED-') ? o.id : `PED-${chave}`,
          orcamentoOrigemId: chave,
          cliente: typeof o.cliente === 'object' ? o.cliente.nome : (o.cliente || existente.cliente || 'Cliente Comercial'),
          obra: o.obra || o.obraId || o.obraVinculada || existente.obra || 'Balcão / Obra Cliente',
          empresaId: o.empresaId || existente.empresaId || 'emp-1',
          empresa: o.empresa || existente.empresa || 'Construtora Martins',
          vendedorResponsavel: o.vendedorResponsavel || o.vendidoPor || o.aprovadoPor || existente.vendedorResponsavel || 'Henrique Camilo',
          valorTotal: arred2(Number(o.valorTotal !== undefined ? o.valorTotal : (o.total !== undefined ? o.total : (o.valor || existente.valorTotal || 0)))),
          data: o.data || o.dataFechamento || (o.vendidoEm ? String(o.vendidoEm).slice(0, 10) : new Date().toISOString().slice(0, 10)),
          status: stOrig,
          etapaFluxo: etapaFluxo,
          itens: Array.isArray(o.itens) && o.itens.length > 0 ? o.itens : (existente.itens || [])
        }));
      }
    });

    let lista = Array.from(mapa.values());
    if (filtros.empresaId && filtros.empresaId !== 'todas') {
      lista = lista.filter((x) => x.empresaId === filtros.empresaId);
    }
    if (filtros.obra && filtros.obra !== 'todas') {
      const qObra = String(filtros.obra).toLowerCase();
      lista = lista.filter((x) => String(x.obra || '').toLowerCase().includes(qObra));
    }
    if (filtros.cliente) {
      const qCli = String(filtros.cliente).toLowerCase();
      lista = lista.filter((x) => String(x.cliente || '').toLowerCase().includes(qCli));
    }
    return lista;
  };

