              { id: 'transferencias', rotulo: 'Transferências Formais entre Depósitos/Empresas', acao: () => window.navegarParaModuloErp('suprimentos', 'estoque') },
              { id: 'fornecedores', rotulo: 'Histórico de Pedidos, Fornecedores & Curva ABC', acao: () => window.navegarParaModuloErp('suprimentos', 'precos') }
