  // ============================================================================
  // SEÇÃO 4 — RH E FREQUÊNCIA: INTEGRAÇÃO AUTOMÁTICA DE ATESTADOS POR PERÍODO
  //           (DATA INICIAL A FINAL, TRATAMENTO DE CONFLITOS E SIGILO MÉDICO)
  // ============================================================================

  const FERIADOS_OFICIAIS_V170 = ['2026-01-01', '2026-04-21', '2026-05-01', '2026-09-07', '2026-10-12', '2026-11-02', '2026-11-15', '2026-11-20', '2026-12-25'];

  function gerarDatasIntervaloIso(dataIni, dataFim) {
    const datas = [];
    const dtIni = new Date(dataIni + 'T12:00:00Z');
    const dtFim = new Date(dataFim + 'T12:00:00Z');
    if (isNaN(dtIni.getTime()) || isNaN(dtFim.getTime()) || dtFim < dtIni) return [dataIni];
    const cursor = new Date(dtIni);
    let seguranca = 0;
    while (cursor <= dtFim && seguranca < 180) {
      datas.push(cursor.toISOString().slice(0, 10));
      cursor.setUTCDate(cursor.getUTCDate() + 1);
      seguranca++;
    }
    return datas;
  }

  window.registrarAtestadoMedicoPorPeriodoIntegradoV170 = function (dados = {}, usuarioExecutor = null) {
    const colabNome = String(dados.colaborador || dados.nomeColaborador || '').trim();
    const colabId = String(dados.colaboradorId || ('COL-' + colabNome.toLowerCase().replace(/[^a-z0-9]/g, '_')));
    if (!colabNome) return { sucesso: false, erro: 'Informe o colaborador para o atestado médico.' };

    const dataInicial = String(dados.dataInicial || dados.data || new Date().toISOString().slice(0, 10)).trim();
    const dataFinal = String(dados.dataFinal || dataInicial).trim();
    const diasPeriodo = gerarDatasIntervaloIso(dataInicial, dataFinal);

    const atestadosDb = lerJson('cm_atestados_medicos_periodo_v170', []);
    const freqMap = lerJson('cm_frequencia_diaria_periodo_v170', {});

    const idAtestado = dados.id || ('ATEST-' + colabId + '-' + dataInicial);
    const idxExistente = atestadosDb.findIndex((a) => a.id === idAtestado);

    // Se for uma alteração posterior de um atestado existente, limpa os dias antigos que este mesmo atestado havia marcado
    if (idxExistente >= 0) {
      const ant = atestadosDb[idxExistente];
      (ant.diasAplicadosNaFrequencia || []).forEach((diaAnt) => {
        const ch = `${diaAnt}|${colabNome.toLowerCase()}`;
        if (freqMap[ch] && freqMap[ch].atestadoOrigemId === idAtestado) {
          delete freqMap[ch];
        }
      });
    }

    const conflitosDetectados = [];
    const diasAplicados = [];

    diasPeriodo.forEach((diaIso) => {
      const dt = new Date(diaIso + 'T12:00:00Z');
      const diaSemana = dt.getUTCDay(); // 0 = Dom, 6 = Sáb
      const ehFimDeSemana = diaSemana === 0 || diaSemana === 6;
      const ehFeriado = FERIADOS_OFICIAIS_V170.includes(diaIso);
      const chaveFreq = `${diaIso}|${colabNome.toLowerCase()}`;
      const regExistente = freqMap[chaveFreq];

      if (regExistente && regExistente.atestadoOrigemId !== idAtestado) {
        if (String(regExistente.status || '').toLowerCase().includes('férias') || String(regExistente.status || '').toLowerCase().includes('ferias')) {
          conflitosDetectados.push({ data: diaIso, tipoConflito: 'FERIAS_JA_LANCADAS', acaoTomada: 'Preservado registro de Férias' });
          return;
        }
        if (!dados.sobrescreverFrequenciaExistente) {
          conflitosDetectados.push({
            data: diaIso,
            tipoConflito: 'FREQUENCIA_OU_FOLGA_EXISTENTE',
            statusExistente: regExistente.status,
            acaoTomada: 'Preservado lançamento existente (evitada sobrescrita sem confirmação)'
          });
          return;
        } else {
          conflitosDetectados.push({
            data: diaIso,
            tipoConflito: 'SOBRESCRITO_COM_AUTORIZACAO',
            statusAnterior: regExistente.status
          });
        }
      }

      freqMap[chaveFreq] = {
        data: diaIso,
        colaborador: colabNome,
        colaboradorId: colabId,
        empresaId: dados.empresaId || 'emp-1',
        obra: dados.obra || 'Afastamento Médico',
        status: 'Atestado Médico',
        tipoDia: ehFeriado ? 'FERIADO' : (ehFimDeSemana ? 'FIM_DE_SEMANA' : 'DIA_UTIL'),
        atestadoOrigemId: idAtestado,
        atualizadoEm: new Date().toISOString()
      };
      diasAplicados.push(diaIso);
    });

    const registroAtestado = {
      id: idAtestado,
      colaborador: colabNome,
      colaboradorId: colabId,
      empresaId: dados.empresaId || 'emp-1',
      dataInicial: dataInicial,
      dataFinal: dataFinal,
      quantidadeDiasPeriodo: diasPeriodo.length,
      diasAplicadosNaFrequencia: diasAplicados,
      conflitosDetectados: conflitosDetectados,
      cidConfidencial: dados.cid || 'Z00 (Sigilo Médico)',
      medico: dados.medico || 'Médico do Trabalho',
      motivoClinicoConfidencial: dados.motivo || 'Atestado Médico Homologado',
      anexoNome: dados.anexoNome || 'atestado_medico.pdf',
      atualizadoEm: new Date().toISOString()
    };

    if (idxExistente >= 0) atestadosDb[idxExistente] = registroAtestado;
    else atestadosDb.unshift(registroAtestado);

    salvarJson('cm_atestados_medicos_periodo_v170', atestadosDb);
    salvarJson('cm_frequencia_diaria_periodo_v170', freqMap);
    enfileirarSyncSupabaseV170('rh_atestados_medicos_periodo', 'UPSERT', registroAtestado);

    return {
      sucesso: true,
      atestado: registroAtestado,
      diasRefletidosNaFrequencia: diasAplicados,
      conflitosDetectados: conflitosDetectados
    };
  };

