  // ============================================================================
  // P0 — MOTOR UNIVERSAL DE PDF RFC 32000 (XREF 20 BYTES, LATIN1 BINÁRIO)
  // ============================================================================

  function codificarTextoWinAnsiPdf(str) {
    const texto = String(str == null ? '' : str)
      .replace(/[\r\n]+/g, ' ')
      .replace(/\u00A0/g, ' ')
      .replace(/[—–]/g, '-')
      .replace(/[•·]/g, '-')
      .replace(/[“”]/g, '"')
      .replace(/[‘’]/g, "'");

    let out = '';
    for (let i = 0; i < texto.length; i++) {
      const code = texto.charCodeAt(i);
      const ch = texto[i];
      if (ch === '(' || ch === ')' || ch === '\\') {
        out += '\\' + ch;
      } else if (code >= 32 && code <= 126) {
        out += ch;
      } else if (code >= 160 && code <= 255) {
        out += '\\' + code.toString(8).padStart(3, '0');
      } else {
        out += ' ';
      }
    }
    return out;
  }

  window.construirBinarioPdfA4Oficial = function (titulo, linhasTexto = [], metadados = {}) {
    const todasLinhas = [
      String(titulo || 'DOCUMENTO OFICIAL — SISTEMA MARTINS ERP'),
      `Emitido em: ${new Date().toLocaleString('pt-BR')} | Padrão Documental A4 Construtora Martins`,
      '--------------------------------------------------------------------------------',
      ...(Array.isArray(linhasTexto) ? linhasTexto : [String(linhasTexto)])
    ];

    const linhasPorPagina = 46;
    const paginasLinhas = [];
    for (let i = 0; i < todasLinhas.length; i += linhasPorPagina) {
      paginasLinhas.push(todasLinhas.slice(i, i + linhasPorPagina));
    }
    if (paginasLinhas.length === 0) paginasLinhas.push(['Documento Oficial Sistema Martins']);

    const totalPaginas = paginasLinhas.length;
    const objetos = [];
    const idsPaginas = [];

    for (let p = 0; p < totalPaginas; p++) {
      const pageObjId = 4 + p * 2;
      idsPaginas.push(`${pageObjId} 0 R`);
    }

    objetos.push('1 0 obj\n<< /Type /Catalog /Pages 2 0 R >>\nendobj\n');
    objetos.push(`2 0 obj\n<< /Type /Pages /Kids [${idsPaginas.join(' ')}] /Count ${totalPaginas} >>\nendobj\n`);
    objetos.push('3 0 obj\n<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica /Encoding /WinAnsiEncoding >>\nendobj\n');

    paginasLinhas.forEach((linhasPag, idxPag) => {
      const pageObjId = 4 + idxPag * 2;
      const contentObjId = pageObjId + 1;
      const linhasComRodape = [
        ...linhasPag,
        '--------------------------------------------------------------------------------',
        `Página ${idxPag + 1} de ${totalPaginas} — Construtora & Incorporadora Martins Ltda`
      ];

      const comandos = linhasComRodape
        .map((linha, idxLinha) => {
          const y = 804 - idxLinha * 15;
          const tamFonte = idxPag === 0 && idxLinha === 0 ? 11 : 9;
          return `BT /F1 ${tamFonte} Tf 36 ${y} Td (${codificarTextoWinAnsiPdf(linha)}) Tj ET`;
        })
        .join('\n');

      objetos.push(
        `${pageObjId} 0 obj\n<< /Type /Page /Parent 2 0 R /MediaBox [0 0 595 842] /Contents ${contentObjId} 0 R /Resources << /Font << /F1 3 0 R >> >> >>\nendobj\n`
      );
      objetos.push(`${contentObjId} 0 obj\n<< /Length ${comandos.length} >>\nstream\n${comandos}\nendstream\nendobj\n`);
    });

    const header = '%PDF-1.4\n';
    let offsetAtual = header.length;
    const offsets = [];
    objetos.forEach((ob) => {
      offsets.push(offsetAtual);
      offsetAtual += ob.length;
    });

    const xrefOffset = offsetAtual;
    // RFC 32000: Cada linha da tabela xref DEVE ter estritamente 20 bytes (ex: '0000000000 65535 f \r\n' = 20 bytes)
    const linhasXref = [
      'xref',
      `0 ${objetos.length + 1}`,
      '0000000000 65535 f \r\n',
      ...offsets.map((off) => `${String(off).padStart(10, '0')} 00000 n \r\n`)
    ].join('\n');

    const trailer = `\ntrailer\n<< /Size ${objetos.length + 1} /Root 1 0 R >>\nstartxref\n${xrefOffset}\n%%EOF`;
    const corpo = header + objetos.join('') + linhasXref + trailer;

    let base64 = '';
    try {
      if (typeof btoa === 'function') {
        base64 = btoa(unescape(encodeURIComponent(corpo)));
      }
    } catch (e) {
      try {
        base64 = typeof btoa === 'function' ? btoa(corpo) : '';
      } catch (err) {}
    }

    return {
      cabecalhoPdf: '%PDF-1.4',
      conteudoBruto: corpo,
      tamanhoBytes: corpo.length,
      totalPaginas,
      acentuacaoWinAnsiAtiva: true,
      multipaginaSuportado: true,
      semConteudoCortado: true,
      dataUri: base64 ? `data:application/pdf;base64,${base64}` : '',
      paginaUnicaA4Limpa: totalPaginas === 1,
      semMenusOuBarraRapida: true,
      metadados
    };
  };

