  window.calcularAlertaPrazoCompraV171 = function (prazoEntregaIso, status) {
    if (status === 'Entregue' || status === 'Recebido') {
      return { classe: 'bg-emerald-100 text-emerald-900 border-emerald-300', texto: '✓ Atendido', nivel: 'atendido' };
    }
    if (!prazoEntregaIso) {
      return { classe: 'bg-slate-100 text-slate-700 border-slate-300', texto: 'A combinar', nivel: 'normal' };
    }

    const hoje = new Date();
    hoje.setHours(0, 0, 0, 0);
    const prazo = new Date(prazoEntregaIso + 'T00:00:00');
    const diffDias = Math.ceil((prazo - hoje) / (1000 * 60 * 60 * 24));

    if (diffDias < 0) {
      return { classe: 'bg-rose-100 text-rose-900 border-rose-400 font-black', texto: `⚠️ Vencido há ${Math.abs(diffDias)}d`, nivel: 'vencido' };
    }
    if (diffDias <= 2) {
      return { classe: 'bg-amber-100 text-amber-900 border-amber-400 font-bold', texto: `🟡 Próximo (${diffDias}d)`, nivel: 'proximo' };
    }
    return { classe: 'bg-blue-50 text-blue-800 border-blue-200', texto: `🟢 No prazo (${diffDias}d)`, nivel: 'no_prazo' };
  };

  window.adicionarCotacaoFornecedorAoPedidoV171 = function (pedidoId, dadosCotacao) {
    const pedidos = typeof window.getPedidosDb === 'function' ? window.getPedidosDb() : lerJson('cm_pedidos_db', []);
    const ped = pedidos.find((p) => p.id === pedidoId);
    if (!ped) return { sucesso: false, erro: 'Pedido não encontrado.' };

    ped.cotacoes3Fornecedores = ped.cotacoes3Fornecedores || [];
    const novaCotacao = {
      id: `COT-${Date.now()}-${ped.cotacoes3Fornecedores.length + 1}`,
      fornecedorNome: dadosCotacao.fornecedorNome || 'Fornecedor Cotação',
      cnpj: dadosCotacao.cnpj || '',
      valorTotal: Number(dadosCotacao.valorTotal || 0),
      prazoEntregaDias: Number(dadosCotacao.prazoEntregaDias || 5),
      condicoesPagamento: dadosCotacao.condicoesPagamento || 'À Vista / 30 dias',
      comprovanteAnexo: dadosCotacao.comprovanteAnexo || null,
      vencedora: Boolean(dadosCotacao.vencedora),
      cadastradoEm: new Date().toISOString()
    };

    ped.cotacoes3Fornecedores.push(novaCotacao);
    if (typeof window.savePedidosDb === 'function') {
      window.savePedidosDb(pedidos);
    } else {
      salvarJson('cm_pedidos_db', pedidos);
    }

    return {
      sucesso: true,
      totalCotacoes: ped.cotacoes3Fornecedores.length,
      pedidoId: ped.id,
      cotacao: novaCotacao
    };
  };

