  window.salvarNovoOrcamentoVendaOuObraV171 = function (e) {
    if (e && typeof e.preventDefault === 'function') e.preventDefault();

    const tipoDestinoEl = document.querySelector('input[name="orc-tipo-destino"]:checked');
    const tipoDestino = tipoDestinoEl ? tipoDestinoEl.value : 'CLIENTE';

    const emp = document.getElementById('orc-inp-empresa') ? document.getElementById('orc-inp-empresa').value : 'Construtora & Incorporadora Martins Ltda';
    const clienteInp = document.getElementById('orc-inp-cliente');
    const obraSelect = document.getElementById('orc-select-obra-destino');

    let clienteNome = '';
    let obraIdVinculada = '';

    if (tipoDestino === 'OBRA') {
      obraIdVinculada = obraSelect ? obraSelect.value : 'OBR-UEMG-01';
      clienteNome = `Fornecimento Interno — Obra: ${obraIdVinculada}`;
    } else {
      clienteNome = clienteInp ? clienteInp.value.trim() : '';
      if (!clienteNome) {
        if (typeof window.showToast === 'function') {
          window.showToast('Para venda externa, o nome do cliente é obrigatório.', 'warning');
        }
        return { sucesso: false, erro: 'Cliente obrigatório' };
      }
    }

    const linhas = window.linhasOrcamentoModal || [];
    if (linhas.length === 0) {
      if (typeof window.showToast === 'function') {
        window.showToast('Adicione pelo menos um item ao orçamento.', 'warning');
      }
      return { sucesso: false, erro: 'Sem itens' };
    }

    let total = 0;
    const itensProntos = linhas.map((it) => {
      const sub = (it.qtd || 1) * (it.precoUnit || 0);
      total += sub;
      return {
        desc: it.desc || 'Item de Orçamento',
        unid: it.unid || 'Un',
        qtd: it.qtd || 1,
        precoUnit: it.precoUnit || 0,
        total: sub
      };
    });

    const orcs = typeof window.getOrcamentosVendasDb === 'function' ? window.getOrcamentosVendasDb() : lerJson('cm_orcamentos_vendas_db', []);
    const novoOrc = {
      id: 'ORC-' + (orcs.length + 101),
      num: `${String(orcs.length + 1).padStart(3, '0')}/2026`,
      tipoDestino: tipoDestino,
      empresa: emp,
      cliente: clienteNome,
      obraIdVinculada: obraIdVinculada || null,
      data: new Date().toISOString().split('T')[0],
      status: tipoDestino === 'OBRA' ? 'Apropriado na Obra' : 'Orçamento Aberto',
      itens: itensProntos,
      total: total,
      condicoes: document.getElementById('orc-inp-condicoes') ? document.getElementById('orc-inp-condicoes').value : '',
      prazo: document.getElementById('orc-inp-prazo') ? document.getElementById('orc-inp-prazo').value : ''
    };

    orcs.unshift(novoOrc);
    if (typeof window.saveOrcamentosVendasDb === 'function') {
      window.saveOrcamentosVendasDb(orcs);
    } else {
      salvarJson('cm_orcamentos_vendas_db', orcs);
    }

    if (tipoDestino === 'OBRA' && obraIdVinculada) {
      const lancs = lerJson('cm_gastos_obras_apropriados_v171', []);
      lancs.push({
        id: `GST-MAT-${novoOrc.id}`,
        obraId: obraIdVinculada,
        categoria: 'MATERIAIS',
        origem: 'FORNECIMENTO_INTERNO',
        orcamentoId: novoOrc.id,
        valor: total,
        itens: itensProntos,
        data: novoOrc.data
      });
      salvarJson('cm_gastos_obras_apropriados_v171', lancs);
    }

    const modal = document.getElementById('modal-novo-orcamento-venda');
    if (modal) modal.classList.add('hidden');

    if (typeof window.renderListaOrcamentosVendas === 'function') {
      try { window.renderListaOrcamentosVendas(); } catch (e) {}
    }

    if (typeof window.showToast === 'function') {
      window.showToast(`✓ Proposta ${novoOrc.id} registrada com sucesso (${tipoDestino === 'OBRA' ? 'Obra Própria' : 'Venda Externa'})!`);
    }

    return {
      sucesso: true,
      orcamentoId: novoOrc.id,
      tipoDestino,
      total: total,
      obraApropriada: obraIdVinculada || null
    };
  };

