  window.salvarEdicaoContaBancariaV171 = function (e, contaId, dadosFallback) {
    if (e && typeof e.preventDefault === 'function') e.preventDefault();
    const elNome = document.getElementById('edit-cta-nome');
    const elBanco = document.getElementById('edit-cta-banco');
    const elEmp = document.getElementById('edit-cta-empresa');
    const elAg = document.getElementById('edit-cta-agencia');
    const elCc = document.getElementById('edit-cta-conta');
    const elSaldo = document.getElementById('edit-cta-saldo');

    const nome = elNome ? String(elNome.value).trim() : (dadosFallback?.nome || 'Conta Bancária');
    const banco = elBanco ? String(elBanco.value).trim() : (dadosFallback?.banco || '001 - BB');
    const empId = elEmp ? elEmp.value : (dadosFallback?.empresaId || 'emp-1');
    const ag = elAg ? String(elAg.value).trim() : (dadosFallback?.agencia || '');
    const cc = elCc ? String(elCc.value).trim() : (dadosFallback?.conta || '');
    const saldo = elSaldo ? (parseFloat(elSaldo.value) || 0) : (Number(dadosFallback?.saldoAtual) || 0);

    let contas = Array.isArray(window.contasBancariasGrupoDb) ? window.contasBancariasGrupoDb : [];
    let conta = contas.find((x) => x.id === contaId);
    if (!conta) {
      conta = { id: contaId || `CTA-${Date.now()}` };
      contas.push(conta);
    }

    conta.nome = nome;
    conta.banco = banco;
    conta.empresaId = empId;
    conta.agencia = ag;
    conta.conta = cc;
    conta.agenciaConta = `${ag} / ${cc}`;
    conta.saldoAtual = saldo;

    window.contasBancariasGrupoDb = contas;
    window.contasBancariasEmpresaDb = contas;
    salvarJson('cm_contas_bancarias_db', contas);

    const modal = document.getElementById('modal-editar-conta-bancaria-v171');
    if (modal) modal.classList.add('hidden');

    if (typeof window.abrirModuloFinanceiro7Abas === 'function') {
      window.abrirModuloFinanceiro7Abas('bancos');
    }

    if (typeof window.showToast === 'function') {
      window.showToast(`Conta bancária "${nome}" atualizada com sucesso!`);
    }

    return { sucesso: true, contaAtualizada: conta };
  };

