  window.atualizarIndicadoresSincronizacaoUI = window.aplicarCorrecaoDefinitivaCabecalhoMobileV172;
  window.determinarEstadoRealSincronizacao = function () {
    const st = window.obterEstadoRealSincronizacaoV172();
    return (window.ESTADOS_SYNC_OFICIAIS && window.ESTADOS_SYNC_OFICIAIS[st.estado]) || {
      codigo: st.codigo,
      corDot: st.corDot,
      icone: st.icone,
      labelCurto: st.rotuloCompacto,
      descricao: st.descricao
    };
  };

  // Proteção do Botão Voltar no Celular (popstate) — fecha modais/drawer ou volta para a tela anterior sem fechar o app
  window.historicoNavegacaoInternaV172 = window.historicoNavegacaoInternaV172 || ['painel'];
  window.tratarBotaoVoltarMobileSeguroV172 = function () {
    if (typeof document !== 'undefined') {
      // 1. Se houver modal aberto, fecha o modal
      const modaisAbertos = Array.from(document.querySelectorAll('.fixed.inset-0:not(.hidden)'))
        .filter((el) => el.id !== 'tela-login-gate' && (!el.style || el.style.display !== 'none'));
      if (modaisAbertos.length > 0) {
        const ultimoModal = modaisAbertos[modaisAbertos.length - 1];
        ultimoModal.classList.add('hidden');
        if (ultimoModal.style) ultimoModal.style.display = 'none';
        return { acao: 'FECHOU_MODAL', modalId: ultimoModal.id };
      }

      // 2. Se o menu lateral (drawer) estiver aberto, fecha o drawer
      const drawer = document.getElementById('drawer-menu-lateral');
      if (drawer && !drawer.classList.contains('hidden')) {
        if (typeof window.fecharDrawerMenu === 'function') window.fecharDrawerMenu();
        else drawer.classList.add('hidden');
        return { acao: 'FECHOU_DRAWER' };
      }

      // 3. Caso contrário, retorna para a seção anterior ou Painel Inicial sem encerrar o aplicativo
      if (window.historicoNavegacaoInternaV172.length > 1) {
        window.historicoNavegacaoInternaV172.pop();
        const destino = window.historicoNavegacaoInternaV172[window.historicoNavegacaoInternaV172.length - 1] || 'painel';
        if (typeof window.navegarParaModuloErp === 'function') window.navegarParaModuloErp(destino);
        return { acao: 'VOLTOU_SECAO', destino };
      }
    }
    return { acao: 'PERMANECEU_NO_APP', destino: 'painel' };
  };

  if (typeof window !== 'undefined' && typeof window.addEventListener === 'function' && !window._boundPopstateV172) {
    window._boundPopstateV172 = true;
    window.addEventListener('popstate', function () {
      window.tratarBotaoVoltarMobileSeguroV172();
      if (typeof history !== 'undefined' && typeof history.pushState === 'function') {
        try { history.pushState({ martinsApp: true }, ''); } catch (e) {}
      }
    });
  }

  // ============================================================================
  // SEÇÃO 2 — RH: CORRIGIR CADASTRO DE EPI E UNIFORMES ("Cadastrar EPI / Uniforme")
