  // Bug Corrigido: criarOrcamentoCalhasRufosCompleto e criarOrcamentoTelhasMultiMedidas
  // usavam "Lucas Mendes Comercial" (não cadastrado em emp-2), travando com VENDEDOR_RESPONSAVEL_INVALIDO_OU_NAO_AUTORIZADO!
  function resolverVendedorValidoParaEmpresa(empresaId, vendedorInformado) {
    const vends = typeof window.listarVendedoresAutorizadosPorEmpresa === 'function'
      ? window.listarVendedoresAutorizadosPorEmpresa(empresaId || 'emp-2')
      : [];
    if (vendedorInformado) {
      const achado = vends.find(
        (v) =>
          v.nome.toLowerCase() === String(vendedorInformado).toLowerCase().trim() ||
          v.usuario.toLowerCase() === String(vendedorInformado).toLowerCase().trim()
      );
      if (achado) return achado.nome;
    }
    const logado = obterUsuarioAtivo();
    const achadoLogado = vends.find((v) => normLogin(v.usuario) === normLogin(logado));
    if (achadoLogado) return achadoLogado.nome;
    return vends[0] ? vends[0].nome : 'Henrique Camilo';
  }

  const _origCriarOrcCalhasRufosCompleto = window.criarOrcamentoCalhasRufosCompleto;
