      const vendValido = resolverVendedorValidoParaEmpresa(empId, dados.vendedorResponsavel || dados.vendedorNome);
      return _origCriarOrcTelhasMulti.call(this, {
        ...dados,
        empresaId: empId,
        vendedorNome: vendValido,
        vendedorResponsavel: vendValido
      });
