  // Normaliza qualquer registro financeiro para garantir compatibilidade com todas as abas e módulos
  function normalizarRegistroFinanceiroV190(item) {
    if (!item || typeof item !== 'object') return null;
    const id = String(item.id || item.idImportacao || `FIN-${Date.now()}`);
    const tipoMov = String(item.tipo || item.tipoMovimentacao || (item.natureza === 'ENTRADA' ? 'RECEITA' : 'DESPESA')).toUpperCase();
    const natureza = item.natureza || (tipoMov === 'RECEITA' || tipoMov === 'ENTRADA' ? 'ENTRADA' : tipoMov === 'TRANSFERENCIA' ? 'TRANSFERENCIA' : 'SAIDA');
    const valorBase = arred2(item.valor ?? item.valorPrevisto ?? item.valorOriginal ?? 0);
    const pagoConfirmado =
      item.status === 'CONFIRMADO' ||
      item.status === 'PAGO' ||
      item.situacaoPagamento === 'Pago' ||
      item.statusFluxo6Estagios === '6_CONCILIADO' ||
      item.statusFluxo6Estagios === 'RECEBIDO_CONFIRMADO' ||
      Number(item.valorRealizado) > 0 ||
      Number(item.valorPago) > 0;
    const valorReal = pagoConfirmado ? arred2(item.valorRealizado || item.valorPago || valorBase) : 0;

    return Object.assign({}, item, {
      id,
      idImportacao: item.idImportacao || id,
      natureza,
      tipo: natureza === 'ENTRADA' ? 'RECEITA' : natureza === 'TRANSFERENCIA' ? 'TRANSFERENCIA' : 'DESPESA',
      tipoMovimentacao: natureza === 'ENTRADA' ? 'RECEITA' : natureza === 'TRANSFERENCIA' ? 'TRANSFERENCIA' : 'DESPESA',
      empresaId: item.empresaId || 'emp-1',
      descricao: item.descricao || item.historico || 'Movimentação Financeira',
      favorecido: item.favorecido || item.fornecedor || item.cliente || item.favorecidoOuCliente || '-',
      fornecedor: item.fornecedor || item.favorecido || item.favorecidoOuCliente || '-',
      valor: valorBase,
      valorPrevisto: valorBase,
      valorOriginal: valorBase,
      valorRealizado: valorReal,
      valorPago: valorReal,
      saldoAberto: Math.max(0, arred2(valorBase - valorReal)),
      vencimento: item.vencimento || item.dataVencimento || item.data || '2026-11-15',
      data: item.data || item.vencimento || item.dataEmissao || '2026-11-10',
      obraId: item.obraId && item.obraId !== '-' ? item.obraId : null,
      obra: item.obra && item.obra !== '-' ? item.obra : (item.obraId && item.obraId !== '-' ? item.obraId : null),
      centroCustoId: item.centroCustoId || null,
      centroCusto: item.centroCusto || item.centroCustoNome || item.categoriaFinanceira || 'Geral',
      categoriaFinanceira: item.categoriaFinanceira || item.categoria || 'Materiais',
      contaBancariaId: item.contaBancariaId || 'CTA-BB-MOV',
      status: item.status || (pagoConfirmado ? 'CONFIRMADO' : 'PENDENTE'),
      situacaoPagamento: item.situacaoPagamento || (pagoConfirmado ? 'Pago' : 'Pendente'),
      statusConferencia: item.statusConferencia || (pagoConfirmado ? 'CONFERIDO' : 'PENDENTE_CONFERENCIA'),
      statusFluxo6Estagios: item.statusFluxo6Estagios || item.statusFluxoRdo || (pagoConfirmado ? '6_CONCILIADO' : '1_REGISTRADO_PENDENTE_CONFERENCIA'),
      visibilidade: item.visibilidade === 'RESTRITO_MASTER' || item.restritoMaster === true ? 'RESTRITO_MASTER' : 'NORMAL',
      restritoMaster: item.visibilidade === 'RESTRITO_MASTER' || item.restritoMaster === true,
      origemOperacional: 'INTEGRACAO_AUTENTICADA_WORK',
      anexos: Array.isArray(item.anexos) ? item.anexos : [],
      historicoEdicoes: Array.isArray(item.historicoEdicoes) ? item.historicoEdicoes : []
    });
  }

  /**
   * Recupera, mescla e preserva todos os registros históricos do Financeiro
   * (sem sobrescrever registros criados pelo usuário e sem duplicar em F5/reloads).
   */
  window.recuperarEPreservarDadosFinanceirosHistoricosV190 = function (opcoes = {}) {
    // 1. Neutraliza a rotina que expurgava lançamentos históricos em runtime
    window.auditarEDesconsiderarLancamentosCodigoFonte = function () {
      return {
        sucesso: true,
        desativadoParaPreservarHistoricoRealV190: true,
        totalExpurgados: 0,
        mensagem: 'Proteção v19.0 ativa: Lançamentos históricos reais preservados.'
      };
    };

    // 2. Recupera e consolida Contas Bancárias (6 contas históricas + quaisquer contas adicionais criadas)
    const contasSalvas = lerJson('cm_contas_bancarias_grupo_db', lerJson('cm_contas_bancarias_db', []));
    const contasMemoria = Array.isArray(window.contasBancariasGrupoDb) ? window.contasBancariasGrupoDb : [];
    const mapaContas = new Map();

    CONTAS_BANCARIAS_HISTORICAS_OFICIAIS_V190.forEach((c) => {
      mapaContas.set(c.id, Object.assign({}, c));
    });
    [...contasSalvas, ...contasMemoria].forEach((c) => {
      if (c && c.id) {
        const base = mapaContas.get(c.id) || {};
        mapaContas.set(c.id, Object.assign({}, base, c));
      }
    });

    const listaContasFinal = Array.from(mapaContas.values());
    window.contasBancariasGrupoDb = listaContasFinal;
    window.contasBancariasEmpresaDb = listaContasFinal;
    salvarJson('cm_contas_bancarias_grupo_db', listaContasFinal);
    salvarJson('cm_contas_bancarias_db', listaContasFinal);

    // 3. Recupera e consolida Centros de Custo (11 Fyness + 25 Modelos v17.3 + personalizados)
    const ccAtuais = typeof window.obterCentrosCustoDbV173 === 'function' ? window.obterCentrosCustoDbV173() : lerJson('cm_centros_custo_v173_db', []);
    const mapaCc = new Map();
    ccAtuais.forEach((c) => {
      if (c && c.id) mapaCc.set(c.id, c);
    });
    CENTROS_CUSTO_HISTORICOS_FYNESS_V190.forEach((cf) => {
      if (!mapaCc.has(cf.id)) {
        mapaCc.set(cf.id, Object.assign({}, cf));
      }
    });
    const listaCcFinal = Array.from(mapaCc.values());
    window.centrosCustoErpDbV173 = listaCcFinal;
    salvarJson('cm_centros_custo_v173_db', listaCcFinal);

    // 4. Recupera e consolida Lançamentos Financeiros (26 Fyness + registros em localStorage e memória)
    const lancsStorage = lerJson('cm_lancamentos_financeiros_db', []);
    const despV173Storage = lerJson('cm_despesas_v173_db', []);
    const lancsMem = Array.isArray(window.lancamentosFinanceirosDb) ? window.lancamentosFinanceirosDb : [];
    const despV173Mem = Array.isArray(window.despesasClassificadasV173Db) ? window.despesasClassificadasV173Db : [];

    const mapaLancs = new Map();

    // Primeiro carrega os 26 lançamentos históricos oficiais Fyness
    LANCAMENTOS_FINANCEIROS_HISTORICOS_REAIS_V190.forEach((lh) => {
      const norm = normalizarRegistroFinanceiroV190(lh);
      if (norm) mapaLancs.set(norm.id, norm);
    });

    // Depois mescla o que já estava em storage ou memória (preservando edições e novos lançamentos!)
    [...lancsStorage, ...despV173Storage, ...lancsMem, ...despV173Mem].forEach((item) => {
      if (!item || typeof item !== 'object') return;
      const norm = normalizarRegistroFinanceiroV190(item);
      if (!norm) return;
      const existente = mapaLancs.get(norm.id);
      if (existente) {
        mapaLancs.set(norm.id, Object.assign({}, existente, norm));
      } else {
        mapaLancs.set(norm.id, norm);
      }
    });

    const todosConsolidados = Array.from(mapaLancs.values());
    const despesasConsolidadas = todosConsolidados.filter((l) => l.natureza === 'SAIDA');
    const receitasConsolidadas = todosConsolidados.filter((l) => l.natureza === 'ENTRADA');

    window.lancamentosFinanceirosDb = todosConsolidados;
    window.obrigacoesPagarDb = despesasConsolidadas.slice();
    window.despesasClassificadasV173Db = despesasConsolidadas.slice();
    window.despesasConsolidadasV173 = despesasConsolidadas.slice();
    window.contasReceberDb = receitasConsolidadas.slice();
    window.titulosReceberDb = receitasConsolidadas.slice();

    salvarJson('cm_lancamentos_financeiros_db', todosConsolidados);
    salvarJson('cm_despesas_v173_db', despesasConsolidadas);
    salvarJson('cm_obrigacoes_pagar_db', despesasConsolidadas);
    salvarJson('cm_contas_receber_db', receitasConsolidadas);

    // 5. Restaura tabelas auxiliares (#subview-despesas, #subview-contas) caso tenham sido limpas
    if (typeof document !== 'undefined') {
      const tbodyDespLegacy = document.querySelector('#subview-despesas tbody');
      if (tbodyDespLegacy && (tbodyDespLegacy.textContent.includes('desconsiderados') || tbodyDespLegacy.children.length <= 1)) {
        tbodyDespLegacy.innerHTML = despesasConsolidadas.slice(0, 20).map((d) => `
          <tr class="hover:bg-slate-50 text-xs border-b border-slate-100">
            <td class="p-2 font-mono text-[10px]">${esc(d.id)}</td>
            <td class="p-2 font-bold text-slate-800">${esc(d.descricao)}</td>
            <td class="p-2 text-slate-600">${esc(d.favorecido)}</td>
            <td class="p-2 text-slate-600">${esc(d.centroCusto || d.obraId || 'Geral')}</td>
            <td class="p-2 text-right font-black text-rose-700">${moedaBr(d.valorPrevisto)}</td>
            <td class="p-2 text-center"><span class="px-2 py-0.5 rounded bg-slate-100 text-[10px] font-bold">${esc(d.status)}</span></td>
          </tr>
        `).join('');
      }
    }

    const totalDespesasValor = arred2(despesasConsolidadas.reduce((acc, d) => acc + (Number(d.valorPrevisto) || 0), 0));
    const totalReceitasValor = arred2(receitasConsolidadas.reduce((acc, r) => acc + (Number(r.valorPrevisto) || 0), 0));
    const saldoTotalContas = arred2(listaContasFinal.reduce((acc, c) => acc + (Number(c.saldoAtual) || 0), 0));

    return {
      sucesso: true,
      recuperadoSemPerda: true,
      semDuplicidade: new Set(todosConsolidados.map((x) => x.id)).size === todosConsolidados.length,
      totalLancamentos: todosConsolidados.length,
      totalDespesasCount: despesasConsolidadas.length,
      totalReceitasCount: receitasConsolidadas.length,
      totalDespesasValor,
      totalReceitasValor,
      totalContasBancarias: listaContasFinal.length,
      saldoTotalContas,
      totalCentrosCusto: listaCcFinal.length
    };
  };

  // Executa a recuperação imediatamente na carga do módulo v19.0
  window.recuperarEPreservarDadosFinanceirosHistoricosV190();

  // Garante que qualquer novo lançamento via submeterMovimentacaoFinanceiraUi ou registrarLancamentoFinanceiroUnificado persista em localStorage
  const _origRegistrarLancUnificado = window.registrarLancamentoFinanceiroUnificado;
  if (typeof _origRegistrarLancUnificado === 'function') {
    window.registrarLancamentoFinanceiroUnificado = function (dados = {}, usuario = window.currentLoggedUser) {
      const res = _origRegistrarLancUnificado.apply(this, arguments);
      if (res && res.sucesso && res.lancamento) {
        const norm = normalizarRegistroFinanceiroV190(res.lancamento);
        const idx = (window.lancamentosFinanceirosDb || []).findIndex((x) => x.id === norm.id);
        if (idx >= 0) window.lancamentosFinanceirosDb[idx] = norm;
        else window.lancamentosFinanceirosDb.unshift(norm);
        salvarJson('cm_lancamentos_financeiros_db', window.lancamentosFinanceirosDb);
      }
      return res;
    };
  }

  // Envolve abrirModuloFinanceiro7Abas para sempre exibir TODOS os lançamentos recuperados (sem truncar em 12) + barra de filtros rápidos
  const _origAbrirFin7AbasV180 = window.abrirModuloFinanceiro7Abas;
