  // Deduplica colaboradores preservando todos os dados e vínculos
  window.deduplicarColaboradoresPreservandoDadosV190 = function () {
    const lista = typeof window.getColaboradoresDb === 'function'
      ? window.getColaboradoresDb()
      : (Array.isArray(window.initialColaboradoresDb) ? window.initialColaboradoresDb : []);
    const mapa = new Map();
    let duplicadosRemovidos = 0;

    lista.forEach((c) => {
      if (!c || typeof c !== 'object') return;
      const cpfLimpo = String(c.cpf || '').replace(/\D/g, '');
      const nomeChave = String(c.nome || '').toLowerCase().trim();
      const chave = cpfLimpo ? `CPF:${cpfLimpo}` : `NOME:${nomeChave}`;
      if (!chave || chave === 'NOME:') return;

      if (mapa.has(chave)) {
        duplicadosRemovidos++;
        const ant = mapa.get(chave);
        mapa.set(chave, Object.assign({}, ant, c, { id: ant.id || c.id }));
      } else {
        mapa.set(chave, Object.assign({}, c));
      }
    });

    const unicos = Array.from(mapa.values());
    if (unicos.length > 0) {
      window.initialColaboradoresDb = unicos;
      if (typeof window.saveColaboradoresDb === 'function') {
        try { window.saveColaboradoresDb(unicos); } catch (e) {}
      }
      salvarJson('cm_colaboradores_db', unicos);
    }

    return {
      sucesso: true,
      totalColaboradoresUnicos: unicos.length,
      duplicadosRemovidos
    };
  };

