  // Abre e renderiza o módulo unificado "RH e Frequência" com as 10 abas
  window.abrirAbaUnificadaRhEFrequenciaV190 = function (abaId = 'quadro') {
    window.abaAtivaRhFrequenciaV190 = abaId;
    window.deduplicarColaboradoresPreservandoDadosV190();

    if (typeof window.switchView === 'function') {
      try { window.switchView('colaboradores'); } catch (e) {}
    }

    if (typeof document !== 'undefined') {
      document.querySelectorAll('main > section').forEach((s) => s.classList.add('hidden'));
      const secColab = document.getElementById('view-colaboradores');
      if (secColab) {
        secColab.classList.remove('hidden');

        // Atualiza título do cabeçalho para "RH e Frequência"
        const hTitulo = document.getElementById('colab-header-titulo');
        const hBadge = document.getElementById('colab-header-badge');
        const hDesc = document.getElementById('colab-header-desc');
        if (hBadge) hBadge.textContent = 'Módulo Unificado · Gestão de Pessoas & Campo';
        if (hTitulo) hTitulo.textContent = '👷 RH e Frequência (Central Unificada)';
        if (hDesc) hDesc.textContent = 'Funcionários, Frequência Diária, Faltas e Atestados, Férias e Folgas, Planejamento de Equipes, Vales, Folha, EPI/Uniformes, Documentos e Relatórios.';

        // Atualiza botão da barra de navegação superior/inferior
        const navBtnColab = document.getElementById('nav-btn-colaboradores');
        if (navBtnColab) {
          navBtnColab.innerHTML = '👷 RH e Frequência';
        }

        // Renderiza barra das 10 abas unificadas
        let barra10 = document.getElementById('barra-10-abas-rh-frequencia-v190');
        const containerAbasAntigo = document.getElementById('container-abas-frequencia-rh');
        if (!barra10) {
          barra10 = document.createElement('div');
          barra10.id = 'barra-10-abas-rh-frequencia-v190';
          barra10.className = 'flex flex-wrap gap-1.5 bg-slate-900 p-2.5 rounded-2xl border border-slate-800 shadow-xs mb-4';
          if (containerAbasAntigo && containerAbasAntigo.parentNode) {
            containerAbasAntigo.parentNode.insertBefore(barra10, containerAbasAntigo);
            containerAbasAntigo.classList.add('hidden');
          } else {
            secColab.insertBefore(barra10, secColab.firstChild);
          }
        }

        barra10.innerHTML = ABAS_UNIFICADAS_RH_FREQUENCIA_V190.map((a) => {
          const ativa = a.id === abaId;
          return `<button type="button" id="btn-aba-rh-unif-${a.id}" data-aba-rh="${a.id}" onclick="window.abrirAbaUnificadaRhEFrequenciaV190('${a.id}')" class="px-3 py-1.5 rounded-xl text-xs font-black transition cursor-pointer ${ativa ? 'bg-amber-500 text-slate-950 shadow-xs' : 'bg-slate-800 text-slate-300 hover:bg-slate-700'}">${a.icone} ${a.rotulo}</button>`;
        }).join('');

        // Garante que as subviews complementares existam e alterna visibilidade
        garantirSubviewsComplementaresRhV190(secColab);

        const todasSubviewsIds = [
          'subview-quadro-colab',
          'subview-ponto-colab',
          'subview-relatorios-colab',
          'subview-uniformes-colab',
          'subview-faltas-atestados-v190',
          'subview-ferias-folgas-v190',
          'subview-planejamento-equipes-v190',
          'subview-vales-rh-v190',
          'subview-folha-rh-v190',
          'subview-documentos-rh-v190'
        ];
        todasSubviewsIds.forEach((sid) => {
          const el = document.getElementById(sid);
          if (el) el.classList.add('hidden');
        });

        const abaCfg = ABAS_UNIFICADAS_RH_FREQUENCIA_V190.find((a) => a.id === abaId) || ABAS_UNIFICADAS_RH_FREQUENCIA_V190[0];
        const alvoEl = document.getElementById(abaCfg.subviewId);
        if (alvoEl) alvoEl.classList.remove('hidden');

        // Se for uma das 4 abas originais do HTML, também aciona switchColabSubtab para sincronizar contadores
        if (['quadro', 'ponto', 'uniformes', 'relatorios'].includes(abaId) && typeof window.switchColabSubtab === 'function') {
          try { window.switchColabSubtab(abaId); } catch (e) {}
          if (alvoEl) alvoEl.classList.remove('hidden');
        }
      }
    }

    return {
      sucesso: true,
      moduloUnificado: 'RH e Frequência',
      abaAtiva: abaId,
      totalAbasDisponiveis: ABAS_UNIFICADAS_RH_FREQUENCIA_V190.length
    };
  };

