  window.testarTodosOs11PdfsObrigatoriosV190 = function (usuario = window.currentLoggedUser) {
    const usr = obterUsuarioAtivo(usuario);
    const resultados = {};
    let todosValidos = true;

    TIPOS_PDF_OFICIAIS_11_V190.forEach((tipo) => {
      const res = typeof window.exportarDocumentoPadronizadoPdfV165 === 'function'
        ? window.exportarDocumentoPadronizadoPdfV165(tipo, { empresaId: 'emp-1', titulo: `Documento Oficial — ${tipo}` }, usr)
        : { sucesso: false };
      const binValido = Boolean(
        res &&
        res.sucesso &&
        res.pdfBinario &&
        res.pdfBinario.cabecalhoPdf === '%PDF-1.4' &&
        String(res.pdfBinario.conteudoBruto || '').includes('0000000000 65535 f')
      );
      if (!binValido) todosValidos = false;
      resultados[tipo] = {
        sucesso: binValido,
        cabecalhoPdf: res?.pdfBinario?.cabecalhoPdf || null,
        possuiHtmlPreview: Boolean(res?.htmlFormatadoRico),
        tamanhoBytes: res?.pdfBinario?.tamanhoBytes || 0
      };
    });

    return {
      sucesso: todosValidos,
      totalTiposTestados: TIPOS_PDF_OFICIAIS_11_V190.length,
      resultados
    };
  };

