  // 4.4 VENDAS E PRODUÇÃO (4 Abas Internas: 1. Esquadrias, 2. Telhas, 3. Calhas e Rufos, 4. Serralheria)
  window.abrirSecaoVendasLote1 = function (subaba) {
    if (subaba === 'producao') {
      if (typeof window.navegarSubabaProducaoSerralheriaV170 === 'function') {
        window.navegarSubabaProducaoSerralheriaV170(window.subabaProducaoAtivaV170 || 'esquadrias');
      } else {
        window.navegarParaModuloErp('comercial', 'esquadrias');
      }
      return {
        sucesso: true,
        subaba: 'producao',
        abasInternasProducao: ['1. Esquadrias', '2. Telhas', '3. Calhas e Rufos', '4. Serralheria']
      };
    }

    // Ao abrir outras páginas de Vendas, oculta a barra exclusiva de Produção se estiver visível
    const barraProd = typeof document !== 'undefined' ? document.getElementById('barra-subabas-producao-serralheria-v170') : null;
    if (barraProd) barraProd.classList.add('hidden');

    if (subaba === 'pedidos-venda') {
      window.navegarParaModuloErp('comercial', 'orcamentos');
      if (typeof window.setSubtabComercial === 'function') {
        try { window.setSubtabComercial('orcamentos'); } catch (e) {}
      }
      return { sucesso: true, subaba: 'pedidos-venda' };
    }

    window.navegarParaModuloErp('comercial', subaba);
    if (typeof window.setSubtabComercial === 'function') {
      try { window.setSubtabComercial(subaba); } catch (e) {}
    }
    return { sucesso: true, subaba };
  };

  // Garante que ao chamar navegarSubabaProducaoSerralheriaV170 a barra de 4 abas internas fique sempre visível e com alvos >= 44px
  if (typeof window.navegarSubabaProducaoSerralheriaV170 === 'function') {
    const _origNavProdV170 = window.navegarSubabaProducaoSerralheriaV170;
    window.navegarSubabaProducaoSerralheriaV170 = function (subabaId) {
      const res = _origNavProdV170.apply(this, arguments);
      if (typeof document !== 'undefined') {
        const barraProd = document.getElementById('barra-subabas-producao-serralheria-v170');
        if (barraProd) {
          barraProd.classList.remove('hidden');
          barraProd.querySelectorAll('button').forEach((b) => {
            b.classList.add('min-h-[44px]');
          });
        }
      }
      return res;
    };
  }

