  window.cadastrarOuEditarMotoristaFrota = function (dados = {}, usuarioExecutor = obterUsuarioAtual()) {
    const nome = String(dados.nome || '').trim();
    const cnhNumero = String(dados.cnhNumero || '').trim();
    const cnhCategoria = String(dados.cnhCategoria || 'D').trim().toUpperCase();
    const cnhValidade = String(dados.cnhValidade || '').trim();
    const empresaId = String(dados.empresaId || 'emp-1').trim();

    if (!nome || !cnhNumero || !cnhValidade) {
      return {
        sucesso: false,
        codigo: 'CAMPOS_MOTORISTA_OBRIGATORIOS',
        erro: 'Nome do motorista, número da CNH e data de validade da CNH são obrigatórios.'
      };
    }

    window.motoristasFrotaDb = Array.isArray(window.motoristasFrotaDb) ? window.motoristasFrotaDb : [];
    const idx = window.motoristasFrotaDb.findIndex(
      (m) => (dados.id && m.id === dados.id) || (!dados.id && m.cnhNumero === cnhNumero)
    );

    if (idx >= 0 && !dados.id && !dados.permitirAtualizarPorCnh) {
      return {
        sucesso: false,
        duplicidadeBloqueada: true,
        codigo: 'MOTORISTA_CNH_DUPLICADA',
        erro: `Já existe um motorista cadastrado com a CNH nº ${cnhNumero}.`
      };
    }

    const registro = {
      id: idx >= 0 ? window.motoristasFrotaDb[idx].id : (dados.id || `MOT-${Date.now()}`),
      nome,
      cpf: String(dados.cpf || (idx >= 0 ? window.motoristasFrotaDb[idx].cpf : '') || '').trim(),
      empresaId,
      empresaNome: window.obterNomeEmpresaLote2 ? window.obterNomeEmpresaLote2(empresaId) : 'Construtora Martins',
      cnhNumero,
      cnhCategoria,
      cnhValidade,
      telefone: String(dados.telefone || '').trim(),
      veiculoPadrao: String(dados.veiculoPadrao || 'Frota Geral').trim(),
      ativo: dados.ativo !== false,
      atualizadoEm: new Date().toISOString(),
      atualizadoPor: usuarioExecutor.login || usuarioExecutor.nome || 'master'
    };

    if (idx >= 0) window.motoristasFrotaDb[idx] = registro;
    else window.motoristasFrotaDb.unshift(registro);

    salvarJson('cm_motoristas_frota_estab_db', window.motoristasFrotaDb);
    return {
      sucesso: true,
      operacao: idx >= 0 ? 'EDICAO' : 'CADASTRO',
      motorista: registro,
      totalMotoristas: window.motoristasFrotaDb.length
    };
  };

