  window.exportarRelatorioFeriasRhCsv = function (filtros = {}) {
    const rel = window.apurarRelatorioFeriasRhEstab(filtros);
    const cab = 'Funcionario;Empresa;Data Admissao;Periodo Aquisitivo;Periodo Concessivo;Dias Programados;Dias Usufruidos;Saldo Dias;Situacao';
    const rows = rel.linhas.map(
      (l) =>
        `${l.funcionario};${l.empresa};${l.dataAdmissao};${l.periodoAquisitivo};${l.periodoConcessivo};${l.diasProgramados};${l.diasUsufruidos};${l.saldoDias};${l.situacao}`
    );
    const csv = [cab, ...rows].join('\n');
    return { sucesso: true, csvConteudo: csv, totalLinhas: rows.length };
  };

