    // Sincroniza Contas de Origem e Destino filtradas pela empresa selecionada
    const selEmpTrf = panelBancos.querySelector('#trf-inp-empresa');
    const selOrig = panelBancos.querySelector('#trf-inp-conta-origem');
    const selDest = panelBancos.querySelector('#trf-inp-conta-destino');

    const atualizarContasTransferenciaPorEmpresa = () => {
      if (!selEmpTrf || !selOrig || !selDest) return;
      const empId = selEmpTrf.value;
      const contasEmp = (window.contasBancariasEmpresaDb || []).filter((c) => c.empresaId === empId && c.ativo !== false);
      selOrig.innerHTML = contasEmp.map((c) => `<option value="${esc(c.id)}">${esc(c.nome)} (${moedaBr(c.saldoAtual)})</option>`).join('');
      selDest.innerHTML = contasEmp.map((c, idx) => `<option value="${esc(c.id)}" ${idx === 1 ? 'selected' : ''}>${esc(c.nome)} (${moedaBr(c.saldoAtual)})</option>`).join('');
    };

    if (selEmpTrf) selEmpTrf.onchange = atualizarContasTransferenciaPorEmpresa;
