  window.calcularStatusValidadeDocumentoRhFase22 = function (dataValidadeIso) {
    if (!dataValidadeIso || !/^\d{4}-\d{2}-\d{2}$/.test(String(dataValidadeIso).trim())) {
      return { status: 'Sem Vencimento', corBadge: 'bg-slate-100 text-slate-700', diasRestantes: null, alerta: false };
    }
    const hoje = new Date('2026-11-11T12:00:00Z');
    const val = new Date(dataValidadeIso + 'T12:00:00Z');
    const dias = Math.round((val - hoje) / 86400000);
    if (dias < 0) {
      return { status: `Vencido há ${Math.abs(dias)}d`, corBadge: 'bg-rose-100 text-rose-800', diasRestantes: dias, alerta: true, vencido: true };
    }
    if (dias <= 30) {
      return { status: `Vence em ${dias}d`, corBadge: 'bg-amber-100 text-amber-900', diasRestantes: dias, alerta: true, proximoVencimento: true };
    }
    return { status: `Vigente (${dias}d)`, corBadge: 'bg-emerald-100 text-emerald-800', diasRestantes: dias, alerta: false };
  };

  window.adicionarDocumentoFuncionarioFichaFase22 = function (dados = {}) {
    const colabId = String(dados.colaboradorId || window.fichaColaboradorAtivoId || '').trim();
    const titulo = String(dados.tituloDocumento || '').trim();
    const tipo = String(dados.tipoDocumento || 'ASO').trim();
    if (!colabId || !titulo) {
      return { sucesso: false, erro: 'Informe o funcionário e o título do documento (ASO, CNH, Certificado ou Contrato).' };
    }

    window.documentosFichaFuncionarioDb = Array.isArray(window.documentosFichaFuncionarioDb)
      ? window.documentosFichaFuncionarioDb
      : [];

    const novoDoc = {
      id: dados.id || `DOC-FICHA-${Date.now()}-${Math.floor(Math.random() * 90 + 10)}`,
      colaboradorId: colabId,
      empresaId: dados.empresaId || 'emp-1',
      tipoDocumento: tipo,
      tituloDocumento: titulo,
      numeroRegistro: String(dados.numeroRegistro || '').trim(),
      dataEmissao: String(dados.dataEmissao || '2026-11-11').trim(),
      dataValidade: String(dados.dataValidade || '').trim(),
      arquivoAnexo: String(dados.arquivoAnexo || `${tipo.toLowerCase()}_anexo.pdf`).trim(),
      observacoes: String(dados.observacoes || '').trim(),
      ativo: true,
      criadoEm: new Date().toISOString()
    };

    window.documentosFichaFuncionarioDb.unshift(novoDoc);
    salvarJson('cm_documentos_ficha_funcionario_fase22_db', window.documentosFichaFuncionarioDb);

    if (typeof window.injetarSecaoDocumentosEResumoFeriasNaFichaFase22 === 'function') {
      window.injetarSecaoDocumentosEResumoFeriasNaFichaFase22(colabId);
    }

    return {
      sucesso: true,
      documento: novoDoc,
      validadeInfo: window.calcularStatusValidadeDocumentoRhFase22(novoDoc.dataValidade)
    };
  };

  window.consultarDocumentosFuncionarioFichaFase22 = function (colaboradorId, filtroTipo = 'TODOS') {
    const lista = (window.documentosFichaFuncionarioDb || []).filter(
      (d) => d && d.ativo !== false && String(d.colaboradorId) === String(colaboradorId)
    );
    const filtrados =
      filtroTipo && filtroTipo !== 'TODOS'
        ? lista.filter((d) => d.tipoDocumento.toLowerCase() === filtroTipo.toLowerCase())
        : lista;
    return filtrados.map((d) => ({
      ...d,
      validadeInfo: window.calcularStatusValidadeDocumentoRhFase22(d.dataValidade)
    }));
  };

