  window.resolverEnderecoLocalEntregaCompraFase23 = function (opcoes = {}) {
    const rawTipo = String(opcoes.tipoLocalEntrega || 'OBRA').trim().toUpperCase();
    const tipo = (rawTipo === 'OBRA' || rawTipo.includes('OBRA'))
      ? 'OBRA'
      : (rawTipo === 'ESCRITORIO' || rawTipo.includes('ESCRIT'))
      ? 'ESCRITORIO'
      : (rawTipo === 'OUTRO_AUTORIZADO' || rawTipo.includes('OUTRO'))
      ? 'OUTRO_AUTORIZADO'
      : rawTipo;
    const obra = String(opcoes.obra || 'UEMG - Bloco 1').trim();
    const empresaId = String(opcoes.empresaId || 'emp-1').trim();

    if (tipo === 'OBRA') {
      const endObra =
        opcoes.enderecoConferido ||
        window.MAPA_ENDERECOS_OBRAS_FASE23[obra] ||
        `Canteiro Oficial da Obra ${obra} — Passos/MG`;
      return {
        valido: true,
        tipoLocalEntrega: 'OBRA',
        rotuloLocalEntrega: 'Entregar no endereço da obra',
        enderecoEntrega: endObra,
        justificativaEnderecoAlternativo: ''
      };
    }

    if (tipo === 'ESCRITORIO') {
      const endEsc =
        opcoes.enderecoConferido ||
        window.MAPA_ENDERECOS_ESCRITORIOS_EMPRESAS_FASE23[empresaId] ||
        window.MAPA_ENDERECOS_ESCRITORIOS_EMPRESAS_FASE23['emp-1'];
      return {
        valido: true,
        tipoLocalEntrega: 'ESCRITORIO',
        rotuloLocalEntrega: 'Entregar no escritório',
        enderecoEntrega: endEsc,
        justificativaEnderecoAlternativo: ''
      };
    }

    if (tipo === 'OUTRO_AUTORIZADO') {
      const endAlt = String(opcoes.enderecoAlternativo || opcoes.enderecoEntrega || '').trim();
      const justAlt = String(opcoes.justificativaEnderecoAlternativo || opcoes.justificativaEndereco || opcoes.justificativaOutroEndereco || '').trim();
      if (!endAlt || !justAlt) {
        return {
          valido: false,
          codigo: 'ENDERECO_ALTERNATIVO_EXIGE_JUSTIFICATIVA',
          erro: 'Para "Outro endereço autorizado", informe obrigatoriamente o endereço completo e a justificativa operacional.'
        };
      }
      return {
        valido: true,
        tipoLocalEntrega: 'OUTRO_AUTORIZADO',
        rotuloLocalEntrega: 'Outro endereço autorizado',
        enderecoEntrega: endAlt,
        justificativaEnderecoAlternativo: justAlt
      };
    }

    return {
      valido: false,
      codigo: 'LOCAL_ENTREGA_OBRIGATORIO',
      erro: 'Selecione obrigatoriamente o Local de Entrega (Obra, Escritório ou Outro endereço autorizado).'
    };
  };

  // 1.5 Cálculo do Indicador de Atraso (não substitui o status operacional!)
  window.calcularIndicadorAtrasoPedidoCompraFase23 = function (pedido, dataReferenciaIso = '2026-11-11') {
    if (!pedido) return { atrasado: false, diasAtraso: 0, tipoAtraso: null, descricaoAlerta: '' };
    const statusNorm = window.normalizarStatusPedidoCompraFase23(pedido.status);

    // Pedidos integralmente entregues ou cancelados NUNCA geram alerta de atraso!
    if (statusNorm === 'Entregue' || statusNorm === 'Cancelado') {
      return { atrasado: false, diasAtraso: 0, tipoAtraso: null, descricaoAlerta: '' };
    }

    const hoje = new Date(dataReferenciaIso + 'T12:00:00Z');
    const dtNec = String(pedido.dataNecessaria || pedido.prazoEntrega || '').trim();
    const dtPrevFornecedor = String(pedido.previsaoEntrega || pedido.pedidoCompraOficial?.previsaoEntregaData || dtNec || '').trim();

    const calcDias = (dtIso) => {
      if (!/^\d{4}-\d{2}-\d{2}$/.test(dtIso)) return 0;
      const d = new Date(dtIso + 'T12:00:00Z');
      return Math.round((hoje - d) / 86400000);
    };

    // Caso 1: Pedido ainda não comprado e com prazo de necessidade vencido
    if (['Solicitado', 'Em cotação', 'Cotado — Com orçamento', 'Aguardando aprovação', 'Aprovado'].includes(statusNorm)) {
      const dias = calcDias(dtNec);
      if (dias > 0) {
        return {
          atrasado: true,
          diasAtraso: dias,
          prazoReferencia: dtNec,
          tipoAtraso: 'NAO_COMPRADO_PRAZO_VENCIDO',
          descricaoAlerta: `Pedido ainda não comprado com prazo de necessidade vencido há ${dias} dia(s) (${dtNec}).`,
          destinatarios: ['Engenharia responsável pela obra', 'Setor de Compras']
        };
      }
    }

    // Caso 2: Pedido comprado com previsão de entrega vencida
    if (statusNorm === 'Compra realizada / Pedido emitido') {
      const dias = calcDias(dtPrevFornecedor);
      if (dias > 0) {
        return {
          atrasado: true,
          diasAtraso: dias,
          prazoReferencia: dtPrevFornecedor,
          tipoAtraso: 'COMPRADO_ENTREGA_VENCIDA',
          descricaoAlerta: `Pedido emitido/comprado com previsão de entrega vencida há ${dias} dia(s) (${dtPrevFornecedor}).`,
          destinatarios: ['Engenharia responsável pela obra', 'Setor de Compras']
        };
      }
    }

    // Caso 3: Pedido parcialmente entregue e com saldo atrasado
    if (statusNorm === 'Parcialmente entregue') {
      const dias = calcDias(dtPrevFornecedor || dtNec);
      if (dias > 0) {
        return {
          atrasado: true,
          diasAtraso: dias,
          prazoReferencia: dtPrevFornecedor || dtNec,
          tipoAtraso: 'PARCIALMENTE_ENTREGUE_SALDO_ATRASADO',
          descricaoAlerta: `Pedido parcialmente entregue com saldo pendente em atraso há ${dias} dia(s).`,
          destinatarios: ['Engenharia responsável pela obra', 'Setor de Compras']
        };
      }
    }

    return { atrasado: false, diasAtraso: 0, tipoAtraso: null, descricaoAlerta: '' };
  };

