  window.exportarBoletimMedicaoPdfV168 = window.gerarBoletimMedicaoPdfUnificado;
  window.visualizarBoletimMedicaoModalV168 = window.gerarBoletimMedicaoPdfUnificado;
  window.imprimirBoletimMedicaoHistorico = window.gerarBoletimMedicaoPdfUnificado;

  // ============================================================================
  // 2. PREVISÃO DE RECEBIMENTOS DAS VENDAS E MEDIÇÕES INTEGRADA AO FINANCEIRO
  // ============================================================================

  window.previsaoRecebimentosVendasDb = lerJson('cm_previsao_recebimentos_vendas_db', []);

  window.gerarOuSincronizarPrevisaoRecebimentosVenda = function (orcamentoOuId, opcoes = {}) {
    const orc =
      typeof orcamentoOuId === 'object' && orcamentoOuId !== null
        ? orcamentoOuId
        : window.localizarOrcamentoComercialQualquerBase(orcamentoOuId);
    if (!orc || !orc.id) {
      return { sucesso: false, erro: 'Orçamento ou Pedido de Venda não localizado para gerar previsão de recebimento.' };
    }

    window.previsaoRecebimentosVendasDb = Array.isArray(window.previsaoRecebimentosVendasDb)
      ? window.previsaoRecebimentosVendasDb
      : lerJson('cm_previsao_recebimentos_vendas_db', []);

    window.lancamentosFinanceirosDb = Array.isArray(window.lancamentosFinanceirosDb)
      ? window.lancamentosFinanceirosDb
      : lerJson('cm_lancamentos_financeiros_lote2_db', []);

    const valorTotal = arred2(Number(orc.valorTotal ?? orc.valor ?? orc.total ?? 0));
    if (valorTotal <= 0) {
      return { sucesso: false, erro: 'O valor do orçamento/pedido deve ser maior que zero para gerar previsão de recebimento.' };
    }

    const qtdParcelas = Math.max(1, Math.min(12, Number(opcoes.parcelas || orc.qtdParcelas || 1)));
    const valorParcelaBase = arred2(valorTotal / qtdParcelas);
    const dataBaseStr = opcoes.dataPrimeiroVencimento || orc.dataEntregaPrevista || orc.data || '2026-11-25';
    const empresaId =
      orc.empresaId ||
      (String(orc.empresa || '').toLowerCase().includes('calha')
        ? 'emp-2'
        : String(orc.empresa || '').toLowerCase().includes('aço') || String(orc.empresa || '').toLowerCase().includes('serralheria')
        ? 'emp-3'
        : 'emp-1');
    const empresaNome =
      empresaId === 'emp-2'
        ? 'Calhas e Rufos Martins'
        : empresaId === 'emp-3'
        ? 'Aços RR / Serralheria & Telhas'
        : 'Construtora Martins';

    const titulosGerados = [];
    let bloqueadosDuplicidade = 0;

    for (let p = 1; p <= qtdParcelas; p++) {
      const chaveIdemp = `PREV-REC-VENDA-${orc.id}-P${p}`;
      let existente = window.previsaoRecebimentosVendasDb.find((r) => r.chaveIdempotencia === chaveIdemp);

      const valorParc = p === qtdParcelas ? arred2(valorTotal - valorParcelaBase * (qtdParcelas - 1)) : valorParcelaBase;
      const dVenc = new Date(dataBaseStr.slice(0, 10) + 'T12:00:00Z');
      if (isNaN(dVenc.getTime())) {
        dVenc.setTime(Date.now());
      }
      dVenc.setUTCDate(dVenc.getUTCDate() + (p - 1) * 30);
      const vencIso = dVenc.toISOString().slice(0, 10);

      if (existente) {
        bloqueadosDuplicidade++;
        titulosGerados.push(existente);
        continue;
      }

      const novoTitulo = {
        id: `REC-VND-${orc.id}-P${p}`,
        chaveIdempotencia: chaveIdemp,
        origemTipo: opcoes.origemTipo || 'VENDA_COMERCIAL',
        orcamentoId: orc.id,
        pedidoVendaId: orc.pedidoConvertidoId || `PV-${orc.id}`,
        empresaId,
        empresaNome,
        obraId: orc.obraId || orc.obra || 'Comercial / Fábrica',
        cliente: orc.cliente || 'Cliente Comercial',
        vendedor: orc.vendedorResponsavel || orc.vendedor || 'Equipe Comercial',
        centroCustoCodigo: '1.2',
        centroCusto: '1.2 Receita de Vendas / Produção',
        parcelaNumero: p,
        totalParcelas: qtdParcelas,
        valorPrevisto: valorParc,
        valorRecebido: 0,
        vencimento: vencIso,
        formaPagamento: opcoes.formaPagamento || orc.condicoes || 'Boleto / PIX',
        status: 'Previsto / A Receber',
        criadoEm: new Date().toISOString()
      };

      window.previsaoRecebimentosVendasDb.unshift(novoTitulo);
      titulosGerados.push(novoTitulo);

      // Sincroniza com window.lancamentosFinanceirosDb sem duplicidade!
      const idFin = `FIN-${chaveIdemp}`;
      if (!window.lancamentosFinanceirosDb.some((l) => l.id === idFin || l.chaveIdempotencia === chaveIdemp)) {
        window.lancamentosFinanceirosDb.unshift({
          id: idFin,
          chaveIdempotencia: chaveIdemp,
          empresaId,
          empresaNome,
          obraId: novoTitulo.obraId,
          obraNome: novoTitulo.obraId,
          centroCustoId: 'CC-SUB-1-2',
          centroCustoCodigo: '1.2',
          centroCusto: '1.2 Receita de Vendas / Produção',
          natureza: 'ENTRADA',
          tipo: 'RECEITA',
          categoriaFinanceira: 'Receita de Vendas Comerciais',
          descricao: `Previsão de Recebimento Venda ${orc.id} (${p}/${qtdParcelas}) — ${novoTitulo.cliente}`,
          favorecido: novoTitulo.cliente,
          valor: valorParc,
          valorPrevisto: valorParc,
          valorRealizado: 0,
          data: vencIso,
          vencimento: vencIso,
          situacao: 'A Receber',
          status: 'PREVISTO_A_RECEBER',
          statusConferencia: 'CONFERIDO',
          origemOrcamentoId: orc.id,
          criadoPor: obterUsuarioAtual()?.login || 'henrique',
          compartilhadoCom: []
        });
      }
    }

    salvarJson('cm_previsao_recebimentos_vendas_db', window.previsaoRecebimentosVendasDb);
    salvarJson('cm_lancamentos_financeiros_lote2_db', window.lancamentosFinanceirosDb);

    if (!opcoes.silenciarRender && typeof window.renderizarPainelPrevisaoRecebimentosVendasUi === 'function') {
      window.renderizarPainelPrevisaoRecebimentosVendasUi();
    }

    return {
      sucesso: true,
      orcamentoId: orc.id,
      valorTotalPrevisto: valorTotal,
      qtdParcelas,
      novosTitulosCriados: qtdParcelas - bloqueadosDuplicidade,
      duplicidadesEvitadas: bloqueadosDuplicidade,
      titulos: titulosGerados
    };
  };

  window.confirmarBaixaPrevisaoRecebimentoVenda = function (previsaoIdOuChave, dadosBaixa = {}) {
    window.previsaoRecebimentosVendasDb = Array.isArray(window.previsaoRecebimentosVendasDb)
      ? window.previsaoRecebimentosVendasDb
      : lerJson('cm_previsao_recebimentos_vendas_db', []);

    const tit = window.previsaoRecebimentosVendasDb.find(
      (r) => r.id === previsaoIdOuChave || r.chaveIdempotencia === previsaoIdOuChave || r.orcamentoId === previsaoIdOuChave
    );
    if (!tit) return { sucesso: false, erro: 'Título de previsão de recebimento não encontrado.' };

    if (tit.status === 'Recebido / Confirmado') {
      return {
        sucesso: false,
        codigo: 'RECEBIMENTO_JA_BAIXADO',
        duplicado: true,
        erro: 'Este recebimento de venda já foi confirmado anteriormente no caixa.'
      };
    }

    tit.valorRecebido = arred2(Number(dadosBaixa.valorRecebido ?? tit.valorPrevisto));
    tit.status = 'Recebido / Confirmado';
    tit.dataRecebimentoEfetivo = dadosBaixa.dataRecebimento || '2026-11-11';
    tit.contaBancariaId = dadosBaixa.contaBancariaId || 'CTA-BB-MOV';

    window.lancamentosFinanceirosDb = Array.isArray(window.lancamentosFinanceirosDb)
      ? window.lancamentosFinanceirosDb
      : lerJson('cm_lancamentos_financeiros_lote2_db', []);

    const lancFin = window.lancamentosFinanceirosDb.find(
      (l) => l.chaveIdempotencia === tit.chaveIdempotencia || l.id === `FIN-${tit.chaveIdempotencia}`
    );
    if (lancFin) {
      lancFin.valorRealizado = tit.valorRecebido;
      lancFin.situacao = 'Recebido';
      lancFin.status = 'RECEBIDO_CONFIRMADO';
    }

    salvarJson('cm_previsao_recebimentos_vendas_db', window.previsaoRecebimentosVendasDb);
    salvarJson('cm_lancamentos_financeiros_lote2_db', window.lancamentosFinanceirosDb);

    if (typeof window.renderizarPainelPrevisaoRecebimentosVendasUi === 'function') {
      window.renderizarPainelPrevisaoRecebimentosVendasUi();
    }

    return {
      sucesso: true,
      tituloBaixado: tit,
      lancamentoFinanceiroAtualizado: lancFin
    };
  };

  // Integra automaticamente a geração de Previsão de Recebimento ao aprovar ou converter orçamento em venda!
  const _origConvOrcFase22 = window.converterOrcamentoEmPedidoComReservaFase22;
  if (typeof _origConvOrcFase22 === 'function') {
    window.converterOrcamentoEmPedidoComReservaFase22 = function (orcamentoId, opcoes = {}) {
      const res = _origConvOrcFase22.apply(this, arguments);
      if (res && res.sucesso) {
        const prev = window.gerarOuSincronizarPrevisaoRecebimentosVenda(orcamentoId, opcoes);
        res.previsaoRecebimentos = prev;
      }
      return res;
    };
  }

  const _origMarcarVendido = window.marcarOrcamentoComoVendido;
  window.marcarOrcamentoComoVendido = function (orcId) {
    const res = typeof _origMarcarVendido === 'function' ? _origMarcarVendido.apply(this, arguments) : { sucesso: true };
    const prev = window.gerarOuSincronizarPrevisaoRecebimentosVenda(orcId);
    return { ...(res || { sucesso: true }), previsaoRecebimentos: prev };
  };

  const _origAlterarStatusOrc = window.alterarStatusOrcamentoVenda;
  if (typeof _origAlterarStatusOrc === 'function') {
    window.alterarStatusOrcamentoVenda = function (orcId, novoStatus) {
      const res = _origAlterarStatusOrc.apply(this, arguments);
      if (['Aprovado', 'Vendido', 'Entregue'].includes(String(novoStatus || '').trim())) {
        window.gerarOuSincronizarPrevisaoRecebimentosVenda(orcId);
      }
      return res;
    };
  }

  // Semeia previsões iniciais das vendas já aprovadas/convertidas para que o quadro nunca abra vazio
  let _jaInicializouPrevisoesVendas = false;
  window.inicializarPrevisoesRecebimentosVendasExistentes = function () {
    if (_jaInicializouPrevisoesVendas) return window.previsaoRecebimentosVendasDb;
    _jaInicializouPrevisoesVendas = true;
    const orcs =
      typeof window.obterOrcamentosComerciaisUnificadosV167 === 'function'
        ? window.obterOrcamentosComerciaisUnificadosV167()
        : lerJson('cm_orcamentos_vendas_db', []);
    (orcs || []).forEach((o) => {
      if (['Aprovado', 'Vendido', 'Entregue'].includes(String(o.status || '').trim())) {
        window.gerarOuSincronizarPrevisaoRecebimentosVenda(o, { silenciarRender: true });
      }
    });
    if ((window.previsaoRecebimentosVendasDb || []).length === 0) {
      window.gerarOuSincronizarPrevisaoRecebimentosVenda({
        id: 'ORC-2026-901',
        cliente: 'Construtora Horizonte Ltda',
        empresaId: 'emp-3',
        empresa: 'Aços RR / Serralheria & Telhas',
        vendedor: 'Josué Paiva',
        valorTotal: 14600.0,
        condicoes: '28/56 DDL Boleto',
        qtdParcelas: 2,
        data: '2026-11-11',
        status: 'Vendido'
      }, { silenciarRender: true });
    }
    return window.previsaoRecebimentosVendasDb;
  };

  window.renderizarPainelPrevisaoRecebimentosVendasUi = function () {
    window.inicializarPrevisoesRecebimentosVendasExistentes();
    if (typeof document === 'undefined') return { sucesso: true };

    const titulos = window.previsaoRecebimentosVendasDb || [];
    const totalPrevisto = arred2(titulos.reduce((a, b) => a + Number(b.valorPrevisto || 0), 0));
    const totalRecebido = arred2(titulos.reduce((a, b) => a + Number(b.valorRecebido || 0), 0));
    const totalAReceber = arred2(Math.max(0, totalPrevisto - totalRecebido));

    const htmlQuadro = `
      <div class="bg-white rounded-2xl p-4 border-2 border-emerald-500/40 shadow-2xs space-y-3 text-xs">
        <div class="flex flex-wrap items-center justify-between gap-2 border-b border-slate-100 pb-2.5">
          <div>
            <span class="px-2.5 py-0.5 rounded-full bg-emerald-100 text-emerald-900 font-black text-[10px] uppercase">Integração Comercial ➔ Financeiro</span>
            <h4 class="text-sm font-black text-slate-900 mt-1">💰 Previsão de Recebimentos das Vendas (${titulos.length} título(s))</h4>
            <p class="text-[11px] text-slate-500">Títulos gerados automaticamente a partir dos Orçamentos Aprovados e Pedidos de Venda convertidos.</p>
          </div>
          <div class="flex flex-wrap gap-2">
            <div class="px-3 py-1.5 rounded-xl bg-slate-50 border border-slate-200">
              <span class="text-[10px] text-slate-500 block uppercase font-bold">Total Previsto</span>
              <strong class="font-mono font-black text-slate-900">${moedaBr(totalPrevisto)}</strong>
            </div>
            <div class="px-3 py-1.5 rounded-xl bg-amber-50 border border-amber-200">
              <span class="text-[10px] text-amber-800 block uppercase font-bold">Saldo a Receber</span>
              <strong class="font-mono font-black text-amber-900">${moedaBr(totalAReceber)}</strong>
            </div>
            <div class="px-3 py-1.5 rounded-xl bg-emerald-50 border border-emerald-200">
              <span class="text-[10px] text-emerald-800 block uppercase font-bold">Já Recebido</span>
              <strong class="font-mono font-black text-emerald-800">${moedaBr(totalRecebido)}</strong>
            </div>
          </div>
        </div>
        <div class="overflow-x-auto">
          <table class="w-full text-left border-collapse text-xs">
            <thead class="bg-slate-900 text-white uppercase text-[10px]">
              <tr>
                <th class="p-2">Título / Orçamento</th>
                <th class="p-2">Empresa / Cliente</th>
                <th class="p-2 text-center">Parcela</th>
                <th class="p-2 text-center">Vencimento Previsto</th>
                <th class="p-2 text-right">Valor Previsto</th>
                <th class="p-2 text-right">Valor Recebido</th>
                <th class="p-2 text-center">Status</th>
                <th class="p-2 text-center">Ação Financeira</th>
              </tr>
            </thead>
            <tbody class="divide-y divide-slate-100">
              ${titulos
                .map(
                  (t) => `
                <tr class="hover:bg-slate-50" data-row-previsao-venda="${esc(t.id)}">
                  <td class="p-2 font-mono font-bold text-slate-900">${esc(t.id)}<div class="text-[10px] text-slate-500">Ref: ${esc(t.orcamentoId)}</div></td>
                  <td class="p-2 font-bold text-slate-900">${esc(t.cliente)}<div class="text-[10px] text-slate-500">${esc(t.empresaNome)} · Vend: ${esc(t.vendedor)}</div></td>
                  <td class="p-2 text-center font-mono font-bold">${t.parcelaNumero}/${t.totalParcelas}</td>
                  <td class="p-2 text-center font-mono">${esc(t.vencimento)}</td>
                  <td class="p-2 text-right font-mono font-black text-slate-900">${moedaBr(t.valorPrevisto)}</td>
                  <td class="p-2 text-right font-mono font-bold text-emerald-700">${moedaBr(t.valorRecebido)}</td>
                  <td class="p-2 text-center">
                    <span class="px-2 py-0.5 rounded-full text-[10px] font-black ${
                      t.status === 'Recebido / Confirmado' ? 'bg-emerald-100 text-emerald-900' : 'bg-amber-100 text-amber-950'
                    }">${esc(t.status)}</span>
                  </td>
                  <td class="p-2 text-center">
                    ${
                      t.status === 'Recebido / Confirmado'
                        ? `<span class="text-[10px] font-bold text-emerald-700">✓ Liquidado (${esc(t.dataRecebimentoEfetivo || '2026-11-11')})</span>`
                        : `<button type="button" onclick="window.confirmarBaixaPrevisaoRecebimentoVenda('${esc(t.id)}')" class="px-2.5 py-1 rounded-lg bg-emerald-600 hover:bg-emerald-700 text-white font-black text-[10px] cursor-pointer">💰 Confirmar Recebimento</button>`
                    }
                  </td>
                </tr>
              `
                )
                .join('')}
            </tbody>
          </table>
        </div>
      </div>
    `;

    // Injeta no final de #painel-com-orcamentos (sem duplicar!)
    const pOrc = document.getElementById('painel-com-orcamentos');
    if (pOrc) {
      let boxVendas = document.getElementById('quadro-previsao-recebimentos-vendas-comercial');
      if (!boxVendas) {
        boxVendas = document.createElement('div');
        boxVendas.id = 'quadro-previsao-recebimentos-vendas-comercial';
        pOrc.appendChild(boxVendas);
      }
      boxVendas.innerHTML = htmlQuadro;
    }

    // Injeta também dentro de #fin-tab-panel-receber quando a aba Contas a Receber estiver aberta!
    const pFinRec = document.getElementById('fin-tab-panel-receber');
    if (pFinRec) {
      let boxFin = document.getElementById('quadro-previsao-recebimentos-vendas-financeiro');
      if (!boxFin) {
        boxFin = document.createElement('div');
        boxFin.id = 'quadro-previsao-recebimentos-vendas-financeiro';
        pFinRec.insertBefore(boxFin, pFinRec.firstChild);
      }
      boxFin.innerHTML = htmlQuadro;
    }

    return { sucesso: true, totalTitulos: titulos.length, totalPrevisto, totalRecebido, totalAReceber };
  };

  // ============================================================================
  // 3. UNIFICAÇÃO DAS PERMISSÕES FINANCEIRAS E FIM DA TABELA DUPLICADA EM #view-financeiro
  // ============================================================================

  const _origAbrirModuloFin7Abas = window.abrirModuloFinanceiro7Abas;
  if (typeof _origAbrirModuloFin7Abas === 'function') {
    window.abrirModuloFinanceiro7Abas = function (aba = 'registrar', opcoes = {}) {
      const res = _origAbrirModuloFin7Abas.apply(this, arguments);
      const user = obterUsuarioAtual();
      const permF22 =
        typeof window.obterPermissoesFluxoCaixaUsuarioFase22 === 'function'
          ? window.obterPermissoesFluxoCaixaUsuarioFase22(user)
          : { visualizarLancamentos: true, criar: true, editar: true, excluir: true, aprovar: true, visualizarSaldos: true, compartilharLancamentos: true };

      if (typeof document !== 'undefined') {
        const viewFin = document.getElementById('view-financeiro');
        if (viewFin) {
          // Remove a tabela solta no final de #view-financeiro se existir, e usa um único container limpo dentro da aba!
          const solta = document.getElementById('painel-lista-lancamentos-fluxo-fase23');
          if (solta && solta.parentElement === viewFin) {
            solta.remove();
          }

          // Em fin-tab-panel-registrar, substitui o segundo card (Lançamentos Recentes desprotegido) pelo painel governado pelas permissões!
          const panelReg = document.getElementById('fin-tab-panel-registrar');
          if (panelReg) {
            const cardsReg = Array.from(panelReg.children);
            if (cardsReg.length > 1) {
              cardsReg[1].id = 'painel-lista-lancamentos-fluxo-fase23';
            }
            const formReg = document.getElementById('form-registrar-movimentacao-fin');
            if (formReg) {
              const btnSubmit = formReg.querySelector('button[type="submit"]');
              if (btnSubmit) {
                btnSubmit.disabled = !permF22.criar;
                btnSubmit.classList.toggle('opacity-50', !permF22.criar);
              }
            }
          }

          // Se estiver na aba receber, injeta o quadro de Previsão de Recebimentos das Vendas
          if (aba === 'receber') {
            window.renderizarPainelPrevisaoRecebimentosVendasUi();
          }

          // Aplica as permissões visuais de Fluxo de Caixa (ocultando lista se visualizarLancamentos=false e ocultando saldos se visualizarSaldos=false)
          if (panelReg && window.obterContextoSegurancaAutenticadoWork?.()) {
            window.renderizarSeletorFluxoCaixaQa?.(panelReg);
          } else if (typeof window.aplicarPermissoesVisuaisNaTelaFinanceiroFase23 === 'function') {
            window.aplicarPermissoesVisuaisNaTelaFinanceiroFase23(user);
          }
        }
      }
      return res;
    };
  }

  // ============================================================================
  // 4. ELIMINAÇÃO DEFINITIVA DE SOBREPOSIÇÃO DAS TABELAS EM TODOS OS MÓDULOS
  // ============================================================================

  window.injetarCssAntiSobreposicaoTabelasELote3Mobile = function () {
    if (typeof document === 'undefined') return;
    if (document.getElementById('style-anti-sobreposicao-lote3')) return;

    const style = document.createElement('style');
    style.id = 'style-anti-sobreposicao-lote3';
    style.textContent = `
      /* Prevenção absoluta de sobreposição entre tabelas e painéis irmãos */
      #view-gestao > div,
      #view-comercial > div,
      #view-colaboradores > div,
      #view-suprimentos > div,
      #view-financeiro > div,
      #subview-relatorios-colab > div {
        clear: both;
        position: relative;
        max-width: 100%;
        box-sizing: border-box;
      }
      .overflow-x-auto {
        overflow-x: auto !important;
        -webkit-overflow-scrolling: touch;
        max-width: 100%;
      }
      table {
        border-collapse: collapse;
        width: 100%;
      }
      /* Ajuste Mobile Lote 3: margem de segurança inferior para que a barra fixa mobile nunca cubra tabelas ou botões */
      @media (max-width: 1024px) {
        main {
          padding-bottom: 5.5rem !important;
        }
        button, select, input[type="date"], input[type="text"], input[type="number"] {
          min-height: 38px;
        }
      }
    `;
    document.head.appendChild(style);
  };

  window.garantirExclusividadeSubviewsGestaoObras = function (subabaAtivaOpcional = null) {
    if (typeof document === 'undefined') return { sucesso: true };
    const todasSubviewsGestao = [
      'subview-planilha',
      'subview-medicao',
      'subview-cronograma',
      'subview-custos',
      'subview-materiais',
      'subview-relatorios-obra',
      'subview-obs',
      'subview-contas',
      'subview-vendas',
      'subview-frota'
    ];

    let idAlvo = subabaAtivaOpcional ? (subabaAtivaOpcional.startsWith('subview-') ? subabaAtivaOpcional : `subview-${subabaAtivaOpcional}`) : null;
    if (!idAlvo) {
      // Descobre qual está visível; se mais de uma estiver visível (ex: subview-medicao e subview-planilha no boot), prioriza a primeira!
      const visiveis = todasSubviewsGestao.filter((id) => {
        const el = document.getElementById(id);
        return el && !el.classList.contains('hidden');
      });
      idAlvo = visiveis[0] || 'subview-planilha';
    }

    todasSubviewsGestao.forEach((id) => {
      const el = document.getElementById(id);
      if (el) {
        if (id === idAlvo) el.classList.remove('hidden');
        else el.classList.add('hidden');
      }
    });

    // Remove qualquer tabela de planilha duplicada que tenha sido injetada acidentalmente dentro de #subview-obs
    const subObs = document.getElementById('subview-obs');
    if (subObs) {
      subObs.querySelectorAll('table').forEach((tbl) => {
        if (tbl.textContent.includes('SINAPI') || tbl.textContent.includes('Planilha Orçamentária')) {
          tbl.closest('div')?.remove();
        }
      });
    }

    return { sucesso: true, subviewAtiva: idAlvo, sobreposicaoEliminada: true };
  };

