  // ============================================================================
  // 2. MELHORIA VISUAL E FUNCIONAL DA TELA DE PEDIDOS DE MATERIAIS (10 SEÇÕES
  //    CLARAS, CARTÕES RESPONSIVOS NO CELULAR E INCLUSÃO/EXCLUSÃO DE ITENS)
  // ============================================================================

  window.incluirItemAdicionalAoPedidoFase24 = function (pedidoId, dadosNovoItem = {}, usuarioExecutor = obterUsuarioAtual()) {
    const lista = window.inicializarPedidosMateriaisFase23();
    const ped = lista.find((p) => p.id === pedidoId);
    if (!ped) return { sucesso: false, erro: 'Pedido não localizado.' };

    const desc = String(dadosNovoItem.material || dadosNovoItem.descricao || '').trim();
    const qtd = Number(dadosNovoItem.quantidade ?? dadosNovoItem.qtd ?? 0);
    if (!desc || qtd <= 0) {
      return { sucesso: false, erro: 'Informe a descrição do material e uma quantidade maior que zero.' };
    }

    ped.itens = Array.isArray(ped.itens) ? ped.itens : [];
    const novoIdx = ped.itens.length + 1;
    const novoItem = {
      idItem: dadosNovoItem.idItem || `IT-${ped.id}-${Date.now()}-${novoIdx}`,
      item: novoIdx,
      numeroItemPlanilha: String(dadosNovoItem.numeroItemPlanilha || '').trim(),
      codigo: String(dadosNovoItem.codigo || `MAT-0${novoIdx}`).trim(),
      material: desc,
      quantidade: qtd,
      qtdRecebidaAcumulada: 0,
      unidade: String(dadosNovoItem.unidade || 'UN').trim(),
      especificacoes: String(dadosNovoItem.especificacoes || '').trim(),
      statusItem: 'Em cotação',
      anexosItem: []
    };

    ped.itens.push(novoItem);
    // Se já havia cotação, retorna para Em cotação pois o escopo do pedido mudou
    if ((ped.cotacoes || []).length > 0) {
      ped.status = 'Em cotação';
      ped.cotacoes.forEach((c) => {
        c.desatualizadaPorEdicaoItem = true;
        c.statusCotacao = 'DESATUALIZADA';
      });
    }

    ped.historicoStatus = Array.isArray(ped.historicoStatus) ? ped.historicoStatus : [];
    ped.historicoStatus.push({
      status: ped.status,
      dataHora: new Date().toISOString(),
      responsavel: usuarioExecutor?.nome || 'Engenharia',
      observacao: `Item adicional incluído: "${desc}" (${qtd} ${novoItem.unidade}) — Planilha: ${novoItem.numeroItemPlanilha || '-'}.`
    });

    window.salvarSolicitacoesEPedidosCompraV169(lista);
    window.renderizarPainelComprasCompletoV169();
    return { sucesso: true, itemIncluido: novoItem, totalItens: ped.itens.length, statusAtualPedido: ped.status };
  };

  window.excluirItemPedidoCompraFase24 = function (pedidoId, itemIdOuIdx, usuarioExecutor = obterUsuarioAtual()) {
    const lista = window.inicializarPedidosMateriaisFase23();
    const ped = lista.find((p) => p.id === pedidoId);
    if (!ped) return { sucesso: false, erro: 'Pedido não localizado.' };

    if ((ped.itens || []).length <= 1) {
      return { sucesso: false, codigo: 'PEDIDO_EXIGE_MINIMO_UM_ITEM', erro: 'O pedido deve manter pelo menos 1 item ativo. Para desistir de todo o pedido, utilize Cancelar.' };
    }

    const idx = (ped.itens || []).findIndex((i, k) => i.idItem === itemIdOuIdx || String(k) === String(itemIdOuIdx));
    if (idx < 0) return { sucesso: false, erro: 'Item não localizado no pedido.' };

    const removido = ped.itens.splice(idx, 1)[0];
    ped.itens.forEach((it, k) => {
      it.item = k + 1;
    });

    window.salvarSolicitacoesEPedidosCompraV169(lista);
    window.renderizarPainelComprasCompletoV169();
    return { sucesso: true, itemRemovido: removido, totalItensRestantes: ped.itens.length };
  };

  // Sobrescreve window.renderizarPainelComprasCompletoV169 para entregar o layout em 10 seções claras + cartões responsivos no celular!
