  const _origRegistrarValeSegura = window.registrarConcessaoValeSegura;
  if (typeof _origRegistrarValeSegura === 'function') {
    window.registrarConcessaoValeSegura = function (dadosSolicitacao = {}, usuarioExecutor = obterUsuarioAtual()) {
      // Corrige cálculo de valorBrutoTrabalhado para diaristas quando diasTrabalhadosNoPeriodo é informado
      if (dadosSolicitacao && !dadosSolicitacao.salarioMensal) {
        const colabs = typeof window.getColaboradoresDb === 'function' ? window.getColaboradoresDb() : [];
        const colab = colabs.find((c) => c.id === dadosSolicitacao.colabId || c.nome === dadosSolicitacao.colabNome);
        const remBase = Number(colab?.salario || colab?.salarioBase || colab?.diaria || 120);
        if (remBase < 600) {
          dadosSolicitacao.salarioMensal = remBase * 30;
        }
      }
      const res = _origRegistrarValeSegura.call(this, dadosSolicitacao, usuarioExecutor);
      if (res && res.aprovado && res.vale) {
        const v = res.vale;
        window.lancamentosFinanceirosDb = Array.isArray(window.lancamentosFinanceirosDb)
          ? window.lancamentosFinanceirosDb
          : lerJson('cm_lancamentos_financeiros_lote2_db', []);
        const idFinVale = `FIN-VALE-${v.id}`;
        if (!window.lancamentosFinanceirosDb.some((l) => l.id === idFinVale)) {
          window.lancamentosFinanceirosDb.unshift({
            id: idFinVale,
            empresaId: v.empresaId || 'emp-1',
            empresaNome: obterNomeEmpresa(v.empresaId || 'emp-1'),
            obraId: v.obra || 'UEMG - Bloco 1',
            obraNome: v.obra || 'UEMG - Bloco 1',
            centroCustoId: 'CC-SUB-2-1',
            centroCustoCodigo: '2.1',
            centroCusto: '2.1 Salários e Remuneração',
            natureza: 'SAIDA',
            tipo: 'DESPESA',
            categoriaFinanceira: 'Mão de Obra',
            descricao: `Adiantamento / Vale Salarial — ${v.colabNome} (${v.competencia})`,
            favorecido: v.colabNome,
            valor: arred2(Number(v.valorConcedido || v.valorSolicitado || 0)),
            valorPrevisto: arred2(Number(v.valorConcedido || v.valorSolicitado || 0)),
            valorRealizado: arred2(Number(v.valorConcedido || v.valorSolicitado || 0)),
            data: v.data || '2026-11-11',
            vencimento: v.data || '2026-11-11',
            situacao: 'Pago',
            status: 'PAGO_CONFIRMADO',
            origemValeId: v.id,
            criadoPor: usuarioExecutor?.login || 'henrique'
          });
          salvarJson('cm_lancamentos_financeiros_lote2_db', window.lancamentosFinanceirosDb);
        }
        window.recalcularEAtualizarCustosOrcadoRealizadoObraFase25(v.obra);
      }
      return res;
    };
  }

  window.estornarValeConcedidoRhFase25 = function (valeId, motivo = 'Estorno de vale solicitado pelo RH') {
    const valesDb = typeof window.obterValesAdiantamentosDb === 'function' ? window.obterValesAdiantamentosDb() : [];
    const vale = valesDb.find((v) => v.id === valeId);
    if (!vale) return { sucesso: false, erro: 'Vale não localizado para estorno.' };
    if (vale.situacao === 'Cancelado') return { sucesso: false, codigo: 'VALE_JA_ESTORNADO', erro: 'Este vale já foi cancelado/estornado.' };

    vale.situacao = 'Cancelado';
    vale.motivoCancelamento = motivo;
    if (typeof window.salvarValesAdiantamentosDb === 'function') {
      window.salvarValesAdiantamentosDb(valesDb);
    }

    window.lancamentosFinanceirosDb = (window.lancamentosFinanceirosDb || []).filter((l) => l.origemValeId !== vale.id && l.id !== `FIN-VALE-${vale.id}`);
    salvarJson('cm_lancamentos_financeiros_lote2_db', window.lancamentosFinanceirosDb);

    return { sucesso: true, valeEstornado: vale };
  };

  // BUG-AUD-10: Garante geração de binário %PDF-1.4 válido em emitirHoleritePdfIndividual
  const _origEmitirHolerite = window.emitirHoleritePdfIndividual;
  if (typeof _origEmitirHolerite === 'function') {
    window.emitirHoleritePdfIndividual = function (colabIdOuNome, competenciaYm = '2026-11', dispararPrint = true) {
      const res = _origEmitirHolerite.call(this, colabIdOuNome, competenciaYm, false);
      if (!res || !res.sucesso) return res;

      const c = res.calculo;
      const nomeColab = res.holerite?.colabNome || c.colabNome || c.nome || colabIdOuNome;
      const idColab = res.holerite?.colabId || c.colabId || colabIdOuNome;
      const linhasHolerite = [
        `HOLERITE E RECIBO DE PAGAMENTO DE SALARIO - COMPETENCIA ${c.competencia}`,
        `Colaborador: ${nomeColab} (${idColab}) | Cargo: ${c.cargoFuncao} | Regime: ${c.regimePagamento}`,
        `Empresa: ${obterNomeEmpresa(c.empresaId)} | Dias Trabalhados: ${c.diasTrabalhados}d | Horas Extras: ${c.horasExtrasQtd}h`,
        '-----------------------------------------------------------------------------------------------',
        `(+) Provento Base: ${moedaBr(c.proventoBase)} | (+) Horas Extras: ${moedaBr(c.horasExtrasValor)} | (+) Outros/Beneficios: ${moedaBr(c.outrosProventosValor)}`,
        `(=) TOTAL DE PROVENTOS BRUTOS: ${moedaBr(c.totalProventos)}`,
        `(-) Faltas/Atrasos: ${moedaBr(c.faltasDescontaveisValor)} | (-) Vales/Adiantamentos: ${moedaBr(c.valesAdiantamentosValor)} | (-) INSS/IRRF: ${moedaBr((c.descontoInss || 0) + (c.descontoIrrf || 0))}`,
        `(=) VALOR LIQUIDO A RECEBER: ${moedaBr(c.liquidoReceber)}`
      ];

      if (typeof window.construirBinarioPdfA4Oficial === 'function') {
        const pdfBin = window.construirBinarioPdfA4Oficial(`HOLERITE ${nomeColab} - ${c.competencia}`, linhasHolerite, {
          documentoId: res.documentoId
        });
        res.pdfBase64 = (pdfBin.dataUri || '').split(',')[1] || '';
        res.tamanhoBytes = pdfBin.tamanhoBytes;
        window.__ultimoPdfHoleriteGerado = res;
      }

      if (dispararPrint && typeof window.abrirVisualizadorEBaixarPdfOficialA4 === 'function') {
        window.abrirVisualizadorEBaixarPdfOficialA4({
          titulo: `HOLERITE INDIVIDUAL — ${c.colabNome} (${c.competencia})`,
          nomeArquivo: `Holerite_${c.colabId}_${c.competencia}.pdf`,
          linhasPdf: linhasHolerite,
          htmlConteudo: res.htmlRenderizado
        });
      }
      return res;
    };
  }

