  window.validarPermissaoOperacional7PerfisFase25 = function (usuarioObj = obterUsuarioAtual(), opcoes = {}) {
    const nomePerfil = String(usuarioObj?.perfil || 'Master').trim();
    const cfgPerfil =
      window.MATRIZ_7_PERFIS_OPERACIONAIS_FASE25[nomePerfil] ||
      window.MATRIZ_7_PERFIS_OPERACIONAIS_FASE25.Encarregado;

    const empresasUsuario = Array.isArray(usuarioObj?.empresas)
      ? usuarioObj.empresas
      : cfgPerfil.acessoMultiEmpresaPadrao;

    // 1. Verifica isolamento de empresa
    if (opcoes.empresaAlvoId && !empresasUsuario.includes(opcoes.empresaAlvoId) && nomePerfil !== 'Master') {
      return {
        permitido: false,
        codigo: 'ISOLAMENTO_EMPRESA_BLOQUEADO',
        perfil: nomePerfil,
        erro: `Acesso bloqueado: o perfil ${nomePerfil} não possui autorização para acessar registros da empresa ${opcoes.empresaAlvoId}.`
      };
    }

    // 2. Verifica módulo permitido
    if (opcoes.modulo && !cfgPerfil.modulosPermitidos.includes(opcoes.modulo) && nomePerfil !== 'Master') {
      return {
        permitido: false,
        codigo: 'MODULO_NAO_AUTORIZADO_PARA_PERFIL',
        perfil: nomePerfil,
        erro: `Acesso bloqueado: o perfil ${nomePerfil} não possui acesso ao módulo "${opcoes.modulo}".`
      };
    }

    // 3. Verifica permissão especial
    if (opcoes.permissaoEspecial && !cfgPerfil.permissoesEspeciais[opcoes.permissaoEspecial] && nomePerfil !== 'Master') {
      return {
        permitido: false,
        codigo: 'ACAO_RESTRITA_AO_PERFIL',
        perfil: nomePerfil,
        erro: `Operação "${opcoes.permissaoEspecial}" não permitida para o perfil ${nomePerfil}.`
      };
    }

    return {
      permitido: true,
      perfil: nomePerfil,
      empresasAutorizadas: empresasUsuario,
      modulosPermitidos: cfgPerfil.modulosPermitidos,
      permissoesEspeciais: cfgPerfil.permissoesEspeciais
    };
  };

  // ============================================================================
