    if (compM <= 0) return { sucesso: false, erro: 'Informe comprimento maior que zero para o retalho/ponta.' };

    const novoRet = {
      id: dados.id || `RET-${Date.now()}-${Math.floor(Math.random() * 90 + 10)}`,
      tipo,
      modalidade: dados.modalidade || 'Serralheria',
      empresaId: dados.empresaId || 'emp-3',
      materiaPrimaId: dados.materiaPrimaId || 'PRD-MP-PERFIL-ACOS',
      descricao: dados.descricao || `Sobra reaproveitável (${compM}m)`,
      comprimentoM: compM,
      pesoKg: arred2(Number(dados.pesoKg || compM * 3.14)),
      disponivel: true,
      criadoEm: new Date().toISOString()
    };

    window.bancoRetalhosEPontasProducaoDb.unshift(novoRet);
    salvarJson('cm_banco_retalhos_pontas_producao_f25_db', window.bancoRetalhosEPontasProducaoDb);
