  // ============================================================================
  window.inventariosCegosAlmoxarifadoDb = lerJson('cm_inventarios_cegos_almoxarifado_f26_db', []);

  window.executarConferenciaInventarioCegoAlmoxarifadoFase26 = function (dadosInventario = {}, usuarioExecutor = obterUsuarioAtual()) {
    window.sincronizarEstoqueUnificadoGlobalFase23();
    const catalogo = window.catalogoProdutosMultimedidaFase22Db || [];
    const contagens = Array.isArray(dadosInventario.itensContados) ? dadosInventario.itensContados : [];

    if (contagens.length === 0) {
      return { sucesso: false, codigo: 'CONTAGEM_INVENTARIO_VAZIA', erro: 'Informe ao menos um item com a quantidade física contada.' };
    }

    const apuracaoItens = [];
    let totalDivergencias = 0;

    for (const item of contagens) {
      const qtdFisica = Number(item.quantidadeContadaFisica);
      if (!Number.isFinite(qtdFisica) || qtdFisica < 0) {
        return {
          sucesso: false,
          codigo: 'QUANTIDADE_CONTADA_NEGATIVA_OU_INVALIDA',
          erro: 'A quantidade física contada no inventário não pode ser negativa ou inválida.'
        };
      }

      const prod = catalogo.find(
        (p) => p.id === item.produtoId || p.codigoSku === item.codigoSku || p.codigoSku === item.produtoId
      );
      if (!prod) continue;

      const saldoSistemaOcultoNaContagem = arred4(Number(prod.saldoFisico || 0));
      const diferenca = arred4(qtdFisica - saldoSistemaOcultoNaContagem);
      const situacao =
        Math.abs(diferenca) < 0.001
          ? 'CONFORME'
          : diferenca > 0
          ? 'SOBRA_FISICA'
          : 'FALTA_FISICA';

      if (situacao !== 'CONFORME') totalDivergencias++;

      apuracaoItens.push({
        produtoId: prod.id,
        codigoSku: prod.codigoSku,
        nome: prod.nome,
        unidade: prod.unidadeEstoque,
        saldoSistemaPrevioOculto: saldoSistemaOcultoNaContagem,
        quantidadeContadaFisica: qtdFisica,
        diferencaApurada: diferenca,
        situacao
      });
    }

    let ajusteAplicadoNoEstoque = false;
    if (dadosInventario.aplicarAjusteAutomatico) {
      if (!ehMaster(usuarioExecutor) || !String(dadosInventario.justificativaAjuste || '').trim()) {
        return {
          sucesso: false,
          codigo: 'AJUSTE_INVENTARIO_EXIGE_MASTER_E_JUSTIFICATIVA',
          erro: 'A aplicação de ajuste de divergência de inventário no saldo físico exige autorização Master e justificativa formal.'
        };
      }

      apuracaoItens.forEach((ap) => {
        if (ap.situacao === 'CONFORME') return;
        const prod = catalogo.find((p) => p.id === ap.produtoId);
        if (prod) {
          prod.saldoFisico = ap.quantidadeContadaFisica;
        }
      });
      salvarJson('cm_catalogo_produtos_multimedida_fase22_db', catalogo);
      window.sincronizarEstoqueUnificadoGlobalFase23();
      ajusteAplicadoNoEstoque = true;
    }

    const regInv = {
      id: `INV-CEGO-${Date.now()}`,
      depositoId: dadosInventario.depositoId || 'DEP-CENTRAL',
      conferente: dadosInventario.conferente || usuarioExecutor?.nome || 'Almoxarife',
      exibiuSaldoPrevioParaConferente: false, // Contagem 100% cega!
      totalItensConferidos: apuracaoItens.length,
      totalDivergencias,
      ajusteAplicadoNoEstoque,
      itens: apuracaoItens,
      dataHora: new Date().toISOString()
    };

    window.inventariosCegosAlmoxarifadoDb.unshift(regInv);
    salvarJson('cm_inventarios_cegos_almoxarifado_f26_db', window.inventariosCegosAlmoxarifadoDb);

    return {
      sucesso: true,
      inventario: regInv
    };
  };


