  // ==========================================================================
  // 3. FREQUÊNCIA — UNIFICAR FALTAS, ATESTADOS E AUSÊNCIAS EM FONTE ÚNICA
  // ==========================================================================
  window.sincronizarBasesFaltasAtestadosEAusenciasFase28 = function () {
    const listaUnificada = Array.isArray(window.ausenciasUnificadasRhDb)
      ? window.ausenciasUnificadasRhDb
      : lerJson('cm_ausencias_unificadas_rh_estab_db', []);
    const listaAtestadosLegada = Array.isArray(window.atestadosMedicosPeriodosDb)
      ? window.atestadosMedicosPeriodosDb
      : lerJson('cm_rh_atestados_periodos_v170', []);

    const mapaPorChave = new Map();
    const gerarChave = (r) => {
      const nome = String(r.colaboradorNome || r.colaborador || '').trim().toLowerCase();
      const tipo = String(r.tipo || 'FALTA').trim().toUpperCase();
      const dtIni = String(r.dataInicio || r.data || '2026-11-10').trim();
      return `${nome}|${tipo}|${dtIni}`;
    };

    listaUnificada.forEach((r) => {
      if (!r || !(r.colaboradorNome || r.colaborador)) return;
      const tipoUp = String(r.tipo || r.tipoAusencia || 'FALTA').toUpperCase();
      const diasVal = Math.max(1, Number(r.dias || r.quantidadeDias) || 1);
      const motVal = r.cidOuMotivo || r.motivo || r.observacao || 'Registro operacional de frequência/RH';
      const norm = {
        id: r.id || `AUS-${Date.now()}-${Math.random().toString(36).slice(2, 6)}`,
        colaboradorId: r.colaboradorId || '',
        colaboradorNome: String(r.colaboradorNome || r.colaborador).trim(),
        empresa: r.empresa || r.empresaNome || 'Construtora Martins',
        empresaNome: r.empresaNome || r.empresa || 'Construtora Martins',
        obra: r.obra || 'UEMG - Bloco 1',
        tipo: tipoUp,
        tipoAusencia: tipoUp,
        dataInicio: r.dataInicio || r.data || '2026-11-10',
        dataFim: r.dataFim || r.dataInicio || r.data || '2026-11-10',
        dias: diasVal,
        quantidadeDias: diasVal,
        abonaFalta: Boolean(r.abonaFalta || tipoUp.includes('ATESTADO') || tipoUp === 'FERIAS' || tipoUp === 'FOLGA'),
        impactaCestaBasica: Boolean(r.impactaCestaBasica !== undefined ? r.impactaCestaBasica : tipoUp === 'FALTA'),
        impactaFolha: Boolean(r.impactaFolha !== undefined ? r.impactaFolha : tipoUp === 'FALTA'),
        cidOuMotivo: motVal,
        motivo: motVal,
        anexoNome: r.anexoNome || r.documentoAnexo || r.arquivoAnexo || '',
        documentoAnexo: r.documentoAnexo || r.anexoNome || '',
        situacao: r.situacao || 'Confirmado',
        status: r.status || 'Homologado'
      };
      mapaPorChave.set(gerarChave(norm), norm);
    });

    listaAtestadosLegada.forEach((a) => {
      if (!a || !(a.colaboradorNome || a.colaborador)) return;
      const tipoNorm = String(a.tipo || 'ATESTADO_MEDICO').toUpperCase().includes('FALTA') ? 'FALTA' : 'ATESTADO_MEDICO';
      const cand = {
        id: a.id || `AUS-ATEST-${Date.now()}`,
        colaboradorId: a.colaboradorId || '',
        colaboradorNome: String(a.colaboradorNome || a.colaborador).trim(),
        empresa: a.empresa || 'Construtora Martins',
        obra: a.obra || 'UEMG - Bloco 1',
        tipo: tipoNorm,
        dataInicio: a.dataInicio || a.data || '2026-11-10',
        dataFim: a.dataFim || a.dataInicio || a.data || '2026-11-10',
        dias: Math.max(1, Number(a.dias || a.qtdDias) || 1),
        abonaFalta: tipoNorm === 'ATESTADO_MEDICO' ? true : Boolean(a.abonaFalta),
        impactaCestaBasica: tipoNorm === 'FALTA' && !a.abonaFalta,
        impactaFolha: tipoNorm === 'FALTA' && !a.abonaFalta,
        cidOuMotivo: a.cidOuMotivo || a.motivo || a.cid || 'Atestado / Ocorrência sincronizada',
        anexoNome: a.anexoNome || a.arquivoNome || '',
        status: a.status || 'Homologado'
      };
      const ch = gerarChave(cand);
      if (!mapaPorChave.has(ch)) {
        mapaPorChave.set(ch, cand);
      }
    });

    const consolidada = Array.from(mapaPorChave.values());
    window.ausenciasUnificadasRhDb = consolidada;
    window.atestadosMedicosPeriodosDb = consolidada;
    salvarJson('cm_ausencias_unificadas_rh_estab_db', consolidada);
    salvarJson('cm_rh_atestados_periodos_v170', consolidada);
    return consolidada;
  };

  const _origRegistrarAusenciaEstab = window.registrarOuEditarAusenciaRhEstab;
  window.registrarOuEditarAusenciaRhEstab = function (dados = {}) {
    window.sincronizarBasesFaltasAtestadosEAusenciasFase28();
    const syncC = typeof window.sincronizarEObterColaboradoresReaisV169 === 'function'
      ? window.sincronizarEObterColaboradoresReaisV169()
      : { colaboradores: window.colaboradoresDb || [] };
    const colabs = Array.isArray(syncC?.colaboradores) ? syncC.colaboradores : [];
    const nomeBusca = String(dados.colaboradorNome || dados.colaborador || '').trim().toLowerCase();
    const colabMatch =
      colabs.find((c) => String(c.id) === String(dados.colaboradorId)) ||
      colabs.find((c) => String(c.nome || '').toLowerCase() === nomeBusca) ||
      colabs.find((c) => String(c.nome || '').toLowerCase().includes(nomeBusca));

    const payloadNorm = Object.assign({}, dados, {
      colaboradorId: dados.colaboradorId || (colabMatch ? colabMatch.id : ('COLAB-' + (nomeBusca || 'geral').replace(/[^a-z0-9]/g, '-'))),
      colaboradorNome: dados.colaboradorNome || dados.colaborador || (colabMatch ? colabMatch.nome : 'Colaborador Martins'),
      tipoAusencia: String(dados.tipoAusencia || dados.tipo || 'FALTA').toUpperCase(),
      tipo: String(dados.tipo || dados.tipoAusencia || 'FALTA').toUpperCase(),
      dataInicio: dados.dataInicio || dados.data || '2026-11-12',
      dataFim: dados.dataFim || dados.dataInicio || dados.data || '2026-11-12',
      motivo: dados.cidOuMotivo || dados.motivo || 'Registro unificado de ausência/atestado'
    });

    const res =
      typeof _origRegistrarAusenciaEstab === 'function'
        ? _origRegistrarAusenciaEstab.call(this, payloadNorm)
        : { sucesso: false };

    const regCriado = res?.registro || res?.ausencia;
    if (res && res.sucesso && regCriado) {
      regCriado.tipo = regCriado.tipo || regCriado.tipoAusencia || payloadNorm.tipo;
      regCriado.dias = regCriado.dias || regCriado.quantidadeDias || 1;
      regCriado.cidOuMotivo = regCriado.cidOuMotivo || regCriado.motivo || payloadNorm.motivo;
      regCriado.obra = regCriado.obra || payloadNorm.obra || 'UEMG - Bloco 1';
      regCriado.empresa = regCriado.empresa || regCriado.empresaNome || 'Construtora Martins';
      window.atestadosMedicosPeriodosDb = window.ausenciasUnificadasRhDb;
      salvarJson('cm_rh_atestados_periodos_v170', window.ausenciasUnificadasRhDb);
      if (typeof window.sincronizarAusenciaPeriodoNaFrequenciaDiariaFase25 === 'function') {
        try {
          window.sincronizarAusenciaPeriodoNaFrequenciaDiariaFase25(regCriado);
        } catch (e) {}
      }
      if (typeof window.renderizarSubviewAusenciasRhLote1 === 'function') {
        try { window.renderizarSubviewAusenciasRhLote1('TODOS'); } catch (e) {}
      }
    }
    return res;
  };

