  // Reconstrói a navegação unificada de Frequência e RH garantindo que:
  // - "Faltas e Atestados" e "Ausências" abram a MESMA tela unificada ("Ausências, Faltas e Atestados")
  // - "Documentos" abra EXCLUSIVAMENTE a tela de Documentos (ASO, CNH, Certificados, Contratos) sem resíduo de Ausências!
  window.abrirAbaUnificadaRhEFrequenciaV190 = function (abaId = 'ponto') {
    window.sincronizarBasesFaltasAtestadosEAusenciasFase28();

    const aliasMap = {
      'frequencia-diaria': 'ponto',
      'ponto-diario': 'ponto',
      'frequencia-coletiva': 'coletiva',
      faltas: 'ausencias',
      'faltas-atestados': 'ausencias',
      'ausencias-faltas-atestados': 'ausencias',
      historico: 'historico-freq',
      'historico-consultas': 'historico-freq'
    };
    const abaNorm = aliasMap[abaId] || abaId;
    window.abaRhUnificadaAtivaV190 = abaNorm;

    if (typeof document === 'undefined') {
      return { sucesso: true, abaAtiva: abaNorm };
    }

    if (typeof window.switchTab === 'function') {
      try { window.switchTab('colaboradores'); } catch (e) {}
    }
    const viewColab = document.getElementById('view-colaboradores');
    if (viewColab) {
      viewColab.classList.remove('hidden');
      viewColab.style.display = 'block';
    }

    // Garante que as subviews novas existam
    window.renderizarSubviewFrequenciaColetivaFase28();
    window.renderizarSubviewHistoricoConsultasFreqFase28();

    // Oculta TODAS as subviews de RH/Frequência antes de exibir apenas a selecionada
    window.TODAS_SUBVIEWS_RH_E_FREQUENCIA_FASE28.forEach((id) => {
      const el = document.getElementById(id);
      if (el) el.classList.add('hidden');
    });

    const mapaAlvo = {
      ponto: 'subview-ponto-colab',
      coletiva: 'subview-frequencia-coletiva-fase28',
      ausencias: 'subview-ausencias-colab-lote1',
      documentos: 'subview-documentos-colab-lote1',
      'historico-freq': 'subview-historico-consultas-freq-fase28',
      quadro: 'subview-quadro-colab',
      ferias: 'subview-plano-ferias-fase22',
      vales: 'subview-vales-rh-v190',
      folha: 'subview-folha-rh-v190',
      uniformes: 'subview-uniformes-colab',
      relatorios: 'subview-relatorios-colab',
      equipes: 'subview-planejamento-equipes-v190'
    };

    let targetId = mapaAlvo[abaNorm] || 'subview-ponto-colab';

    if (abaNorm === 'ausencias') {
      if (typeof window.renderizarSubviewAusenciasRhLote1 === 'function') {
        window.renderizarSubviewAusenciasRhLote1('TODOS');
      }
      targetId = 'subview-ausencias-colab-lote1';
    } else if (abaNorm === 'documentos') {
      if (typeof window.renderizarSubviewDocumentosRhLote1 === 'function') {
        window.renderizarSubviewDocumentosRhLote1(window.categoriaDocumentoColabAtivaLote1 || 'ASO');
      }
      targetId = document.getElementById('subview-documentos-colab-lote1')
        ? 'subview-documentos-colab-lote1'
        : 'subview-documentos-rh-v190';
    } else if (abaNorm === 'ferias') {
      if (typeof window.renderizarPainelPlanoDeFeriasFase22 === 'function') {
        window.renderizarPainelPlanoDeFeriasFase22();
      }
      targetId = document.getElementById('subview-plano-ferias-fase22')
        ? 'subview-plano-ferias-fase22'
        : 'subview-ferias-folgas-v190';
    }

    // Garante exclusividade absoluta: oculta tudo novamente e exibe apenas targetId
    window.TODAS_SUBVIEWS_RH_E_FREQUENCIA_FASE28.forEach((id) => {
      const el = document.getElementById(id);
      if (el) {
        if (id === targetId) {
          el.classList.remove('hidden');
          el.style.display = '';
        } else {
          el.classList.add('hidden');
        }
      }
    });

    // Atualiza cabeçalho dinâmico e barra de navegação da página de Frequência e RH (#container-abas-frequencia-rh)
    const titulosHeader = {
      ponto: ['Controle Diário de Canteiro', '1. Frequência Diária dos Funcionários Ativos', 'Lance presença, obra e apontamentos diários por colaborador'],
      coletiva: ['Apontamento em Lote por Obra e Turno', '2. Frequência Coletiva por Equipe e Turno', 'Confirme presença integral ou parcial por obra e turno (Manhã/Tarde)'],
      ausencias: ['Controle Unificado de Ocorrências', '3. Ausências, Faltas, Atestados, Folgas e Férias', 'Base unificada sincronizada com a Frequência Diária, Cesta Básica e Folha'],
      documentos: ['Prontuário e Validade Documental', '4. Documentos dos Colaboradores (ASO, CNH, Certificados e Contratos)', 'Aba exclusiva de controle documental restaurada e separada de Ausências'],
      'historico-freq': ['Consulta Consolidada', '5. Histórico e Consultas de Frequência e Ocorrências', 'Pesquise rapidamente por colaborador, obra, período e tipo de registro'],
      quadro: ['Gestão de Pessoas', 'Quadro Geral de Funcionários Ativos', 'Clique em qualquer colaborador para abrir a Ficha Individual alinhada no topo'],
      ferias: ['Recursos Humanos', 'Plano de Férias e Períodos Aquisitivos', 'Controle de vencimento e programação de férias por empresa'],
      vales: ['Financeiro RH', 'Vales e Adiantamentos Salariais', 'Concessão controlada com teto paramétrico e recibo PDF'],
      folha: ['Fechamento Mensal', 'Folha de Pagamento e Emissão de Holerites', 'Integração automática com frequência, vales e faltas'],
      uniformes: ['Segurança do Trabalho', 'Entrega de Uniformes e EPIs', 'Controle de estoque e cautelas assinadas'],
      relatorios: ['Indicadores e Exportação', 'Relatórios de Frequência, Faltas, Cesta Básica e Férias', 'Relatórios gerenciais prontos para impressão e PDF']
    };
    const infoH = titulosHeader[abaNorm] || titulosHeader.ponto;
    const elBadgeH = document.getElementById('colab-header-badge');
    const elTitH = document.getElementById('colab-header-titulo');
    const elDescH = document.getElementById('colab-header-desc');
    if (elBadgeH) elBadgeH.textContent = infoH[0];
    if (elTitH) elTitH.textContent = infoH[1];
    if (elDescH) elDescH.textContent = infoH[2];

    const navBar =
      document.querySelector('#container-abas-frequencia-rh .erp-tabs-scroll') ||
      document.getElementById('barra-abas-unificadas-rh-v190');
    if (navBar) {
      const abasPrincipaisFreq = [
        { id: 'ponto', label: '1. Frequência Diária' },
        { id: 'coletiva', label: '2. Frequência Coletiva' },
        { id: 'ausencias', label: '3. Ausências, Faltas e Atestados' },
        { id: 'documentos', label: '4. Documentos' },
        { id: 'historico-freq', label: '5. Histórico e Consultas' },
        { id: 'quadro', label: '👥 Colaboradores' },
        { id: 'ferias', label: '🏖️ Plano de Férias' },
        { id: 'vales', label: '💳 Vales' },
        { id: 'folha', label: '💰 Folha / Holerites' },
        { id: 'uniformes', label: '🦺 EPIs' },
        { id: 'relatorios', label: '📊 Relatórios RH' }
      ];
      navBar.innerHTML = abasPrincipaisFreq
        .map((ab) => {
          const isAtiva = ab.id === abaNorm;
          return `<button type="button" data-rh-tab-f28="${ab.id}" onclick="window.abrirAbaUnificadaRhEFrequenciaV190('${ab.id}')" class="min-h-[38px] px-3 py-1.5 rounded-xl font-black text-xs transition cursor-pointer ${
            isAtiva
              ? 'bg-amber-500 text-slate-950 shadow-2xs'
              : 'bg-slate-800 text-slate-200 hover:bg-slate-700'
          }">${esc(ab.label)}</button>`;
        })
        .join('');
    }

    return { sucesso: true, abaAtiva: abaNorm, subviewVisivel: targetId };
  };

