  function obterMapaMateriaisPorObraF30() {
    let mapa = lerJsonF30(STORAGE_KEYS_F30.MATERIAIS_OBRA, null);
    if (!mapa || typeof mapa !== 'object') {
      mapa = JSON.parse(JSON.stringify(SEMENTES_MATERIAIS_POR_OBRA_F30));
      salvarJsonF30(STORAGE_KEYS_F30.MATERIAIS_OBRA, mapa);
    }
    return mapa;
  }

  function salvarMapaMateriaisPorObraF30(mapa) {
    salvarJsonF30(STORAGE_KEYS_F30.MATERIAIS_OBRA, mapa);
    return mapa;
  }

  // Sincroniza materiais vindos de RDOs (cm_rdos_db) e Pedidos de Compra (cm_pedidos_compras_db) para a obra
  window.sincronizarMateriaisVindosDeRdoEPedidosParaObraFase30 = function (obraAlvoOpcional) {
    const obra = normalizarObraChaveF30(obraAlvoOpcional || obterObraSelecionadaGestaoF30());
    const mapa = obterMapaMateriaisPorObraF30();
    if (!Array.isArray(mapa[obra])) {
      mapa[obra] = [
        {
          id: `MAT-${Date.now().toString().slice(-4)}-01`,
          obra,
          descricao: `Cimento CP-II 50kg e Agregados (${obra})`,
          categoria: 'Insumos Estruturais',
          etapaCodigo: '01.01',
          etapaNome: '01. Serviços Preliminares e Estrutura',
          unidade: 'sc',
          quantidade: 50,
          precoUnitario: 36.5,
          custoTotal: 1825.0,
          origem: 'RDO / Almoxarifado da Obra',
          fornecedor: 'MG Cimentos / Almoxarifado',
          statusNaObra: 'RECEBIDO_CANTEIRO',
          marcadoPorNome: 'Gabriel Bedani',
          marcadoPorLogin: 'gabriel',
          dataHoraMarcacao: '12/11/2026 às 08:30:00',
          observacaoConferencia: 'Lote inicial alocado na obra.'
        }
      ];
    }

    const listaObra = mapa[obra];
    const idsExistentes = new Set(listaObra.map((m) => m.id));

    // 1. Inspeciona RDOs da obra que tenham materiais em texto ou estruturados
    const rdos = (typeof window.getDb === 'function' ? window.getDb() : lerJsonF30('cm_rdos_db', [])) || [];
    (Array.isArray(rdos) ? rdos : []).forEach((r) => {
      if (normalizarObraChaveF30(r.obra) !== obra) return;
      if (Array.isArray(r.materiaisObraF30)) {
        r.materiaisObraF30.forEach((m) => {
          if (m && m.id && !idsExistentes.has(m.id)) {
            listaObra.unshift(m);
            idsExistentes.add(m.id);
          }
        });
      }
      const txtMat = String(r.materiais || '').trim();
      if (txtMat) {
        const idRdoMat = `MAT-RDO-${r.id || r.num || 'DIA'}`;
        if (!idsExistentes.has(idRdoMat)) {
          listaObra.unshift({
            id: idRdoMat,
            obra,
            descricao: txtMat.length > 110 ? `${txtMat.slice(0, 110)}...` : txtMat,
            categoria: 'Material Registrado no RDO',
            etapaCodigo: '01.01',
            etapaNome: 'Registro Diário de Obra (RDO)',
            unidade: 'lote',
            quantidade: 1,
            precoUnitario: Number(r.custoEstimadoMateriaisDia || 850),
            custoTotal: Number(r.custoEstimadoMateriaisDia || 850),
            origem: `RDO Nº ${r.num || 'S/N'} (${r.data || '12/11/2026'})`,
            fornecedor: 'Canteiro de Obras / RDO',
            statusNaObra: r.statusMaterialNaObraF30 || 'RECEBIDO_CANTEIRO',
            marcadoPorNome: r.criadoPor || 'Taiane Furlan Palmiro',
            marcadoPorLogin: r.loginCriador || 'taiane',
            dataHoraMarcacao: r.dataHoraCriacao || '12/11/2026 às 08:45:00',
            observacaoConferencia: 'Enviado automaticamente pelo Diário de Obra (RDO).'
          });
          idsExistentes.add(idRdoMat);
        }
      }
    });

    // 2. Inspeciona Pedidos de Compra da obra
    const pedidos =
      (typeof window.getPedidosDb === 'function' ? window.getPedidosDb() : lerJsonF30('cm_pedidos_compras_db', [])) || [];
    (Array.isArray(pedidos) ? pedidos : []).forEach((p) => {
      if (normalizarObraChaveF30(p.obra) !== obra) return;
      const idPedMat = `MAT-PED-${p.id}`;
      if (!idsExistentes.has(idPedMat)) {
        const descPed =
          Array.isArray(p.itens) && p.itens.length > 0
            ? p.itens.map((i) => `${i.qtd} ${i.unid || 'un'} ${i.desc}`).join(', ')
            : p.descricao || 'Insumos de Pedido de Compra';
        const statusInicial =
          p.status === 'Entregue'
            ? 'RECEBIDO_CANTEIRO'
            : p.status === 'Comprado'
            ? 'AGUARDANDO_ENTREGA'
            : 'AGUARDANDO_ENTREGA';
        listaObra.push({
          id: idPedMat,
          obra,
          descricao: descPed,
          categoria: 'Suprimentos / Compras',
          etapaCodigo: '01.02',
          etapaNome: 'Suprimentos & Almoxarifado',
          unidade: 'ped',
          quantidade: 1,
          precoUnitario: Number(p.valorTotal || p.valor || 1450),
          custoTotal: Number(p.valorTotal || p.valor || 1450),
          origem: `Pedido de Compra (${p.id})`,
          fornecedor: p.fornecedor || 'Fornecedor Homologado',
          statusNaObra: statusInicial,
          marcadoPorNome: p.solicitante || 'Leonardo Abreu de Oliveira',
          marcadoPorLogin: 'leonardo',
          dataHoraMarcacao: `${p.data || '12/11/2026'} às 10:15:00`,
          observacaoConferencia: `Status em Compras: ${p.status || 'Em andamento'}`
        });
        idsExistentes.add(idPedMat);
      }
    });

    salvarMapaMateriaisPorObraF30(mapa);
    return listaObra;
  };

  window.adicionarMaterialDiretoNaObraFase30 = function (dados = {}) {
    const obra = normalizarObraChaveF30(dados.obra || obterObraSelecionadaGestaoF30());
    const mapa = obterMapaMateriaisPorObraF30();
    if (!Array.isArray(mapa[obra])) mapa[obra] = [];

    const user = obterUsuarioAtivoF30();
    const dt = formatarDataHoraBrasilia();
    const qtd = arred2(Number(dados.quantidade || 1));
    const preco = arred2(Number(dados.precoUnitario || 0));
    const custoTotal = arred2(qtd * preco);

    const novoMat = {
      id: dados.id || `MAT-F30-${Date.now().toString().slice(-5)}`,
      obra,
      descricao: String(dados.descricao || 'Material de Obra').trim(),
      categoria: dados.categoria || 'Insumos de Canteiro',
      etapaCodigo: dados.etapaCodigo || '01.01',
      etapaNome: dados.etapaNome || 'Etapa Contratual da Obra',
      unidade: dados.unidade || 'un',
      quantidade: qtd,
      precoUnitario: preco,
      custoTotal,
      origem: dados.origem || 'Lançamento Direto / RDO',
      fornecedor: dados.fornecedor || 'Fornecedor / Almoxarifado',
      statusNaObra: dados.statusNaObra || 'RECEBIDO_CANTEIRO',
      marcadoPorNome: user.nome,
      marcadoPorLogin: user.usuario,
      dataHoraMarcacao: dt.dataHoraBr,
      observacaoConferencia: dados.observacaoConferencia || 'Registrado e vinculado à gestão da obra.'
    };

    mapa[obra].unshift(novoMat);
    salvarMapaMateriaisPorObraF30(mapa);

    // Se tiver custo > 0, também sincroniza na aba Gastos da Obra (#subview-custos)
    if (custoTotal > 0 && dados.gerarGastoNaObra !== false) {
      window.registrarGastoDaObraFase30({
        obra,
        categoria: 'MATERIAIS',
        descricao: `Material na Obra: ${novoMat.descricao} (${novoMat.quantidade} ${novoMat.unidade})`,
        valor: custoTotal,
        origem: novoMat.origem,
        etapaCodigo: novoMat.etapaCodigo,
        confidencial: Boolean(dados.confidencial),
        vinculoMaterialId: novoMat.id,
        silencioso: true
      });
    }

    const acaoAudit = window.registrarAcaoComAutorEHorarioFase30({
      modulo: 'Gestão da Obra · Materiais',
      acao: `Adicionou material "${novoMat.descricao}" (${novoMat.quantidade} ${novoMat.unidade}) na obra ${obra} [${novoMat.statusNaObra}]`,
      obra,
      entidadeId: novoMat.id
    });

    if (typeof window.renderizarAbaMateriaisNaObraFase30 === 'function') {
      window.renderizarAbaMateriaisNaObraFase30(obra);
    }
    if (typeof window.AtualizarContadoresAbasGestaoFase30 === 'function') {
      window.AtualizarContadoresAbasGestaoFase30(obra);
    }

    return {
      sucesso: true,
      material: novoMat,
      auditoria: acaoAudit
    };
  };

  window.marcarStatusMaterialNaObraFase30 = function (materialId, novoStatus, opcoes = {}) {
    const obra = normalizarObraChaveF30(opcoes.obra || obterObraSelecionadaGestaoF30());
    const mapa = obterMapaMateriaisPorObraF30();
    let alvo = null;
    let obraEncontrada = obra;

    Object.keys(mapa).forEach((k) => {
      const achou = (mapa[k] || []).find((m) => m.id === materialId);
      if (achou) {
        alvo = achou;
        obraEncontrada = k;
      }
    });

    if (!alvo) {
      const listaSinc = window.sincronizarMateriaisVindosDeRdoEPedidosParaObraFase30(obra);
      alvo = listaSinc.find((m) => m.id === materialId);
    }
    if (!alvo) return { sucesso: false, erro: 'Material não localizado na obra.' };

    const user = opcoes.usuarioNome
      ? { nome: opcoes.usuarioNome, usuario: opcoes.usuarioLogin || 'henrique', perfil: opcoes.usuarioPerfil || 'Master' }
      : obterUsuarioAtivoF30();
    const dt = formatarDataHoraBrasilia();

    const statusAnterior = alvo.statusNaObra;
    alvo.statusNaObra = novoStatus;
    if (opcoes.etapaCodigo) alvo.etapaCodigo = opcoes.etapaCodigo;
    if (opcoes.observacaoConferencia) alvo.observacaoConferencia = opcoes.observacaoConferencia;
    alvo.marcadoPorNome = user.nome;
    alvo.marcadoPorLogin = user.usuario;
    alvo.dataHoraMarcacao = dt.dataHoraBr;

    if (!Array.isArray(alvo.historicoMarcacoes)) alvo.historicoMarcacoes = [];
    alvo.historicoMarcacoes.unshift({
      de: statusAnterior,
      para: novoStatus,
      etapaCodigo: alvo.etapaCodigo,
      usuarioNome: user.nome,
      usuarioLogin: user.usuario,
      dataHoraBr: dt.dataHoraBr
    });

    salvarMapaMateriaisPorObraF30(mapa);

    const rotulosStatus = {
      AGUARDANDO_ENTREGA: '⏳ Aguardando na Obra',
      RECEBIDO_CANTEIRO: '📦 Recebido no Canteiro',
      CONFERIDO_ENGENHARIA: '✅ Conferido pela Engenharia',
      APLICADO_OBRA: '🏗️ Aplicado / Consumido na Etapa',
      DIVERGENCIA_DEVOLUCAO: '⚠️ Divergência / Devolução'
    };

    const acaoAudit = window.registrarAcaoComAutorEHorarioFase30({
      modulo: 'Gestão da Obra · Marcação de Material',
      acao: `Marcou o material "${alvo.descricao}" como "${rotulosStatus[novoStatus] || novoStatus}" (Etapa ${alvo.etapaCodigo || '01.01'})`,
      obra: obraEncontrada,
      entidadeId: alvo.id,
      usuarioNome: user.nome,
      usuarioLogin: user.usuario
    });

    if (typeof window.showToast === 'function') {
      window.showToast(
        `🧱 Material marcado como "${rotulosStatus[novoStatus] || novoStatus}" por ${user.nome} às ${dt.horaBr}!`
      );
    }

    if (typeof window.renderizarAbaMateriaisNaObraFase30 === 'function') {
      window.renderizarAbaMateriaisNaObraFase30(obraEncontrada);
    }
    if (typeof window.AtualizarContadoresAbasGestaoFase30 === 'function') {
      window.AtualizarContadoresAbasGestaoFase30(obraEncontrada);
    }

    return {
      sucesso: true,
      materialId: alvo.id,
      obra: obraEncontrada,
      statusAnterior,
      novoStatus: alvo.statusNaObra,
      marcadoPorNome: alvo.marcadoPorNome,
      marcadoPorLogin: alvo.marcadoPorLogin,
      dataHoraMarcacao: alvo.dataHoraMarcacao,
      auditoria: acaoAudit
    };
  };

