  window.registrarGastoDaObraFase30 = function (dados = {}) {
    const obra = normalizarObraChaveF30(dados.obra || obterObraSelecionadaGestaoF30());
    const mapa = obterMapaGastosPorObraF30();
    if (!Array.isArray(mapa[obra])) mapa[obra] = [];

    const user = obterUsuarioAtivoF30();
    const dt = formatarDataHoraBrasilia();
    const valor = arred2(Number(dados.valor || 0));

    const novoGasto = {
      id: dados.id || `GASTO-F30-${Date.now().toString().slice(-5)}`,
      obra,
      dataBr: dados.dataBr || dt.dataBr,
      categoria: dados.categoria || 'MATERIAIS', // MATERIAIS | MAO_DE_OBRA | EQUIPAMENTOS | FINANCEIRO
      descricao: String(dados.descricao || 'Gasto operacional da obra').trim(),
      origem: dados.origem || 'Lançamento Gestão da Obra / RDO',
      etapaCodigo: dados.etapaCodigo || '01.01',
      valor,
      confidencial: Boolean(dados.confidencial),
      statusConferencia: dados.statusConferencia || 'AGUARDANDO_CONFERENCIA',
      lancadoPorNome: user.nome,
      lancadoPorLogin: user.usuario,
      dataHoraLancamento: dt.dataHoraBr,
      conferidoPorNome: dados.statusConferencia === 'CONFERIDO_GESTAO' ? user.nome : '',
      conferidoPorLogin: dados.statusConferencia === 'CONFERIDO_GESTAO' ? user.usuario : '',
      dataHoraConferencia: dados.statusConferencia === 'CONFERIDO_GESTAO' ? dt.dataHoraBr : ''
    };

    mapa[obra].unshift(novoGasto);
    salvarMapaGastosPorObraF30(mapa);

    if (!dados.silencioso) {
      window.registrarAcaoComAutorEHorarioFase30({
        modulo: 'Gestão da Obra · Gastos',
        acao: `Registrou gasto "${novoGasto.descricao}" (${moedaBr(novoGasto.valor)}) na obra ${obra}${novoGasto.confidencial ? ' [🔒 CONFIDENCIAL]' : ''}`,
        obra,
        entidadeId: novoGasto.id
      });
    }

    if (typeof window.renderizarAbaGastosDaObraFase30 === 'function') {
      window.renderizarAbaGastosDaObraFase30(obra);
    }
    if (typeof window.AtualizarContadoresAbasGestaoFase30 === 'function') {
      window.AtualizarContadoresAbasGestaoFase30(obra);
    }

    return {
      sucesso: true,
      gasto: novoGasto
    };
  };

  window.conferirGastoDaObraFase30 = function (gastoId, obraOpcional) {
    const obra = normalizarObraChaveF30(obraOpcional || obterObraSelecionadaGestaoF30());
    const mapa = obterMapaGastosPorObraF30();
    let alvo = null;
    let obraEncontrada = obra;

    Object.keys(mapa).forEach((k) => {
      const achou = (mapa[k] || []).find((g) => g.id === gastoId);
      if (achou) {
        alvo = achou;
        obraEncontrada = k;
      }
    });

    if (!alvo) return { sucesso: false, erro: 'Gasto não encontrado.' };

    const user = obterUsuarioAtivoF30();
    const dt = formatarDataHoraBrasilia();
    alvo.statusConferencia = 'CONFERIDO_GESTAO';
    alvo.conferidoPorNome = user.nome;
    alvo.conferidoPorLogin = user.usuario;
    alvo.dataHoraConferencia = dt.dataHoraBr;

    salvarMapaGastosPorObraF30(mapa);

    const audit = window.registrarAcaoComAutorEHorarioFase30({
      modulo: 'Gestão da Obra · Conferência de Gasto',
      acao: `Conferiu e validou o gasto "${alvo.descricao}" (${moedaBr(alvo.valor)}) na obra ${obraEncontrada}`,
      obra: obraEncontrada,
      entidadeId: alvo.id
    });

    if (typeof window.showToast === 'function') {
      window.showToast(`💰 Gasto conferido por ${user.nome} às ${dt.horaBr}!`);
    }

    if (typeof window.renderizarAbaGastosDaObraFase30 === 'function') {
      window.renderizarAbaGastosDaObraFase30(obraEncontrada);
    }

    return {
      sucesso: true,
      gasto: alvo,
      auditoria: audit
    };
  };

