  window.renderizarSubviewHistoricoConsultasFreqFase28 = function () {
    if (typeof document === 'undefined') return { sucesso: true };
    const viewColab = document.getElementById('view-colaboradores');
    if (!viewColab) return { sucesso: false };

    let sec = document.getElementById('subview-historico-consultas-freq-fase28');
    if (!sec) {
      sec = document.createElement('div');
      sec.id = 'subview-historico-consultas-freq-fase28';
      sec.className = 'hidden bg-white rounded-2xl p-4 border border-slate-200 shadow-2xs space-y-4';
      viewColab.appendChild(sec);
    }

    const busca = (window.__buscaHistFreq28 || '').trim().toLowerCase();
    const obraF = window.__obraHistFreq28 || 'TODAS';
    const tipoF = window.__tipoHistFreq28 || 'TODOS';

    const registrosConsolidados = [];
    const freqDb = typeof window.getFrequenciaDiariaDb === 'function' ? window.getFrequenciaDiariaDb() : lerJsonF31('cm_frequencia_diaria_db', {});
    Object.keys(freqDb || {})
      .sort()
      .reverse()
      .slice(0, 8)
      .forEach((dt) => {
        const mapaDia = freqDb[dt] || {};
        Object.values(mapaDia).forEach((r) => {
          if (!r || (!r.nome && !r.colabNome)) return;
          const st = String(r.status || '').toLowerCase();
          if (st === 'sem_apontamento') return;
          registrosConsolidados.push({
            id: 'FREQ-' + dt + '-' + (r.colabId || r.nome),
            colaboradorNome: r.colabNome || r.nome,
            obra: r.obraNome || r.obra || 'Geral / Folga',
            tipo: st === 'presente' ? 'PRESENÇA EM OBRA' : st === 'meio_periodo' ? 'MEIO PERÍODO' : st.toUpperCase(),
            dataInicio: dt,
            dataFim: dt,
            dias: 1,
            cidOuMotivo: r.obs || r.ocorrenciaObs || (st === 'presente' ? 'Alocado em ' + (r.obraNome || r.obra) + ' (' + (r.horas || 8) + 'h)' : 'Registro da Frequência Diária'),
            autor: r.inseridoPor || 'RH / Engenharia'
          });
        });
      });

    if (typeof window.sincronizarBasesFaltasAtestadosEAusenciasFase28 === 'function') {
      try { window.sincronizarBasesFaltasAtestadosEAusenciasFase28(); } catch (e) {}
    }
    (window.ausenciasUnificadasRhDb || []).forEach((a) => {
      if (!a) return;
      registrosConsolidados.push({
        id: a.id || 'AUS-' + Date.now(),
        colaboradorNome: a.colaboradorNome || a.colaborador || '-',
        obra: a.obra || 'Geral',
        tipo: a.tipo || 'FALTA_INJUSTIFICADA',
        dataInicio: a.dataInicio || a.data || '2026-11-12',
        dataFim: a.dataFim || a.dataInicio || '2026-11-12',
        dias: a.dias || a.quantidadeDias || 1,
        cidOuMotivo: a.cidOuMotivo || a.motivo || '-',
        autor: a.registradoPor || 'RH Martins'
      });
    });

    const filtradas = registrosConsolidados.filter((a) => {
      const okBusca =
        !busca ||
        String(a.colaboradorNome || '').toLowerCase().includes(busca) ||
        String(a.cidOuMotivo || '').toLowerCase().includes(busca);
      const okObra = obraF === 'TODAS' || String(a.obra || '').toLowerCase().includes(obraF.toLowerCase());
      const okTipo = tipoF === 'TODOS' || String(a.tipo || '').toUpperCase().includes(tipoF);
      return okBusca && okObra && okTipo;
    });

    const obras = [
      'UBS - Nova Passos',
      'UEMG - Bloco 1',
      'UEMG - Bloco 4',
      'Cemei - Novo Horizonte',
      'SAAE - PÁTIO DE MANUTENÇÃO',
      'UBS - Guaxupé',
      'CRAS - Alpinópolis'
    ];

    sec.innerHTML =
      '<div class="flex flex-wrap items-center justify-between gap-2 border-b border-slate-200 pb-3">' +
        '<div>' +
          '<span class="text-[10px] font-black uppercase text-amber-600 block">Frequência e Recursos Humanos · Consulta Rápida</span>' +
          '<h3 class="text-sm sm:text-base font-black text-slate-900">🔎 Histórico e Consultas de Frequência, Presenças e Ocorrências (' + filtradas.length + ' registros)</h3>' +
        '</div>' +
        '<div class="flex flex-wrap items-center gap-2">' +
          '<input type="text" id="hist-freq28-busca" value="' + esc(window.__buscaHistFreq28 || '') + '" placeholder="Buscar colaborador ou motivo..." oninput="window.__buscaHistFreq28=this.value; window.renderizarSubviewHistoricoConsultasFreqFase28();" class="min-h-[38px] border border-slate-300 rounded-xl px-3 py-1.5 text-xs bg-slate-50">' +
          '<select id="hist-freq28-obra" onchange="window.__obraHistFreq28=this.value; window.renderizarSubviewHistoricoConsultasFreqFase28();" class="min-h-[38px] border border-slate-300 rounded-xl px-2.5 py-1.5 text-xs font-bold bg-slate-50">' +
            '<option value="TODAS">Todas as Obras</option>' +
            obras.map((ob) => '<option value="' + esc(ob) + '" ' + (ob === obraF ? 'selected' : '') + '>' + esc(ob) + '</option>').join('') +
          '</select>' +
          '<select id="hist-freq28-tipo" onchange="window.__tipoHistFreq28=this.value; window.renderizarSubviewHistoricoConsultasFreqFase28();" class="min-h-[38px] border border-slate-300 rounded-xl px-2.5 py-1.5 text-xs font-bold bg-slate-50">' +
            '<option value="TODOS">Todos os Tipos</option>' +
            '<option value="PRESENÇA" ' + (tipoF === 'PRESENÇA' ? 'selected' : '') + '>Presenças em Obra</option>' +
            '<option value="FALTA" ' + (tipoF === 'FALTA' ? 'selected' : '') + '>Faltas</option>' +
            '<option value="ATESTADO" ' + (tipoF === 'ATESTADO' ? 'selected' : '') + '>Atestados Médicos</option>' +
            '<option value="FERIAS" ' + (tipoF === 'FERIAS' ? 'selected' : '') + '>Férias</option>' +
            '<option value="FOLGA" ' + (tipoF === 'FOLGA' ? 'selected' : '') + '>Folgas</option>' +
          '</select>' +
        '</div>' +
      '</div>' +
      '<div class="overflow-x-auto">' +
        '<table class="w-full text-left text-xs border-collapse">' +
          '<thead>' +
            '<tr class="bg-slate-900 text-white">' +
              '<th class="p-2.5">Colaborador</th>' +
              '<th class="p-2.5">Obra / Destino</th>' +
              '<th class="p-2.5">Tipo de Registro</th>' +
              '<th class="p-2.5">Data / Período</th>' +
              '<th class="p-2.5 text-center">Dias</th>' +
              '<th class="p-2.5">Observação / Origem</th>' +
            '</tr>' +
          '</thead>' +
          '<tbody class="divide-y divide-slate-100">' +
            filtradas
              .slice(0, 80)
              .map(
                (a) =>
                  '<tr class="hover:bg-slate-50">' +
                    '<td class="p-2.5 font-bold text-slate-900">' + esc(a.colaboradorNome) + '</td>' +
                    '<td class="p-2.5">' + esc(a.obra) + '</td>' +
                    '<td class="p-2.5"><span class="px-2 py-0.5 rounded ' + (String(a.tipo).includes('PRESENÇA') ? 'bg-emerald-100 text-emerald-900' : 'bg-amber-100 text-amber-950') + ' font-bold text-[10px]">' + esc(a.tipo) + '</span></td>' +
                    '<td class="p-2.5 font-mono">' + esc(a.dataInicio) + (a.dataFim && a.dataFim !== a.dataInicio ? ' até ' + esc(a.dataFim) : '') + '</td>' +
                    '<td class="p-2.5 text-center font-mono font-bold">' + (a.dias || 1) + '</td>' +
                    '<td class="p-2.5 text-slate-600">' + esc(a.cidOuMotivo) + '</td>' +
                  '</tr>'
              )
              .join('') +
          '</tbody>' +
        '</table>' +
      '</div>';
    return { sucesso: true, totalRegistros: filtradas.length };
  };

